package engine

import (
	"math/big"
	"time"
)

// Value is any JavaScript value produced by the interpreter or by the JSON parser.
type Value interface{}

// Undef represents the JavaScript `undefined` value.
type Undef struct{}

// Null represents the JavaScript `null` value.
type Null struct{}

// Bool is a JavaScript boolean.
type Bool bool

// Str is a JavaScript string.
type Str string

// Sym is a JavaScript symbol. Skip marks the special symbol used to signal
// that a value should not be printed.
type Sym struct {
	Desc string
	Skip bool
}

// RawNum is a number as it was written in the input document. Its literal form
// is preserved when the value is printed.
type RawNum struct {
	Raw string
	V   float64
}

// Date is a JavaScript Date object.
type Date struct {
	T     time.Time
	Valid bool
}

// Err is a JavaScript Error object.
type Err struct {
	Name    string
	Message string
	Stack   string
}

// Prop is a single object property.
type Prop struct {
	Key string
	Val Value
}

// Obj is a JavaScript object with ordered properties.
type Obj struct {
	props []Prop
	idx   map[string]int
	proto *Obj
	cls   string // internal class name, e.g. "Map", "Set", "Error", "RegExp"
}

// Arr is a JavaScript array.
type Arr struct {
	Items []Value
}

// Func is a callable value: either a native Go function or a closure.
type Func struct {
	Name    string
	Native  func(rt *Runtime, this Value, args []Value) Value
	Closure *Closure
	Proto   *Obj
}

// Closure is a user defined function.
type Closure struct {
	Node   *Node
	Scope  *Scope
	Name   string
	Params []string
	Body   []Node
	This   Value
}

// MapT is a JavaScript Map.
type MapT struct {
	Keys []Value
	Vals []Value
}

// SetT is a JavaScript Set.
type SetT struct {
	Items []Value
}

// RegExp is a JavaScript regular expression.
type RegExp struct {
	Src   string
	Flags string
}

// ArrayBuffer is a JavaScript ArrayBuffer.
type ArrayBuffer struct {
	Buf []byte
}

// TypedArray is a JavaScript typed array.
type TypedArray struct {
	Kind string
	Buf  []byte
}

// Promise is a JavaScript promise.
type Promise struct {
	State int // 0 pending, 1 fulfilled, 2 rejected
	Val   Value
}

// Proxy is a JavaScript Proxy.
type Proxy struct {
	Target  Value
	Handler *Obj
}

// NewObj creates an empty object.
func NewObj(proto *Obj) *Obj {
	return &Obj{idx: make(map[string]int), proto: proto}
}

// Set inserts or replaces a property.
func (o *Obj) Set(k string, v Value) {
	if o.idx == nil {
		o.idx = make(map[string]int)
	}
	if i, ok := o.idx[k]; ok {
		o.props[i].Val = v
		return
	}
	o.idx[k] = len(o.props)
	o.props = append(o.props, Prop{Key: k, Val: v})
}

// Get returns a property value.
func (o *Obj) Get(k string) (Value, bool) {
	if i, ok := o.idx[k]; ok {
		return o.props[i].Val, true
	}
	return nil, false
}

// Del removes a property.
func (o *Obj) Del(k string) {
	if i, ok := o.idx[k]; ok {
		o.props = append(o.props[:i], o.props[i+1:]...)
		for j := i; j < len(o.props); j++ {
			o.idx[o.props[j].Key] = j
		}
		delete(o.idx, k)
	}
}

// Keys returns the property names in order.
func (o *Obj) Keys() []string {
	ks := make([]string, len(o.props))
	for i, p := range o.props {
		ks[i] = p.Key
	}
	return ks
}

// Values returns the property values in order.
func (o *Obj) Values() []Value {
	vs := make([]Value, len(o.props))
	for i, p := range o.props {
		vs[i] = p.Val
	}
	return vs
}

// Len returns the number of properties.
func (o *Obj) Len() int { return len(o.props) }

// Pairs returns the ordered properties.
func (o *Obj) Pairs() []Prop { return o.props }

// Clone returns a shallow copy of the object.
func (o *Obj) Clone() *Obj {
	n := NewObj(o.proto)
	n.cls = o.cls
	n.props = append([]Prop(nil), o.props...)
	n.idx = make(map[string]int, len(o.props))
	for i, p := range o.props {
		n.idx[p.Key] = i
	}
	return n
}

// IsEmpty reports whether the object has no properties.
func (o *Obj) IsEmpty() bool { return len(o.props) == 0 }

// BigIntVal wraps a big integer.
type BigIntVal = big.Int
EOF
echo done"}

