package json

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"github.com/antonmedv/fx/internal/engine"
)

// Error is a document parsing error. It renders itself together with a source
// frame pointing at the offending position.
type Error struct {
	Msg  string
	Line int
	Col  int
	Src  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("%s on line %d.\n\n  %s\n  %s^\n", e.Msg, e.Line, e.Src, strings.Repeat(".", e.Col))
}

func (e *Error) Plain() string { return e.Msg }

type parser struct {
	src       []byte
	i         int  // next byte to read
	last      int  // index of the last consumed byte
	line      int  // 1 based
	lineStart int  // offset of the start of the current line
	strict    bool
}

func (p *parser) fail(msg string) error {
	return &Error{Msg: msg, Line: p.line, Col: p.last - p.lineStart, Src: p.lineText()}
}

func (p *parser) failAt(msg string, idx int) error {
	return &Error{Msg: msg, Line: p.line, Col: idx - p.lineStart, Src: p.lineText()}
}

func (p *parser) lineText() string {
	end := p.lineStart
	for end < len(p.src) && p.src[end] != '\n' {
		end++
	}
	return string(p.src[p.lineStart:end])
}

func (p *parser) peek() byte {
	if p.i < len(p.src) {
		return p.src[p.i]
	}
	return 0
}

func (p *parser) eof() bool { return p.i >= len(p.src) }

// next consumes and returns the byte at the cursor. Returns 0 at end of input.
func (p *parser) next() byte {
	if p.i >= len(p.src) {
		return 0
	}
	c := p.src[p.i]
	p.i++
	p.last = p.i - 1
	if c == '\n' {
		p.line++
		p.lineStart = p.i
	}
	return c
}

func isWS(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

// skipWS consumes whitespace and comments.
func (p *parser) skipWS() error {
	for {
		c := p.peek()
		if isWS(c) {
			p.next()
			continue
		}
		if c == '/' {
			start := p.i
			p.next()
			c2 := p.peek()
			if c2 == '/' || c2 == '*' {
				if p.strict {
					return p.fail("Comments are not allowed in strict mode")
				}
				p.next()
				if c2 == '/' {
					for !p.eof() && p.peek() != '\n' {
						p.next()
					}
				} else {
					for !p.eof() {
						if p.peek() == '*' && p.i+1 < len(p.src) && p.src[p.i+1] == '/' {
							p.next()
							p.next()
							break
						}
						p.next()
					}
				}
				continue
			}
			// not a comment, rewind
			p.i = start
			p.last = start - 1
			return nil
