	}
}

// Parse parses all values in src.
func Parse(src []byte, strict bool) ([]engine.Value, error) {
	p := &parser{src: src, last: -1, line: 1, strict: strict}
	var out []engine.Value
	for {
		if err := p.skipWS(); err != nil {
			return out, err
		}
		if p.eof() {
			return out, nil
		}
		v, err := p.value()
		if err != nil {
			return out, err
		}
		out = append(out, v)
	}
}

func (p *parser) value() (engine.Value, error) {
	c := p.peek()
	switch {
	case c == '{':
		return p.object()
	case c == '[':
		return p.array()
	case c == '"':
		return p.str()
	case c == '-' || (c >= '0' && c <= '9'):
		return p.number()
	case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'):
		return p.keyword()
	}
	p.next()
	if p.eof() {
		return nil, p.fail("Unexpected character " + quoteByte(0))
	}
	return nil, p.fail("Unexpected character " + quoteRune(c))
}

func quoteByte(b byte) string  { return strconv.QuoteRune(runeOf(b)) }
func quoteRune(c byte) string  { return strconv.QuoteRune(runeOf(c)) }
func runeOf(c byte) rune       { return rune(c) }

func (p *parser) str() (engine.Value, error) {
	p.next() // opening quote
	start := p.i
	depth := 0
	for !p.eof() {
		c := p.peek()
		if c == '\\' {
			p.next()
			continue
		}
		if c == '"' {
			break
		}
		p.next()
	}
	if p.eof() {
		return nil, p.fail("Unexpected character " + quoteByte(0))
	}
	raw := string(p.src[start:p.i])
	p.next() // closing quote
	s, err := unquote(raw)
	if err != nil {
		return nil, err
	}
	_ = depth
	return engine.Str(s), nil
}

// unquote decodes the body of a double quoted string using Go rules.
func unquote(raw string) (string, error) {
	s, err := strconv.Unquote("\"" + raw + "\"")
	if err != nil {
		return "", err
	}
	return s, nil
}

func (p *parser) number() (engine.Value, error) {
	start := p.i
	if p.peek() == '-' {
		p.next()
		if !isDigit(p.peek()) {
			return nil, p.fail("Invalid character " + quoteByte(p.peek()) + " in number")
		}
	}
	for isDigit(p.peek()) {
		p.next()
	}
	if p.peek() == '.' {
		p.next()
		if !isDigit(p.peek()) {
			return nil, p.fail("Invalid character " + quoteByte(p.peek()) + " in number")
		}
		for isDigit(p.peek()) {
			p.next()
		}
	}
	if c := p.peek(); c == 'e' || c == 'E' {
		p.next()
		if c := p.peek(); c == '+' || c == '-' {
			p.next()
		}
		if !isDigit(p.peek()) {
			return nil, p.fail("Invalid character " + quoteByte(p.peek()) + " in number")
		}
		for isDigit(p.peek()) {
			p.next()
		}
	}
	raw := string(p.src[start:p.i])
	v, err := strconv.ParseFloat(raw, 64)
	if err != nil {
		v = math.NaN()
	}
	return &engine.RawNum{Raw: raw, V: v}, nil
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

var keywords = []struct {
	name  string
	strict bool
	val   engine.Value
}{
	{"true", false, engine.Bool(true)},
	{"false", false, engine.Bool(false)},
	{"null", false, engine.Null{}},
	{"NaN", false, &engine.RawNum{Raw: "NaN", V: math.NaN()}},
	{"nan", false, &engine.RawNum{Raw: "nan", V: math.NaN()}},
	{"Infinity", false, &engine.RawNum{Raw: "Infinity", V: math.Inf(1)}},
	{"infinity", false, &engine.RawNum{Raw: "infinity", V: math.Inf(1)}},
	{"undefined", false, engine.Undef{}},
}

func (p *parser) keyword() (engine.Value, error) {
	for _, kw := range keywords {
		if p.strict && kw.name != "true" && kw.name != "false" && kw.name != "null" {
			continue
		}
		if p.i+len(kw.name) <= len(p.src) && string(p.src[p.i:p.i+len(kw.name)]) == kw.name {
			for range kw.name {
				p.next()
			}
			return kw.val, nil
		}
	}
	start := p.i
	for c := p.peek(); c >= 'a' && c <= 'z'; c = p.peek() {
		p.next()
	}
	if p.i == start {
		return nil, p.fail("Unexpected character " + quoteByte(p.peek()))
	}
	return nil, p.fail("Unexpected character " + quoteByte(p.last) + " in keyword")
}

func (p *parser) array() (engine.Value, error) {
	p.next() // [
	arr := &engine.Arr{}
	if err := p.skipWS(); err != nil {
		return nil, err
	}
	if p.peek() == ']' {
		p.next()
		return arr, nil
	}
	for {
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		v, err := p.value()
		if err != nil {
			return nil, err
		}
		arr.Items = append(arr.Items, v)
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		switch p.peek() {
		case ',':
			p.next()
			if err := p.skipWS(); err != nil {
				return nil, err
			}
			if p.peek() == ']' {
				if p.strict {
					return nil, p.fail("Trailing comma is not allowed in strict mode")
				}
				p.next()
				return arr, nil
			}
			continue
		case ']':
			p.next()
			return arr, nil
		}
		if p.eof() {
			return nil, p.fail("Invalid character " + quoteByte(0) + " in array")
		}
		p.next()
		return nil, p.fail("Invalid character " + quoteByte(p.last) + " in array")
	}
}

func (p *parser) object() (engine.Value, error) {
	p.next() // {
	obj := engine.NewObj(nil)
	if err := p.skipWS(); err != nil {
		return nil, err
	}
	if p.peek() == '}' {
		p.next()
		return obj, nil
	}
	for {
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		if p.peek() != '"' {
			if p.eof() {
				return nil, p.fail("Expected object key to be a string, got " + quoteByte(0))
			}
			c := p.next()
			return nil, p.fail("Expected object key to be a string, got " + quoteByte(c))
		}
		kv, err := p.str()
		if err != nil {
			return nil, err
		}
		key := string(kv.(engine.Str))
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		if p.peek() != ':' {
			if p.eof() {
				return nil, p.fail("Expected colon after object key, got " + quoteByte(0))
			}
			c := p.next()
			return nil, p.fail("Expected colon after object key, got " + quoteByte(c))
		}
		p.next()
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		v, err := p.value()
		if err != nil {
			return nil, err
		}
		obj.Set(key, v)
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		switch p.peek() {
		case ',':
			p.next()
			if err := p.skipWS(); err != nil {
				return nil, err
			}
			if p.peek() == '}' {
				if p.strict {
					return nil, p.fail("Trailing comma is not allowed in strict mode")
				}
				p.next()
				return obj, nil
			}
			continue
		case '}':
			p.next()
			return obj, nil
		}
		if p.eof() {
			return nil, p.fail("Unexpected character " + quoteByte(0) + " in object")
		}
		p.next()
		return nil, p.fail("Unexpected character " + quoteByte(p.last) + " in object")
	}
}

