	}
	return fmt.Sprintf("%T", v)
}

// Stringify renders v the way fx prints it. When nested is true the value is
// part of a container so strings and symbols are quoted.
func Stringify(v Value, sb *strings.Builder, nested bool) {
	switch t := v.(type) {
	case nil:
		sb.WriteString("null")
	case Undef:
		if nested {
			sb.WriteString("null")
		} else {
			sb.WriteString("undefined")
		}
	case Null:
		sb.WriteString("null")
	case Bool:
		if t {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case Str:
		if nested {
			sb.WriteString(quoteStr(string(t)))
		} else {
			sb.WriteString(string(t))
		}
	case *RawNum:
		sb.WriteString(t.Raw)
	case float64:
		sb.WriteString(NumToString(t))
	case *big.Int:
		sb.WriteString(t.String())
	case *Sym:
		if t.Skip {
			return
		}
		if nested {
			sb.WriteString(quoteStr(t.Desc))
		} else {
			sb.WriteString(t.Desc)
		}
	case *Date:
		if !t.Valid {
			if nested {
				sb.WriteString(quoteStr("Invalid Date"))
			} else {
				sb.WriteString("Invalid Date")
			}
			return
		}
		sb.WriteString("\"" + t.T.Format("2006-01-02 15:04:05 -0700 MST") + "\"")
	case *Arr:
		writeArr(t, sb, nested)
	case *Obj:
		writeObj(t, sb, nested)
	case *MapT:
		sb.WriteString("[]")
	case *SetT:
		sb.WriteString("[]")
	case *Err:
		sb.WriteString("{}")
	case *RegExp:
		sb.WriteString("{}")
	default:
		panic(&UnsupportedTypeError{Kind: typeKind(v)})
	}
}

func quoteStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		default:
			b.WriteByte(s[i])
		}
	}
	b.WriteByte('"')
	return b.String()
}

func isScalar(v Value) bool {
	switch v.(type) {
	case nil, Undef, Null, Bool, Str, float64, *big.Int, *RawNum, *Sym, *Date:
		return true
	}
	return false
}

func emptyContainer(v Value) bool {
	switch t := v.(type) {
	case *Arr:
		return len(t.Items) == 0
	case *Obj:
		return len(t.props) == 0
	}
	return false
}

func allScalar(items []Value) bool {
	for _, it := range items {
		if !isScalar(it) {
			return false
		}
	}
	return true
}

// inlineable reports whether a container value can be rendered on a single line.
func inlineable(v Value, parentIsArray bool, parentScalars bool, root bool) bool {
	if emptyContainer(v) {
		return true
	}
	if root {
		return false
	}
	switch t := v.(type) {
	case *Obj:
		if parentIsArray && !parentScalars {
			if len(t.props) > 3 {
				return false
			}
			for _, p := range t.props {
				if !isScalar(p.Val) {
					return false
				}
			}
			return true
		}
		return false
	case *Arr:
		if !allScalar(t.Items) {
			return false
		}
		if parentIsArray && parentScalars {
			return false
		}
		return true
	}
	return false
}

func writeArr(a *Arr, sb *strings.Builder, root bool) {
	if len(a.Items) == 0 {
		sb.WriteString("[]")
		return
	}
	if inlineable(a, false, false, root) {
		sb.WriteString("[ ")
		for i, it := range a.Items {
			if i > 0 {
				sb.WriteString(", ")
			}
			Stringify(it, sb, true)
		}
		sb.WriteString(" ]")
		return
	}
	sb.WriteString("[\n")
	for i, it := range a.Items {
		if i > 0 {
			sb.WriteString(",\n")
		}
		sb.WriteString("  ")
		Stringify(it, sb, true)
	}
	sb.WriteString("\n]")
}

func writeObj(o *Obj, sb *strings.Builder, root bool) {
	if len(o.props) == 0 {
		sb.WriteString("{}")
		return
	}
	sb.WriteString("{\n")
	for i, p := range o.props {
		if i > 0 {
			sb.WriteString(",\n")
		}
		sb.WriteString("  ")
		sb.WriteString(quoteStr(p.Key))
		sb.WriteString(": ")
		Stringify(p.Val, sb, true)
	}
	sb.WriteString("\n}")
}

