			b.WriteByte(s[i])
		}
	}
	b.WriteByte('"')
	return b.String()
}

func isScalar(v Value) bool {
	switch v.(type) {
	case nil, Undef, Null, Bool, Str, float64, *big.Int, *RawNum, *Sym, *Date:
		return true
	}
	return false
}

func emptyContainer(v Value) bool {
	switch t := v.(type) {
	case *Arr:
		return len(t.Items) == 0
	case *Obj:
		return len(t.props) == 0
	}
	return false
}

func allScalar(items []Value) bool {
	for _, it := range items {
		if !isScalar(it) {
			return false
		}
	}
	return true
}

// inlineable reports whether a container value can be rendered on a single line.
func inlineable(v Value, parentIsArray bool, parentScalars bool, root bool) bool {
	if emptyContainer(v) {
		return true
	}
	if root {
		return false
	}
	switch t := v.(type) {
	case *Obj:
		if parentIsArray && !parentScalars && len(t.props) <= 3 {
			for _, p := range t.props {
				if !isScalar(p.Val) {
					return false
				}
			}
			return true
		}
		return false
	case *Arr:
		if !allScalar(t.Items) {
			return false
		}
		if parentIsArray && parentScalars {
			return false
		}
		return true
	}
	return false
}

func writeArr(a *Arr, sb *strings.Builder, parentIsArray bool, parentScalars bool, root bool) {
	if inlineable(a, parentIsArray, parentScalars, root) {
		sb.WriteString("[ ")
		for i, it := range a.Items {
			if i > 0 {
				sb.WriteString(", ")
			}
			write(it, sb, false, false, false)
		}
		sb.WriteString(" ]")
		return
	}
	sb.WriteString("[\n")
	scalars := !allScalar(a.Items)
	for i, it := range a.Items {
		if i > 0 {
			sb.WriteString(",\n")
		}
		sb.WriteString("  ")
		write(it, sb, true, scalars, false)
	}
	sb.WriteString("\n]")
}

func writeObj(o *Obj, sb *strings.Builder, parentIsArray bool, parentScalars bool, root bool) {
	if inlineable(o, parentIsArray, parentScalars, root) {
		sb.WriteString("{ ")
		for i, p := range o.props {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(quoteStr(p.Key))
			sb.WriteString(": ")
			write(p.Val, sb, false, false, false)
		}
		sb.WriteString(" }")
		return
	}
	sb.WriteString("{\n")
	for i, p := range o.props {
		if i > 0 {
			sb.WriteString(",\n")
		}
		sb.WriteString("  ")
		sb.WriteString(quoteStr(p.Key))
		sb.WriteString(": ")
		write(p.Val, sb, false, false, false)
	}
	sb.WriteString("\n}")
}

// NumToString formats a float64 like JavaScript does.
func NumToString(v float64) string {
	switch {
	case v != v:
		return "NaN"
	case v > 1.7976931348623157e308:
		return "Infinity"
	case v < -1.7976931348623157e308:
		return "-Infinity"
	case v == 0:
		return "0"
	}
	neg := false
	if v < 0 {
		neg = true
		v = -v
	}
	s := strconv.FormatFloat(v, 'e', -1, 64)
	mant := s
	exp := 0
	if i := strings.IndexByte(s, 'e'); i >= 0 {
		mant = s[:i]
		e := s[i+1:]
		sign := 1
		if e[0] == '-' {
			sign = -1
			e = e[1:]
		} else if e[0] == '+' {
			e = e[1:]
		}
		exp = sign * atoi(e)
	}
	digits := strings.Replace(mant, ".", "", 1)
	// digits holds k significant digits, point position n = exp+1
	n := exp + 1
	k := len(digits)
	var out string
	switch {
	case k <= n && n <= 21:
		out = digits + strings.Repeat("0", n-k)
	case 0 < n && n <= 21:
		out = digits[:n] + "." + digits[n:]
	case -6 < n && n <= 0:
		out = "0." + strings.Repeat("0", -n) + digits
	default:
		e := n - 1
		sign := "+"
		if e < 0 {
			sign = "-"
			e = -e
		}
		if k == 1 {
			out = digits + "e" + sign + strconv.Itoa(e)
		} else {
			out = digits[:1] + "." + digits[1:] + "e" + sign + strconv.Itoa(e)
		}
	}
	if neg {
		out = "-" + out
	}
	return out
}

func atoi(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		n = n*10 + int(s[i]-'0')
	}
	return n
}
