func (l *lexer) next() Tok {
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '\n' {
			l.nline = true
			l.line++
			l.pos++
			l.lineStart = l.pos
			continue
		}
		if isWSByte(c) {
			l.pos++
			continue
		}
		if c == '/' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '/' {
			for l.pos < len(l.src) && l.src[l.pos] != '\n' {
				l.pos++
			}
			continue
		}
		if c == '/' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '*' {
			l.pos += 2
			for l.pos+1 < len(l.src) && !(l.src[l.pos] == '*' && l.src[l.pos+1] == '/') {
				if l.src[l.pos] == '\n' {
					l.nline = true
					l.line++
					l.lineStart = l.pos + 1
				}
				l.pos++
			}
			if l.pos+1 < len(l.src) {
				l.pos += 2
			}
			continue
		}
		break
	}
	line, col := l.line, l.pos-l.lineStart+1
	tok := Tok{Line: line, Col: col}
	if l.pos >= len(l.src) {
		tok.Kind = tEOF
		l.prev = tok
		return tok
	}
	c := l.src[l.pos]
	switch {
	case c == '"' || c == '\'':
		l.readString(&tok, c)
	case c == '`':
