func isWSByte(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\v' || c == '\f' }

func isIdentStart(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func (l *lexer) readString(t *Tok, q byte) {
	start := l.pos
	l.pos++
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '\\' {
			l.pos += 2
			continue
		}
		if c == '\n' {
			panic(l.errAt("Unexpected token ILLEGAL"))
		}
		if c == q {
			break
		}
		l.pos++
	}
	if l.pos >= len(l.src) {
		panic(l.errAt("Unexpected token ILLEGAL"))
	}
	raw := l.src[start+1 : l.pos]
	l.pos++
	s, err := unquoteStr(raw, q)
	if err != nil {
		panic(l.errAt("Unexpected token ILLEGAL"))
	}
	t.Kind = tStr
	t.Str = s
}

// unquoteStr decodes the body of a quoted string following Go rules.
func unquoteStr(raw string, q byte) (string, error) {
	var b strings.Builder
	i := 0
	for i < len(raw) {
		c := raw[i]
		if c != '\\' {
			b.WriteByte(c)
			i++
			continue
		}
		i++
		if i >= len(raw) {
			return "", strconv.ErrSyntax
		}
		e := raw[i]
		switch e {
		case 'n':
			b.WriteByte('\n')
			i++
		case 't':
			b.WriteByte('\t')
			i++
		case 'r':
			b.WriteByte('\r')
			i++
		case 'b':
			b.WriteByte('\b')
			i++
		case 'f':
			b.WriteByte('\f')
			i++
		case 'v':
			b.WriteByte('\v')
			i++
		case 'a':
			b.WriteByte('\a')
			i++
		case '\\':
			b.WriteByte('\\')
			i++
		case '\'':
			if q == '\'' {
				b.WriteByte('\'')
			} else {
				b.WriteByte('\'')
			}
			i++
		case '"':
			b.WriteByte('"')
			i++
		case 'x':
			if i+2 >= len(raw) {
				return "", strconv.ErrSyntax
			}
			n, err := strconv.ParseUint(raw[i+1:i+3], 16, 8)
			if err != nil {
				return "", err
			}
			b.WriteByte(byte(n))
			i += 3
		case 'u':
			if i+4 >= len(raw) {
				return "", strconv.ErrSyntax
			}
			n, err := strconv.ParseUint(raw[i+1:i+5], 16, 32)
			if err != nil {
				return "", err
			}
			b.WriteRune(rune(int(n)))
			i += 5
		case 'U':
			if i+8 >= len(raw) {
				return "", strconv.ErrSyntax
			}
			n, err := strconv.ParseUint(raw[i+1:i+9], 16, 32)
			if err != nil {
				return "", err
			}
			b.WriteRune(rune(int(n)))
			i += 9
		default:
			if e >= '0' && e <= '7' {
				if i+2 >= len(raw) || !isOct(raw[i+1]) || !isOct(raw[i+2]) {
					return "", strconv.ErrSyntax
				}
				n, err := strconv.ParseUint(raw[i:i+3], 8, 32)
				if err != nil {
					return "", err
				}
				b.WriteRune(rune(int(n)))
				i += 3
				continue
			}
			return "", strconv.ErrSyntax
		}
	}
	return b.String(), nil
}

func rune(n int) rune { return rune(n) }

func isOct(c byte) bool { return c >= '0' && c <= '7' }

func (l *lexer) readTemplate(t *Tok, line int) {
	start := l.pos + 1
	i := start
	for i < len(l.src) {
		c := l.src[i]
		if c == '\\' {
			i += 2
			continue
		}
		if c == '`' {
			break
		}
		if c == '$' && i+1 < len(l.src) && l.src[i+1] == '{' {
			// head chunk
			s, err := unquoteTpl(l.src[start:i])
			if err != nil {
				panic(l.errAt("Unexpected token ILLEGAL"))
			}
			t.Kind = tTplHead
			t.Str = s
			l.pos = i + 2
			return
		}
		if c == '\n' {
			l.line++
			l.lineStart = i + 1
		}
		i++
	}
	if i >= len(l.src) {
		panic(l.errAt("Unexpected token ILLEGAL"))
	}
	s, err := unquoteTpl(l.src[start:i])
	if err != nil {
		panic(l.errAt("Unexpected token ILLEGAL"))
	}
	t.Kind = tTpl
	t.Str = s
	l.pos = i + 1
}

// continueTemplate reads the chunk after a } inside a template.
func (l *lexer) continueTemplate(t *Tok) {
	start := l.pos
	i := start
	for i < len(l.src) {
		c := l.src[i]
		if c == '\\' {
			i += 2
			continue
		}
		if c == '`' {
			break
		}
		if c == '$' && i+1 < len(l.src) && l.src[i+1] == '{' {
			s, err := unquoteTpl(l.src[start:i])
			if err != nil {
				panic(l.errAt("Unexpected token ILLEGAL"))
			}
			t.Kind = tTplMid
			t.Str = s
			l.pos = i + 2
			return
		}
		if c == '\n' {
			l.line++
			l.lineStart = i + 1
		}
		i++
	}
	if i >= len(l.src) {
		panic(l.errAt("Unexpected token ILLEGAL"))
	}
	s, err := unquoteTpl(l.src[start:i])
	if err != nil {
		panic(l.errAt("Unexpected token ILLEGAL"))
	}
	t.Kind = tTplTail
	t.Str = s
	l.pos = i + 1
}

func unquoteTpl(raw string) (string, error) {
	return unquoteStr(raw, '`')
}

func (l *lexer) readNumber(t *Tok, line, col int) {
	start := l.pos
	if l.src[l.pos] == '0' && l.pos+1 < len(l.src) {
		switch l.src[l.pos+1] {
		case 'x', 'X':
			l.pos += 2
			for l.pos < len(l.src) && isHex(l.src[l.pos]) {
				l.pos++
			}
			n, ok := new(big.Int).SetString(l.src[start+2:l.pos], 16)
			if !ok {
				panic(l.errAt("Invalid or unexpected token"))
			}
			t.Kind = tNum
			t.Num = bigIntToFloat(n)
			return
		case 'b', 'B':
			l.pos += 2
			for l.pos < len(l.src) && (l.src[l.pos] == '0' || l.src[l.pos] == '1') {
				l.pos++
			}
			n, ok := new(big.Int).SetString(l.src[start+2:l.pos], 2)
			if !ok {
				panic(l.errAt("Invalid or unexpected token"))
			}
			t.Kind = tNum
			t.Num = bigIntToFloat(n)
			return
		case 'o', 'O':
			l.pos += 2
			for l.pos < len(l.src) && l.src[l.pos] >= '0' && l.src[l.pos] <= '7' {
				l.pos++
			}
			n, ok := new(big.Int).SetString(l.src[start+2:l.pos], 8)
			if !ok {
				panic(l.errAt("Invalid or unexpected token"))
			}
			t.Kind = tNum
			t.Num = bigIntToFloat(n)
			return
		}
	}
	for l.pos < len(l.src) && isDigitB(l.src[l.pos]) {
		l.pos++
	}
	isBig := false
	if l.pos < len(l.src) && l.src[l.pos] == '.' {
		l.pos++
		for l.pos < len(l.src) && isDigitB(l.src[l.pos]) {
			l.pos++
		}
	} else if l.pos < len(l.src) && l.src[l.pos] == 'n' {
		isBig = true
		l.pos++
	}
	if l.pos < len(l.src) && (l.src[l.pos] == 'e' || l.src[l.pos] == 'E') {
		if isBig {
			panic(l.errAt("Invalid or unexpected token"))
		}
		l.pos++
		if l.pos < len(l.src) && (l.src[l.pos] == '+' || l.src[l.pos] == '-') {
			l.pos++
		}
		if l.pos >= len(l.src) || !isDigitB(l.src[l.pos]) {
			panic(l.errAt("Unexpected token ILLEGAL"))
		}
		for l.pos < len(l.src) && isDigitB(l.src[l.pos]) {
			l.pos++
		}
	}
	text := l.src[start:l.pos]
	if isBig {
		n, ok := new(big.Int).SetString(strings.TrimSuffix(text, "n"), 10)
		if !ok {
			panic(l.errAt("Invalid or unexpected token"))
		}
		t.Kind = tBig
		t.Big = n
		return
	}
	v, err := strconv.ParseFloat(text, 64)
	if err != nil {
		panic(l.errAt("Invalid or unexpected token"))
	}
	t.Kind = tNum
	t.Num = v
}

func isHex(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
func isDigitB(c byte) bool { return c >= '0' && c <= '9' }

func bigIntToFloat(n *big.Int) float64 {
	f, _ := new(big.Float).SetInt(n).Float64()
	return f
}

func (l *lexer) readIdent(t *Tok, line, col int) {
	start := l.pos
	for l.pos < len(l.src) && isIdentPart(l.src[l.pos]) {
		l.pos++
	}
	t.Kind = tIdent
	t.Str = l.src[start:l.pos]
}

func (l *lexer) readRegex(t *Tok, line, col int) {
	// l.pos points at '/'
	start := l.pos
	l.pos++
	inClass := false
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '\\' {
			l.pos += 2
			continue
		}
		if c == '\n' {
			panic(l.errAt("Unexpected token ILLEGAL"))
		}
		if c == '[' {
			inClass = true
		} else if c == ']' {
			inClass = false
		} else if c == '/' && !inClass {
			break
		}
		l.pos++
	}
	if l.pos >= len(l.src) {
		panic(l.errAt("Invalid regular expression: missing /"))
	}
	l.pos++
	fs := ""
	for l.pos < len(l.src) && isIdentPart(l.src[l.pos]) {
		fs += string(l.src[l.pos])
		l.pos++
	}
	t.Kind = tRegex
	t.Str = l.src[start+1 : l.pos-1-len(fs)]
	t.Num = 0
	// store flags in a side field via Str suffix hack: use Big field to carry length
	t.Col = col
	l.reFlags = fs
}

