cd /workspace && cat > internal/engine/lexer.go <<'EOF'
package engine

import (
	"fmt"
	"math/big"
	"strconv"
	"strings"
)

type tokKind int

const (
	tEOF tokKind = iota
	tIdent
	tNum
	tBig
	tStr
	tTpl      // template chunk or full template without substitutions
	tTplHead  // template chunk followed by ${ (string contains the chunk)
	tTplMid   // chunk between } and ${
	tTplTail  // final chunk after }
	tRegex
	tPunct
)

type Tok struct {
	Kind tokKind
	Str  string
	Num  float64
	Big  *big.Int
	Line int
	Col  int // 1 based column
}

type SyntaxError struct {
	Msg     string
	Line    int
	Col     int
	HasPos  bool
	srcText string
}

func (e *SyntaxError) Error() string { return e.Msg }

var puncts = []string{
	">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=",
	"=>", "==", "!=", "<=", ">=", "&&", "||", "??", "?.", "++", "--", "+=", "-=",
	"*=", "/=", "%=", "&=", "|=", "^=", "**", "<<", ">>", "?.",
	"{", "}", "(", ")", "[", "]", ";", ",", ".", "<", ">", "+", "-", "*", "/", "%",
	"&", "|", "^", "!", "~", "?", ":", "=",
}

type lexer struct {
	src       string
	pos       int
	line      int
	lineStart int
	prev      Tok
	nline     bool // a newline was seen since the previous token
}

func newLexer(src string) *lexer {
	return &lexer{src: src, line: 1, lineStart: 0}
}

func (l *lexer) errAt(msg string) *SyntaxError {
	return &SyntaxError{Msg: msg, Line: l.line, Col: l.pos - l.lineStart + 1}
}

func (l *lexer) canEndExpr() bool {
	switch l.prev.Kind {
	case tEOF:
		return false
	case tIdent, tNum, tBig, tStr, tRegex, tTpl, tTplTail:
		return true
	case tPunct:
		switch l.prev.Str {
		case ")", "]", "}", "++", "--":
			return true
		}
		return false
	}
	return false
}

func (l *lexer) next() Tok {
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '\n' {
			l.nline = true
			l.line++
			l.pos++
			l.lineStart = l.pos
			continue
		}
		if isWSByte(c) {
			l.pos++
			continue
		}
		if c == '/' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '/' {
			for l.pos < len(l.src) && l.src[l.pos] != '\n' {
				l.pos++
			}
			continue
		}
		if c == '/' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '*' {
			l.pos += 2
			for l.pos+1 < len(l.src) && !(l.src[l.pos] == '*' && l.src[l.pos+1] == '/') {
				if l.src[l.pos] == '\n' {
					l.nline = true
					l.line++
					l.lineStart = l.pos + 1
				}
				l.pos++
			}
			if l.pos+1 < len(l.src) {
				l.pos += 2
			}
			continue
		}
		break
	}
	line, col := l.line, l.pos-l.lineStart+1
	tok := Tok{Line: line, Col: col}
	if l.pos >= len(l.src) {
		tok.Kind = tEOF
		l.prev = tok
		return tok
	}
	c := l.src[l.pos]
	switch {
	case c == '"' || c == '\'':
		l.readString(&tok, c)
	case c == '`':
		l.readTemplate(&tok, line)
	case c >= '0' && c <= '9':
		l.readNumber(&tok, line, col)
	case isIdentStart(c):
		l.readIdent(&tok, line, col)
	case c == '/' && !l.canEndExpr():
		l.readRegex(&tok, line, col)
	case (c == '-' || c == '+') && l.pos+1 < len(l.src) && l.src[l.pos+1] == c && l.canEndExpr():
		// handled below as punct
