// unquoteStr decodes the body of a quoted string following Go rules.
func unquoteStr(raw string, q byte) (string, error) {
	var b strings.Builder
	i := 0
	for i < len(raw) {
		c := raw[i]
		if c != '\\' {
			b.WriteByte(c)
			i++
			continue
		}
		i++
		if i >= len(raw) {
			return "", strconv.ErrSyntax
		}
		e := raw[i]
		switch e {
		case 'n':
			b.WriteByte('\n')
			i++
		case 't':
			b.WriteByte('\t')
			i++
		case 'r':
			b.WriteByte('\r')
			i++
		case 'b':
			b.WriteByte('\b')
			i++
		case 'f':
			b.WriteByte('\f')
			i++
		case 'v':
			b.WriteByte('\v')
			i++
		case 'a':
			b.WriteByte('\a')
			i++
		case '\\':
			b.WriteByte('\\')
			i++
		case '\'':
			if q == '\'' {
				b.WriteByte('\'')
			} else {
				b.WriteByte('\'')
			}
			i++
		case '"':
			b.WriteByte('"')
			i++
		case 'x':
			if i+2 >= len(raw) {
				return "", strconv.ErrSyntax
			}
			n, err := strconv.ParseUint(raw[i+1:i+3], 16, 8)
			if err != nil {
				return "", err
			}
			b.WriteByte(byte(n))
			i += 3
		case 'u':
			if i+4 >= len(raw) {
				return "", strconv.ErrSyntax
			}
			n, err := strconv.ParseUint(raw[i+1:i+5], 16, 32)
			if err != nil {
				return "", err
			}
			b.WriteRune(rune(int(n)))
			i += 5
		case 'U':
			if i+8 >= len(raw) {
				return "", strconv.ErrSyntax
			}
			n, err := strconv.ParseUint(raw[i+1:i+9], 16, 32)
			if err != nil {
				return "", err
			}
			b.WriteRune(rune(int(n)))
			i += 9
		default:
			if e >= '0' && e <= '7' {
				if i+2 >= len(raw) || !isOct(raw[i+1]) || !isOct(raw[i+2]) {
					return "", strconv.ErrSyntax
				}
				n, err := strconv.ParseUint(raw[i:i+3], 8, 32)
				if err != nil {
					return "", err
				}
				b.WriteRune(rune(int(n)))
				i += 3
				continue
			}
			return "", strconv.ErrSyntax
		}
	}
	return b.String(), nil
}

