func (l *lexer) readNumber(t *Tok, line, col int) {
	start := l.pos
	if l.src[l.pos] == '0' && l.pos+1 < len(l.src) {
		switch l.src[l.pos+1] {
		case 'x', 'X':
			l.pos += 2
			for l.pos < len(l.src) && isHex(l.src[l.pos]) {
				l.pos++
			}
			n, ok := new(big.Int).SetString(l.src[start+2:l.pos], 16)
			if !ok {
				panic(l.errAt("Invalid or unexpected token"))
			}
			t.Kind = tNum
			t.Num = bigIntToFloat(n)
			return
		case 'b', 'B':
			l.pos += 2
			for l.pos < len(l.src) && (l.src[l.pos] == '0' || l.src[l.pos] == '1') {
				l.pos++
			}
			n, ok := new(big.Int).SetString(l.src[start+2:l.pos], 2)
			if !ok {
				panic(l.errAt("Invalid or unexpected token"))
			}
			t.Kind = tNum
			t.Num = bigIntToFloat(n)
			return
		case 'o', 'O':
			l.pos += 2
			for l.pos < len(l.src) && l.src[l.pos] >= '0' && l.src[l.pos] <= '7' {
				l.pos++
			}
			n, ok := new(big.Int).SetString(l.src[start+2:l.pos], 8)
			if !ok {
				panic(l.errAt("Invalid or unexpected token"))
			}
			t.Kind = tNum
			t.Num = bigIntToFloat(n)
			return
		}
	}
	for l.pos < len(l.src) && isDigitB(l.src[l.pos]) {
		l.pos++
	}
	isBig := false
	if l.pos < len(l.src) && l.src[l.pos] == '.' {
		l.pos++
		for l.pos < len(l.src) && isDigitB(l.src[l.pos]) {
			l.pos++
		}
	} else if l.pos < len(l.src) && l.src[l.pos] == 'n' {
		isBig = true
		l.pos++
	}
	if l.pos < len(l.src) && (l.src[l.pos] == 'e' || l.src[l.pos] == 'E') {
		if isBig {
			panic(l.errAt("Invalid or unexpected token"))
		}
		l.pos++
		if l.pos < len(l.src) && (l.src[l.pos] == '+' || l.src[l.pos] == '-') {
			l.pos++
		}
		if l.pos >= len(l.src) || !isDigitB(l.src[l.pos]) {
			panic(l.errAt("Unexpected token ILLEGAL"))
		}
		for l.pos < len(l.src) && isDigitB(l.src[l.pos]) {
			l.pos++
		}
	}
	text := l.src[start:l.pos]
	if isBig {
		n, ok := new(big.Int).SetString(strings.TrimSuffix(text, "n"), 10)
		if !ok {
			panic(l.errAt("Invalid or unexpected token"))
		}
		t.Kind = tBig
		t.Big = n
		return
	}
	v, err := strconv.ParseFloat(text, 64)
	if err != nil {
		panic(l.errAt("Invalid or unexpected token"))
	}
	t.Kind = tNum
	t.Num = v
}

func isHex(c byte) bool {
