func isDigitB(c byte) bool { return c >= '0' && c <= '9' }

func bigIntToFloat(n *big.Int) float64 {
	f, _ := new(big.Float).SetInt(n).Float64()
	return f
}

func (l *lexer) readIdent(t *Tok, line, col int) {
	start := l.pos
	for l.pos < len(l.src) && isIdentPart(l.src[l.pos]) {
