func (l *lexer) readRegex(t *Tok, line, col int) {
	// l.pos points at '/'
	start := l.pos
	l.pos++
	inClass := false
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '\\' {
			l.pos += 2
			continue
		}
		if c == '\n' {
			panic(l.errAt("Unexpected token ILLEGAL"))
		}
		if c == '[' {
			inClass = true
		} else if c == ']' {
			inClass = false
		} else if c == '/' && !inClass {
			break
		}
		l.pos++
	}
	if l.pos >= len(l.src) {
		panic(l.errAt("Invalid regular expression: missing /"))
	}
	l.pos++
	fs := ""
	for l.pos < len(l.src) && isIdentPart(l.src[l.pos]) {
		fs += string(l.src[l.pos])
		l.pos++
	}
	t.Kind = tRegex
	t.Str = l.src[start+1 : l.pos-1-len(fs)]
	t.Num = 0
	// store flags in a side field via Str suffix hack: use Big field to carry length
	t.Col = col
	l.reFlags = fs
}

