	KContinue
	KSwitch
	KLabel
	KEmpty
	KDebugger
)

// Node is a generic AST node.
type Node struct {
	Kind    int
	Str     string
	Num     float64
	Big     *big.Int
	Flags   string
	Bool    bool
	Op      string
	L       *Node
	R       *Node
	X       *Node
	Y       *Node
	List    []*Node
	Strs    []string
	Line    int
	Col     int
	Compute bool
	Opt     bool
	Prefix  bool
	Async   bool
	Gen     bool
	IsDecl  bool
	Decl    bool
	Method  bool
	Tag     *Node
	Body    *Node
}

// Program is the parsed reducer.
type Program struct {
	Body []*Node
	// Strict flags detected during parsing
	Reserved []int // token indexes of let/yield used as identifiers
	LetPos   []Tok
}

type parser struct {
	l      *lexer
	look   []Tok
	p      Tok
	pi     int
	toks   []Tok
	strict []Tok // let/yield used as identifiers
}

func newParser(src string) *parser { return &parser{l: newLexer(src)} }

func (ps *parser) advance() Tok {
	t := ps.l.next()
	if t.Kind == tRegex {
		// keep flags with the token
	}
	return t
}

func (ps *parser) peek() Tok {
	for ps.pi >= len(ps.look) {
		if ps.p.Kind == tEOF {
			ps.look = append(ps.look, ps.p)
			continue
		}
		t := ps.advance()
		if t.Kind == tEOF {
			ps.p = t
		}
		ps.look = append(ps.look, t)
	}
	return ps.look[ps.pi]
}

func (ps *parser) pop() Tok {
	t := ps.peek()
	if t.Kind != tEOF {
		ps.pi++
	}
	return t
}

func (ps *parser) back() Tok {
	if ps.pi > 0 {
		ps.pi--
	}
	return ps.peek()
}

func (ps *parser) isPunct(s string) bool {
	t := ps.peek()
	return t.Kind == tPunct && t.Str == s
}

func (ps *parser) isIdent(s string) bool {
	t := ps.peek()
	return t.Kind == tIdent && t.Str == s
}

func (ps *parser) expectPunct(s string) {
	if !ps.isPunct(s) {
		ps.unexpected()
	}
	ps.pop()
}

func (ps *parser) unexpected() {
	t := ps.peek()
	switch {
	case t.Kind == tEOF:
		panic(&SyntaxError{Msg: "Unexpected token }"})
	case t.Kind == tIdent:
		switch t.Str {
		case "enum", "import", "export":
			panic(&SyntaxError{Msg: "Unexpected reserved word"})
		}
		panic(&SyntaxError{Msg: "Unexpected identifier"})
	case t.Kind == tNum:
		panic(&SyntaxError{Msg: "Unexpected number"})
	case t.Kind == tStr:
		panic(&SyntaxError{Msg: "Unexpected string"})
	case t.Kind == tRegex:
		panic(&SyntaxError{Msg: "Unexpected token ILLEGAL"})
	case t.Kind == tPunct:
		switch t.Str {
		case "import", "export":
			panic(&SyntaxError{Msg: "Unexpected reserved word"})
		case "=>":
			panic(&SyntaxError{Msg: "Unexpected token =>"})
		}
		panic(&SyntaxError{Msg: "Unexpected token " + t.Str})
	}
	panic(&SyntaxError{Msg: "Unexpected token " + t.Str})
}

// Parse parses src as an expression (or a statement list) wrapped in a return.
func Parse(src string) *Program {
	ps := newParser(src)
	body, err := parseProgram(ps)
	if err != nil {
		panic(err)
	}
	return body
}

func parseProgram(ps *parser) (*Program, error) {
	prog := &Program{}
	stmts, err := parseStatementList(ps, true)
	if err != nil {
		return nil, err
	}
	prog.Body = stmts
	prog.LetPos = ps.strict
	return prog, nil
}

func (ps *parser) semi() {
	if ps.isPunct(";") {
		ps.pop()
	}
}

// statement terminators for automatic semicolon insertion
func canEndStatement(t Tok) bool {
	switch t.Kind {
	case tEOF:
		return true
	case tPunct:
		switch t.Str {
		case "}", ";", ")":
			return true
		}
	}
	return false
}

var stmtStarters = map[string]bool{
	"var": true, "let": true, "const": true, "if": true, "for": true, "while": true,
	"do": true, "switch": true, "try": true, "throw": true, "return": true,
	"function": true, "class": true, "break": true, "continue": true, "debugger": true,
}

func (ps *parser) atStatementEnd() bool {
	t := ps.peek()
	if canEndStatement(t) {
		return true
	}
	if t.Kind == tIdent {
		if stmtStarters[t.Str] {
			return true
		}
	}
	if t.Kind == tPunct {
		// tokens that cannot continue an expression
		switch t.Str {
		case "+", "-", "*", "/", "%", "**", "<", ">", "<=", ">=", "==", "!=", "===",
			"!==", "&&", "||", "??", "&", "|", "^", "<<", ">>", ">>>", ",", "=", "+=",
			"-=", "*=", "/=", "%=", "**=", "&=", "|=", "^=", "<<=", ">>=", ">>>=",
			"&&=", "||=", "??=", "(", "[", ".", "?.", "!", "~", "++", "--", "?", "=>", "...":
			return false
		}
		return true
	}
	if t.Kind == tNum || t.Kind == tStr || t.Kind == tTpl || t.Kind == tTplHead ||
		t.Kind == tTplMid || t.Kind == tTplTail || t.Kind == tRegex {
		return true
	}
	return false
}

func parseStatementList(ps *parser, top bool) ([]*Node, error) {
	var out []*Node
	for {
		t := ps.peek()
		if t.Kind == tEOF {
			break
		}
		if t.Kind == tPunct && t.Str == "}" {
			break
		}
		st, err := parseStatement(ps)
		if err != nil {
			return nil, err
		}
		if st != nil {
			out = append(out, st)
		}
	}
	return out, nil
}

func parseStatement(ps *parser) (*Node, error) {
	t := ps.peek()
	switch {
	case t.Kind == tPunct && t.Str == ";":
		ps.pop()
		return &Node{Kind: KEmpty}, nil
	case t.Kind == tPunct && t.Str == "{":
		return parseBlock(ps)
	case t.Kind == tIdent:
		switch t.Str {
		case "var", "let", "const":
			if ps.isLetDecl() {
				return parseVarDecl(ps)
			}
		case "function":
			return parseFunctionDecl(ps)
		case "if":
			return parseIf(ps)
		case "for":
			return parseFor(ps)
		case "while":
			return parseWhile(ps)
		case "do":
			return parseDoWhile(ps)
		case "switch":
			return parseSwitch(ps)
		case "try":
			return parseTry(ps)
		case "throw":
			return parseThrow(ps)
		case "return":
			return parseReturn(ps)
		case "break":
			ps.pop()
			return &Node{Kind: KBreak}, nil
		case "continue":
			ps.pop()
			return &Node{Kind: KContinue}, nil
		case "debugger":
			ps.pop()
			ps.semi()
			return &Node{Kind: KDebugger}, nil
		}
	}
	// labelled statement?
	if ps.isLabelled() {
		return parseLabel(ps)
	}
	e, err := parseExpression(ps, false)
	if err != nil {
		return nil, err
	}
	ps.semi()
	return &Node{Kind: KExprStmt, L: e, Line: t.Line, Col: t.Col}, nil
}

func (ps *parser) isLabelled() bool {
	if ps.peek().Kind != tIdent {
		return false
	}
	// save state
	save := ps.pi
	ps.pop()
	lab := ps.peek()
	ok := lab.Kind == tPunct && lab.Str == ":"
	ps.pi = save
	return ok
}

func parseLabel(ps *parser) (*Node, error) {
	t := ps.pop()
	ps.pop() // ':'
	body, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KLabel, Str: t.Str, L: body}, nil
}

func parseBlock(ps *parser) (*Node, error) {
	ps.expectPunct("{")
	var body []*Node
	for {
		t := ps.peek()
		if t.Kind == tEOF {
			panic(&SyntaxError{Msg: "Unexpected token }"})
		}
		if t.Kind == tPunct && t.Str == "}" {
			ps.pop()
			break
		}
		st, err := parseStatement(ps)
		if err != nil {
			return nil, err
		}
		body = append(body, st)
	}
	return &Node{Kind: KBlock, List: body}, nil
}

func (ps *parser) isLetDecl() bool {
	// look at the next token
	save := ps.pi
	ps.pop()
	t := ps.peek()
	ok := false
	switch {
	case t.Kind == tIdent && !keywords[t.Str]:
		ok = true
	case t.Kind == tPunct && (t.Str == "[" || t.Str == "{"):
		ok = true
	}
	ps.pi = save
	return ok
}

func parseVarDecl(ps *parser) (*Node, error) {
	kw := ps.pop() // var/let/const
	kind := kw.Str
	if kind == "var" {
		// var is only allowed in statement position, which we are
	}
	n := &Node{Kind: KVar, Str: kind}
	for {
		pat, err := parseBindingTarget(ps)
		if err != nil {
			return nil, err
		}
		var init *Node
		if ps.isPunct("=") {
			ps.pop()
			e, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			init = e
		} else if kind == "const" {
			panic(&SyntaxError{Msg: "Missing initializer in const declaration"})
		}
		n.List = append(n.List, &Node{Kind: KAssign, L: pat, R: init})
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.semi()
	return n, nil
}

// parseBindingTarget parses a binding pattern or identifier.
func parseBindingTarget(ps *parser) (*Node, error) {
	t := ps.peek()
	if t.Kind == tIdent {
		ps.pop()
		return &Node{Kind: KIdent, Str: t.Str, Line: t.Line, Col: t.Col}, nil
	}
	if t.Kind == tPunct && t.Str == "[" {
		return parseArrayPattern(ps)
	}
	if t.Kind == tPunct && t.Str == "{" {
		return parseObjectPattern(ps)
	}
	ps.unexpected()
	return nil, nil
}

func parseArrayPattern(ps *parser) (*Node, error) {
	n := &Node{Kind: KArray}
	ps.expectPunct("[")
	for !ps.isPunct("]") {
		if ps.isPunct(",") {
			ps.pop()
			n.List = append(n.List, &Node{Kind: KEmpty})
			continue
		}
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseBindingTarget(ps)
			if err != nil {
				return nil, err
			}
			n.List = append(n.List, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
			}
			break
		}
		e, err := parseBindingTarget(ps)
		if err != nil {
			return nil, err
		}
		if ps.isPunct("=") {
			ps.pop()
			d, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			e = &Node{Kind: KAssign, L: e, R: d}
		}
		n.List = append(n.List, e)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("]")
	return n, nil
}

func parseObjectPattern(ps *parser) (*Node, error) {
	n := &Node{Kind: KObject}
	ps.expectPunct("{")
	for !ps.isPunct("}") {
		var key *Node
		shorthand := false
		t := ps.peek()
		if t.Kind == tIdent {
			ps.pop()
			key = &Node{Kind: KStr, Str: t.Str}
			shorthand = true
		} else if t.Kind == tStr {
			ps.pop()
			key = &Node{Kind: KStr, Str: t.Str}
		} else if t.Kind == tNum {
			ps.pop()
			key = &Node{Kind: KStr, Str: strconv.FormatFloat(t.Num, 'g', -1, 64)}
		} else if t.Kind == tPunct && t.Str == "[" {
			ps.pop()
			e, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct("]")
			key = e
		} else {
			ps.unexpected()
		}
		val := key
		if !shorthand || ps.isPunct(":") {
			ps.expectPunct(":")
			v, err := parseBindingTarget(ps)
			if err != nil {
				return nil, err
			}
			val = v
		}
		if ps.isPunct("=") {
			ps.pop()
			d, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			val = &Node{Kind: KAssign, L: val, R: d}
		}
		n.List = append(n.List, &Node{Kind: KObject, L: key, R: val})
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("}")
	return n, nil
}

func parseFunctionDecl(ps *parser) (*Node, error) {
	fn, err := parseFunction(ps, true, false)
	if err != nil {
		return nil, err
	}
	name := fn.Str
	decl := &Node{Kind: KVar, Str: "var"}
	decl.List = []*Node{{Kind: KAssign, L: &Node{Kind: KIdent, Str: name}, R: fn}}
	return decl, nil
}

func parseIf(ps *parser) (*Node, error) {
	ps.pop() // if
	ps.expectPunct("(")
	cond, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	then, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	var els *Node
	if ps.isIdent("else") {
		ps.pop()
		els, err = parseStatement(ps)
		if err != nil {
			return nil, err
		}
	}
	return &Node{Kind: KIf, L: cond, R: then, X: els}, nil
}

func parseFor(ps *parser) (*Node, error) {
	ps.pop() // for
	ps.expectPunct("(")
	// detect for-in / for-of
	save := ps.pi
	isIn, isOf := false, false
	var pat *Node
	if ps.peek().Kind == tIdent && (ps.peek().Str == "var" || ps.peek().Str == "let" || ps.peek().Str == "const") {
		kw := ps.pop()
		if pat, err2 := parseBindingTarget(ps); err2 != nil {
			return nil, err2
		} else {
			_ = pat
		}
	}
	_ = isIn
	_ = isOf
	_ = pat
	ps.pi = save
	// parse init
	var init *Node
	if ps.isPunct(";") {
		ps.pop()
	} else {
		if ps.peek().Kind == tIdent && (ps.peek().Str == "var" || ps.peek().Str == "let" || ps.peek().Str == "const") && ps.isVarDeclAhead() {
			d, err := parseVarDeclNoSemi(ps)
			if err != nil {
				return nil, err
			}
			init = d
		} else {
			e, err := parseExpression(ps, false)
			if err != nil {
				return nil, err
			}
			init = &Node{Kind: KExprStmt, L: e}
		}
		if ps.isIdent("in") || ps.isIdent("of") {
			of := ps.isIdent("of")
			ps.pop()
			obj, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct(")")
			body, err := parseStatement(ps)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KForIn, Op: map[bool]string{true: "of", false: "in"}[of], L: init, R: obj, X: body}, nil
		}
		ps.expectPunct(";")
	}
	var cond *Node
	if !ps.isPunct(";") {
		c, err := parseExpression(ps, true)
		if err != nil {
			return nil, err
		}
		cond = c
	}
	ps.expectPunct(";")
	var upd *Node
	if !ps.isPunct(")") {
		u, err := parseExpression(ps, false)
		if err != nil {
			return nil, err
		}
		upd = &Node{Kind: KExprStmt, L: u}
	}
	ps.expectPunct(")")
	body, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KFor, L: init, R: cond, X: upd, Y: body}, nil
}

func (ps *parser) isVarDeclAhead() bool {
	save := ps.pi
	kw := ps.pop()
	t := ps.peek()
	ok := false
	switch {
	case t.Kind == tIdent && !keywords[t.Str]:
		ok = true
	case t.Kind == tPunct && (t.Str == "[" || t.Str == "{"):
		ok = true
	}
	ps.pi = save
	_ = kw
	return ok
}

func parseVarDeclNoSemi(ps *parser) (*Node, error) {
	kw := ps.pop()
	n := &Node{Kind: KVar, Str: kw.Str}
	for {
		pat, err := parseBindingTarget(ps)
		if err != nil {
			return nil, err
		}
		var init *Node
		if ps.isPunct("=") {
			ps.pop()
			e, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			init = e
		}
		n.List = append(n.List, &Node{Kind: KAssign, L: pat, R: init})
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	return n, nil
}

func parseWhile(ps *parser) (*Node, error) {
	ps.pop()
	ps.expectPunct("(")
	c, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	b, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KWhile, L: c, R: b}, nil
}

func parseDoWhile(ps *parser) (*Node, error) {
	ps.pop()
	b, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	if !ps.isIdent("while") {
		panic(&SyntaxError{Msg: "Unexpected token while"})
	}
	ps.pop()
	ps.expectPunct("(")
	c, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	return &Node{Kind: KWhile, Op: "do", L: c, R: b}, nil
}

func parseSwitch(ps *parser) (*Node, error) {
	ps.pop()
	ps.expectPunct("(")
	d, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	ps.expectPunct("{")
	sw := &Node{Kind: KSwitch, L: d}
	for !ps.isPunct("}") {
		t := ps.peek()
		if t.Kind == tIdent && t.Str == "case" {
			ps.pop()
			c, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct(":")
			body, err := parseStatementList(ps, false)
			if err != nil {
				return nil, err
			}
			sw.List = append(sw.List, &Node{Kind: KIf, L: c, List: body})
		} else if t.Kind == tIdent && t.Str == "default" {
			ps.pop()
			ps.expectPunct(":")
			body, err := parseStatementList(ps, false)
			if err != nil {
				return nil, err
			}
			sw.List = append(sw.List, &Node{Kind: KNull, List: body})
		} else {
			ps.unexpected()
		}
	}
	ps.pop()
	return sw, nil
}

func parseTry(ps *parser) (*Node, error) {
	ps.pop()
	blk, err := parseBlock(ps)
	if err != nil {
		return nil, err
	}
	n := &Node{Kind: KTry, L: blk}
	if ps.isIdent("catch") {
		ps.pop()
		if ps.isPunct("(") {
			ps.pop()
			t := ps.pop()
			n.Str = t.Str
			ps.expectPunct(")")
		}
		cb, err := parseBlock(ps)
		if err != nil {
			return nil, err
		}
		n.R = cb
	}
	if ps.isIdent("finally") {
		ps.pop()
		fb, err := parseBlock(ps)
		if err != nil {
			return nil, err
		}
		n.X = fb
	}
	return n, nil
}

func parseThrow(ps *parser) (*Node, error) {
	ps.pop()
	e, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.semi()
	return &Node{Kind: KThrow, L: e}, nil
}

func parseReturn(ps *parser) (*Node, error) {
	ps.pop()
	if ps.isPunct(";") || canEndStatement(ps.peek()) || ps.atStatementEnd() {
		return &Node{Kind: KReturn}, nil
	}
	e, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.semi()
	return &Node{Kind: KReturn, L: e}, nil
}

func parseFunction(ps *parser, isDecl bool, isArrow bool) (*Node, error) {
	t := ps.pop() // function
	_ = t
	name := ""
	if ps.peek().Kind == tIdent {
		name = ps.pop().Str
	}
	ps.expectPunct("(")
	params, err := parseParams(ps)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	body, err := parseBlock(ps)
	if err != nil {
		return nil, err
	}
	fn := &Node{Kind: KFunc, Str: name, List: params, L: body}
	return fn, nil
}

func parseParams(ps *parser) ([]*Node, error) {
	var out []*Node
	for !ps.isPunct(")") {
		if ps.isPunct("...") {
			ps.pop()
			t := ps.pop()
			out = append(out, &Node{Kind: KSpread, Str: t.Str})
			if ps.isPunct(",") {
				ps.pop()
			}
			break
		}
		t := ps.peek()
		if t.Kind == tIdent {
			ps.pop()
			if ps.isPunct("=") {
				ps.pop()
				d, err := parseAssign(ps)
				if err != nil {
					return nil, err
				}
				out = append(out, &Node{Kind: KAssign, Str: t.Str, R: d})
				continue
			}
			out = append(out, &Node{Kind: KIdent, Str: t.Str})
		} else if t.Kind == tPunct && (t.Str == "[" || t.Str == "{") {
			pat, err := parseBindingTarget(ps)
			if err != nil {
				return nil, err
			}
			out = append(out, pat)
		} else {
			ps.unexpected()
		}
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	return out, nil
}

var _ = strings.Repeat
EOF
echo ok

function.arguments:
{"command": "cd /workspace && cat > internal/engine/parser.go <<'EOF'
package engine

import (
	"math/big"
	"strconv"
	"strings"
)

// Node kinds.
const (
	KNum = iota
	KBig
	KStr
	KTpl
	KBool
	KNull
	KThis
	KIdent
	KRegex
	KUndef
	KSuper
	KArray
	KObject
	KFunc
	KClass
	KNew
	KCall
	KMember
	KChain
	KUnary
	KUpdate
	KBinary
	KLogical
	KCond
	KAssign
	KSeq
	KSpread

	KExprStmt
	KReturn
	KBlock
	KIf
	KFor
	KForIn
	KWhile
	KTry
	KThrow
	KVar
	KBreak
	KContinue
	KSwitch
	KLabel
	KEmpty
	KDebugger
)

// Node is a generic AST node.
type Node struct {
	Kind    int
	Str     string
	Num     float64
	Big     *big.Int
	Flags   string
	Bool    bool
	Op      string
	L       *Node
	R       *Node
	X       *Node
	Y       *Node
	List    []*Node
	Strs    []string
	Line    int
	Col     int
	Compute bool
	Opt     bool
	Prefix  bool
	Async   bool
	Gen     bool
	IsDecl  bool
	Decl    bool
	Method  bool
	Tag     *Node
	Body    *Node
}

// Program is the parsed reducer.
type Program struct {
	Body []*Node
	// Strict flags detected during parsing
	Reserved []int // token indexes of let/yield used as identifiers
	LetPos   []Tok
}

type parser struct {
	l      *lexer
	look   []Tok
	p      Tok
	pi     int
	toks   []Tok
	strict []Tok // let/yield used as identifiers
}

func newParser(src string) *parser { return &parser{l: newLexer(src)} }

func (ps *parser) advance() Tok {
	t := ps.l.next()
	if t.Kind == tRegex {
		// keep flags with the token
	}
	return t
}

func (ps *parser) peek() Tok {
	for ps.pi >= len(ps.look) {
		if ps.p.Kind == tEOF {
			ps.look = append(ps.look, ps.p)
			continue
		}
		t := ps.advance()
		if t.Kind == tEOF {
			ps.p = t
		}
		ps.look = append(ps.look, t)
	}
	return ps.look[ps.pi]
}

func (ps *parser) pop() Tok {
	t := ps.peek()
	if t.Kind != tEOF {
		ps.pi++
	}
	return t
}

func (ps *parser) back() Tok {
	if ps.pi > 0 {
		ps.pi--
	}
	return ps.peek()
}

func (ps *parser) isPunct(s string) bool {
	t := ps.peek()
	return t.Kind == tPunct && t.Str == s
}

func (ps *parser) isIdent(s string) bool {
	t := ps.peek()
	return t.Kind == tIdent && t.Str == s
}

func (ps *parser) expectPunct(s string) {
	if !ps.isPunct(s) {
		ps.unexpected()
	}
	ps.pop()
}

func (ps *parser) unexpected() {
	t := ps.peek()
	switch {
	case t.Kind == tEOF:
		panic(&SyntaxError{Msg: "Unexpected token }"})
	case t.Kind == tIdent:
		switch t.Str {
		case "enum", "import", "export":
			panic(&SyntaxError{Msg: "Unexpected reserved word"})
		}
		panic(&SyntaxError{Msg: "Unexpected identifier"})
	case t.Kind == tNum:
		panic(&SyntaxError{Msg: "Unexpected number"})
	case t.Kind == tStr:
		panic(&SyntaxError{Msg: "Unexpected string"})
	case t.Kind == tRegex:
		panic(&SyntaxError{Msg: "Unexpected token ILLEGAL"})
	case t.Kind == tPunct:
		switch t.Str {
		case "import", "export":
			panic(&SyntaxError{Msg: "Unexpected reserved word"})
		case "=>":
			panic(&SyntaxError{Msg: "Unexpected token =>"})
		}
		panic(&SyntaxError{Msg: "Unexpected token " + t.Str})
	}
	panic(&SyntaxError{Msg: "Unexpected token " + t.Str})
}

// Parse parses src as an expression (or a statement list) wrapped in a return.
func Parse(src string) *Program {
	ps := newParser(src)
	body, err := parseProgram(ps)
	if err != nil {
		panic(err)
	}
	return body
}

func parseProgram(ps *parser) (*Program, error) {
	prog := &Program{}
	stmts, err := parseStatementList(ps, true)
	if err != nil {
		return nil, err
	}
	prog.Body = stmts
	prog.LetPos = ps.strict
	return prog, nil
}

func (ps *parser) semi() {
	if ps.isPunct(";") {
		ps.pop()
	}
}

// statement terminators for automatic semicolon insertion
func canEndStatement(t Tok) bool {
	switch t.Kind {
	case tEOF:
		return true
	case tPunct:
		switch t.Str {
		case "}", ";", ")":
			return true
		}
	}
	return false
}

var stmtStarters = map[string]bool{
	"var": true, "let": true, "const": true, "if": true, "for": true, "while": true,
	"do": true, "switch": true, "try": true, "throw": true, "return": true,
	"function": true, "class": true, "break": true, "continue": true, "debugger": true,
}

func (ps *parser) atStatementEnd() bool {
	t := ps.peek()
	if canEndStatement(t) {
		return true
	}
	if t.Kind == tIdent {
		if stmtStarters[t.Str] {
			return true
		}
	}
	if t.Kind == tPunct {
		// tokens that cannot continue an expression
		switch t.Str {
		case "+", "-", "*", "/", "%", "**", "<", ">", "<=", ">=", "==", "!=", "===",
			"!==", "&&", "||", "??", "&", "|", "^", "<<", ">>", ">>>", ",", "=", "+=",
			"-=", "*=", "/=", "%=", "**=", "&=", "|=", "^=", "<<=", ">>=", ">>>=",
			"&&=", "||=", "??=", "(", "[", ".", "?.", "!", "~", "++", "--", "?", "=>", "...":
			return false
		}
		return true
	}
	if t.Kind == tNum || t.Kind == tStr || t.Kind == tTpl || t.Kind == tTplHead ||
		t.Kind == tTplMid || t.Kind == tTplTail || t.Kind == tRegex {
		return true
	}
	return false
}

func parseStatementList(ps *parser, top bool) ([]*Node, error) {
	var out []*Node
	for {
		t := ps.peek()
		if t.Kind == tEOF {
			break
		}
		if t.Kind == tPunct && t.Str == "}" {
			break
		}
		st, err := parseStatement(ps)
		if err != nil {
			return nil, err
		}
		if st != nil {
			out = append(out, st)
		}
	}
	return out, nil
}

func parseStatement(ps *parser) (*Node, error) {
	t := ps.peek()
	switch {
	case t.Kind == tPunct && t.Str == ";":
		ps.pop()
		return &Node{Kind: KEmpty}, nil
	case t.Kind == tPunct && t.Str == "{":
		return parseBlock(ps)
	case t.Kind == tIdent:
		switch t.Str {
		case "var", "let", "const":
			if ps.isLetDecl() {
				return parseVarDecl(ps)
			}
		case "function":
			return parseFunctionDecl(ps)
		case "if":
			return parseIf(ps)
		case "for":
			return parseFor(ps)
		case "while":
			return parseWhile(ps)
		case "do":
			return parseDoWhile(ps)
		case "switch":
			return parseSwitch(ps)
		case "try":
			return parseTry(ps)
		case "throw":
			return parseThrow(ps)
		case "return":
			return parseReturn(ps)
		case "break":
			ps.pop()
			return &Node{Kind: KBreak}, nil
		case "continue":
			ps.pop()
			return &Node{Kind: KContinue}, nil
		case "debugger":
			ps.pop()
			ps.semi()
			return &Node{Kind: KDebugger}, nil
		}
	}
	// labelled statement?
	if ps.isLabelled() {
		return parseLabel(ps)
	}
	e, err := parseExpression(ps, false)
	if err != nil {
		return nil, err
	}
	ps.semi()
	return &Node{Kind: KExprStmt, L: e, Line: t.Line, Col: t.Col}, nil
}

func (ps *parser) isLabelled() bool {
	if ps.peek().Kind != tIdent {
		return false
	}
	// save state
	save := ps.pi
	ps.pop()
	lab := ps.peek()
	ok := lab.Kind == tPunct && lab.Str == ":"
	ps.pi = save
	return ok
}

func parseLabel(ps *parser) (*Node, error) {
	t := ps.pop()
	ps.pop() // ':'
	body, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KLabel, Str: t.Str, L: body}, nil
}

func parseBlock(ps *parser) (*Node, error) {
	ps.expectPunct("{")
	var body []*Node
	for {
		t := ps.peek()
		if t.Kind == tEOF {
			panic(&SyntaxError{Msg: "Unexpected token }"})
		}
		if t.Kind == tPunct && t.Str == "}" {
			ps.pop()
			break
		}
		st, err := parseStatement(ps)
		if err != nil {
			return nil, err
		}
		body = append(body, st)
	}
	return &Node{Kind: KBlock, List: body}, nil
}

func (ps *parser) isLetDecl() bool {
	// look at the next token
	save := ps.pi
	ps.pop()
	t := ps.peek()
	ok := false
	switch {
	case t.Kind == tIdent && !keywords[t.Str]:
		ok = true
	case t.Kind == tPunct && (t.Str == "[" || t.Str == "{"):
		ok = true
	}
	ps.pi = save
	return ok
}

func parseVarDecl(ps *parser) (*Node, error) {
	kw := ps.pop() // var/let/const
	kind := kw.Str
	if kind == "var" {
		// var is only allowed in statement position, which we are
	}
	n := &Node{Kind: KVar, Str: kind}
	for {
		pat, err := parseBindingTarget(ps)
		if err != nil {
			return nil, err
		}
		var init *Node
		if ps.isPunct("=") {
			ps.pop()
			e, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			init = e
		} else if kind == "const" {
			panic(&SyntaxError{Msg: "Missing initializer in const declaration"})
		}
		n.List = append(n.List, &Node{Kind: KAssign, L: pat, R: init})
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.semi()
	return n, nil
}

// parseBindingTarget parses a binding pattern or identifier.
func parseBindingTarget(ps *parser) (*Node, error) {
	t := ps.peek()
	if t.Kind == tIdent {
		ps.pop()
		return &Node{Kind: KIdent, Str: t.Str, Line: t.Line, Col: t.Col}, nil
	}
	if t.Kind == tPunct && t.Str == "[" {
		return parseArrayPattern(ps)
	}
	if t.Kind == tPunct && t.Str == "{" {
		return parseObjectPattern(ps)
	}
	ps.unexpected()
	return nil, nil
}

func parseArrayPattern(ps *parser) (*Node, error) {
	n := &Node{Kind: KArray}
	ps.expectPunct("[")
	for !ps.isPunct("]") {
		if ps.isPunct(",") {
			ps.pop()
			n.List = append(n.List, &Node{Kind: KEmpty})
			continue
		}
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseBindingTarget(ps)
			if err != nil {
				return nil, err
			}
			n.List = append(n.List, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
			}
			break
		}
		e, err := parseBindingTarget(ps)
		if err != nil {
			return nil, err
		}
		if ps.isPunct("=") {
			ps.pop()
			d, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			e = &Node{Kind: KAssign, L: e, R: d}
		}
		n.List = append(n.List, e)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("]")
	return n, nil
}

func parseObjectPattern(ps *parser) (*Node, error) {
	n := &Node{Kind: KObject}
	ps.expectPunct("{")
	for !ps.isPunct("}") {
		var key *Node
		shorthand := false
		t := ps.peek()
		if t.Kind == tIdent {
			ps.pop()
			key = &Node{Kind: KStr, Str: t.Str}
			shorthand = true
		} else if t.Kind == tStr {
			ps.pop()
			key = &Node{Kind: KStr, Str: t.Str}
		} else if t.Kind == tNum {
			ps.pop()
			key = &Node{Kind: KStr, Str: strconv.FormatFloat(t.Num, 'g', -1, 64)}
		} else if t.Kind == tPunct && t.Str == "[" {
			ps.pop()
			e, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct("]")
			key = e
		} else {
			ps.unexpected()
		}
		val := key
		if !shorthand || ps.isPunct(":") {
			ps.expectPunct(":")
			v, err := parseBindingTarget(ps)
			if err != nil {
				return nil, err
			}
			val = v
		}
		if ps.isPunct("=") {
			ps.pop()
			d, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			val = &Node{Kind: KAssign, L: val, R: d}
		}
		n.List = append(n.List, &Node{Kind: KObject, L: key, R: val})
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("}")
	return n, nil
}

func parseFunctionDecl(ps *parser) (*Node, error) {
	fn, err := parseFunction(ps, true, false)
	if err != nil {
		return nil, err
	}
	name := fn.Str
	decl := &Node{Kind: KVar, Str: "var"}
	decl.List = []*Node{{Kind: KAssign, L: &Node{Kind: KIdent, Str: name}, R: fn}}
	return decl, nil
}

func parseIf(ps *parser) (*Node, error) {
	ps.pop() // if
	ps.expectPunct("(")
	cond, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	then, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	var els *Node
	if ps.isIdent("else") {
		ps.pop()
		els, err = parseStatement(ps)
		if err != nil {
			return nil, err
		}
	}
	return &Node{Kind: KIf, L: cond, R: then, X: els}, nil
}

func parseFor(ps *parser) (*Node, error) {
	ps.pop() // for
	ps.expectPunct("(")
	// detect for-in / for-of
	save := ps.pi
	isIn, isOf := false, false
	var pat *Node
	if ps.peek().Kind == tIdent && (ps.peek().Str == "var" || ps.peek().Str == "let" || ps.peek().Str == "const") {
		kw := ps.pop()
		if pat, err2 := parseBindingTarget(ps); err2 != nil {
			return nil, err2
		} else {
			_ = pat
		}
	}
	_ = isIn
	_ = isOf
	_ = pat
	ps.pi = save
	// parse init
	var init *Node
	if ps.isPunct(";") {
		ps.pop()
	} else {
		if ps.peek().Kind == tIdent && (ps.peek().Str == "var" || ps.peek().Str == "let" || ps.peek().Str == "const") && ps.isVarDeclAhead() {
			d, err := parseVarDeclNoSemi(ps)
			if err != nil {
				return nil, err
			}
			init = d
		} else {
			e, err := parseExpression(ps, false)
			if err != nil {
				return nil, err
			}
			init = &Node{Kind: KExprStmt, L: e}
		}
		if ps.isIdent("in") || ps.isIdent("of") {
			of := ps.isIdent("of")
			ps.pop()
			obj, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct(")")
			body, err := parseStatement(ps)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KForIn, Op: map[bool]string{true: "of", false: "in"}[of], L: init, R: obj, X: body}, nil
		}
		ps.expectPunct(";")
	}
	var cond *Node
	if !ps.isPunct(";") {
		c, err := parseExpression(ps, true)
		if err != nil {
			return nil, err
		}
		cond = c
	}
	ps.expectPunct(";")
	var upd *Node
	if !ps.isPunct(")") {
		u, err := parseExpression(ps, false)
		if err != nil {
			return nil, err
		}
		upd = &Node{Kind: KExprStmt, L: u}
	}
	ps.expectPunct(")")
	body, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KFor, L: init, R: cond, X: upd, Y: body}, nil
}

func (ps *parser) isVarDeclAhead() bool {
	save := ps.pi
	kw := ps.pop()
	t := ps.peek()
	ok := false
	switch {
	case t.Kind == tIdent && !keywords[t.Str]:
		ok = true
	case t.Kind == tPunct && (t.Str == "[" || t.Str == "{"):
		ok = true
	}
	ps.pi = save
	_ = kw
	return ok
}

func parseVarDeclNoSemi(ps *parser) (*Node, error) {
	kw := ps.pop()
	n := &Node{Kind: KVar, Str: kw.Str}
	for {
		pat, err := parseBindingTarget(ps)
		if err != nil {
			return nil, err
		}
		var init *Node
		if ps.isPunct("=") {
			ps.pop()
			e, err := parseAssign(ps)
			if err != nil {
				return nil, err
			}
			init = e
		}
		n.List = append(n.List, &Node{Kind: KAssign, L: pat, R: init})
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	return n, nil
}

func parseWhile(ps *parser) (*Node, error) {
	ps.pop()
	ps.expectPunct("(")
	c, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	b, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KWhile, L: c, R: b}, nil
}

func parseDoWhile(ps *parser) (*Node, error) {
	ps.pop()
	b, err := parseStatement(ps)
	if err != nil {
		return nil, err
	}
	if !ps.isIdent("while") {
		panic(&SyntaxError{Msg: "Unexpected token while"})
	}
	ps.pop()
	ps.expectPunct("(")
	c, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	return &Node{Kind: KWhile, Op: "do", L: c, R: b}, nil
}

func parseSwitch(ps *parser) (*Node, error) {
	ps.pop()
	ps.expectPunct("(")
	d, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	ps.expectPunct("{")
	sw := &Node{Kind: KSwitch, L: d}
	for !ps.isPunct("}") {
		t := ps.peek()
		if t.Kind == tIdent && t.Str == "case" {
			ps.pop()
			c, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct(":")
			body, err := parseStatementList(ps, false)
			if err != nil {
				return nil, err
			}
			sw.List = append(sw.List, &Node{Kind: KIf, L: c, List: body})
		} else if t.Kind == tIdent && t.Str == "default" {
			ps.pop()
			ps.expectPunct(":")
			body, err := parseStatementList(ps, false)
			if err != nil {
				return nil, err
			}
			sw.List = append(sw.List, &Node{Kind: KNull, List: body})
		} else {
			ps.unexpected()
		}
	}
	ps.pop()
	return sw, nil
}

func parseTry(ps *parser) (*Node, error) {
	ps.pop()
	blk, err := parseBlock(ps)
	if err != nil {
		return nil, err
	}
	n := &Node{Kind: KTry, L: blk}
	if ps.isIdent("catch") {
		ps.pop()
		if ps.isPunct("(") {
			ps.pop()
			t := ps.pop()
			n.Str = t.Str
			ps.expectPunct(")")
		}
		cb, err := parseBlock(ps)
		if err != nil {
			return nil, err
		}
		n.R = cb
	}
	if ps.isIdent("finally") {
		ps.pop()
		fb, err := parseBlock(ps)
		if err != nil {
			return nil, err
		}
		n.X = fb
	}
	return n, nil
}

func parseThrow(ps *parser) (*Node, error) {
	ps.pop()
	e, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.semi()
	return &Node{Kind: KThrow, L: e}, nil
}

func parseReturn(ps *parser) (*Node, error) {
	ps.pop()
	if ps.isPunct(";") || canEndStatement(ps.peek()) || ps.atStatementEnd() {
		return &Node{Kind: KReturn}, nil
	}
	e, err := parseExpression(ps, true)
	if err != nil {
		return nil, err
	}
	ps.semi()
	return &Node{Kind: KReturn, L: e}, nil
}

func parseFunction(ps *parser, isDecl bool, isArrow bool) (*Node, error) {
	t := ps.pop() // function
	_ = t
	name := ""
	if ps.peek().Kind == tIdent {
		name = ps.pop().Str
	}
	ps.expectPunct("(")
	params, err := parseParams(ps)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	body, err := parseBlock(ps)
	if err != nil {
		return nil, err
	}
	fn := &Node{Kind: KFunc, Str: name, List: params, L: body}
	return fn, nil
}

func parseParams(ps *parser) ([]*Node, error) {
	var out []*Node
	for !ps.isPunct(")") {
		if ps.isPunct("...") {
			ps.pop()
			t := ps.pop()
			out = append(out, &Node{Kind: KSpread, Str: t.Str})
			if ps.isPunct(",") {
				ps.pop()
			}
			break
		}
		t := ps.peek()
		if t.Kind == tIdent {
			ps.pop()
			if ps.isPunct("=") {
				ps.pop()
				d, err := parseAssign(ps)
				if err != nil {
					return nil, err
				}
				out = append(out, &Node{Kind: KAssign, Str: t.Str, R: d})
				continue
			}
			out = append(out, &Node{Kind: KIdent, Str: t.Str})
		} else if t.Kind == tPunct && (t.Str == "[" || t.Str == "{") {
			pat, err := parseBindingTarget(ps)
			if err != nil {
				return nil, err
			}
			out = append(out, pat)
		} else {
			ps.unexpected()
		}
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	return out, nil
}

var _ = strings.Repeat
EOF
