actions.command:
cd /workspace && cat > internal/engine/expr.go <<'EOF'
package engine

import (
	"math/big"
	"strconv"
)

type saveState struct {
	pi        int
	look      []Tok
	lpos      int
	lline     int
	lstart    int
	lprev     Tok
	lnline    bool
}

func (ps *parser) save() saveState {
	return saveState{pi: ps.pi, look: append([]Tok(nil), ps.look...), lpos: ps.l.pos,
		lline: ps.l.line, lstart: ps.l.lineStart, lprev: ps.l.prev, lnline: ps.l.nline}
}

func (ps *parser) restore(s saveState) {
	ps.pi = s.pi
	ps.look = s.look
	ps.l.pos = s.lpos
	ps.l.line = s.lline
	ps.l.lineStart = s.lstart
	ps.l.prev = s.lprev
	ps.l.nline = s.lnline
}

// parseExpression parses a sequence expression.
func parseExpression(ps *parser, noIn bool) (*Node, error) {
	e, err := parseAssign(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct(",") {
		ps.pop()
		r, err := parseAssign(ps, noIn)
		if err != nil {
			return nil, err
		}
		if e.Kind != KSeq {
			e = &Node{Kind: KSeq, List: []*Node{e}}
		}
		e.List = append(e.List, r)
	}
	return e, nil
}

func (ps *parser) tryArrow() (*Node, bool) {
	st := ps.save()
	var params []*Node
	async := false
	if ps.isIdent("async") {
		// async arrow only when not followed by a newline and next is not => etc
		save := ps.pi
		ps.pop()
		if ps.isPunct("(") || (ps.peek().Kind == tIdent && !keywords[ps.peek().Str]) {
			async = true
		} else {
			ps.pi = save
		}
	}
	ok := true
	if ps.isPunct("(") {
		ps.pop()
		var err error
		params, err = parseParams(ps)
		if err != nil {
			ok = false
		} else if !ps.isPunct(")") {
			ok = false
		} else {
			ps.pop()
		}
	} else if ps.peek().Kind == tIdent {
		t := ps.pop()
		params = []*Node{&Node{Kind: KIdent, Str: t.Str}}
	} else {
		ok = false
	}
	if ok {
		if ps.isPunct("=>") {
			ps.pop()
			body, err := parseArrowBody(ps)
			if err != nil {
				return nil, false
			}
			fn := &Node{Kind: KFunc, List: params, L: body, Async: async, Gen: false, Body: body}
			return fn, true
		}
	}
	ps.restore(st)
	return nil, false
}

func parseArrowBody(ps *parser) (*Node, error) {
	if ps.isPunct("{") {
		b, err := parseBlock(ps)
		if err != nil {
			return nil, err
		}
		return b, nil
	}
	e, err := parseAssign(ps, false)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KReturn, L: e}, nil
}

func parseAssign(ps *parser, noIn bool) (*Node, error) {
	if fn, ok := ps.tryArrow(); ok {
		return fn, nil
	}
	l, err := parseCond(ps, noIn)
	if err != nil {
		return nil, err
	}
	t := ps.peek()
	if t.Kind == tPunct {
		switch t.Str {
		case "=", "+=", "-=", "*=", "/=", "%=", "**=", "<<=", ">>=", ">>>=", "&=", "|=", "^=", "&&=", "||=", "??=":
			if !isValidAssignTarget(l) {
				panic(&SyntaxError{Msg: "Invalid left-hand side in assignment "})
			}
			ps.pop()
			r, err := parseAssign(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KAssign, Op: t.Str, L: l, R: r}, nil
		}
	}
	return l, nil
}

func isValidAssignTarget(n *Node) bool {
	switch n.Kind {
	case KIdent, KMember, KThis:
		return true
	case KArray, KObject:
		return true
	}
	return false
}

func parseCond(ps *parser, noIn bool) (*Node, error) {
	c, err := parseCoalesce(ps, noIn)
	if err != nil {
		return nil, err
	}
	if ps.isPunct("?") {
		ps.pop()
		t, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		ps.expectPunct(":")
		f, err := parseAssign(ps, noIn)
		if err != nil {
			return nil, err
		}
		return &Node{Kind: KCond, L: c, R: t, X: f}, nil
	}
	return c, nil
}

func parseCoalesce(ps *parser, noIn bool) (*Node, error) {
	l, err := parseOr(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("??") {
		ps.pop()
		r, err := parseOr(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KLogical, Op: "??", L: l, R: r}
	}
	return l, nil
}

func parseOr(ps *parser, noIn bool) (*Node, error) {
	l, err := parseAnd(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("||") {
		ps.pop()
		r, err := parseAnd(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KLogical, Op: "||", L: l, R: r}
	}
	return l, nil
}

func parseAnd(ps *parser, noIn bool) (*Node, error) {
	l, err := parseBitOr(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("&&") {
		ps.pop()
		r, err := parseBitOr(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KLogical, Op: "&&", L: l, R: r}
	}
	return l, nil
}

func parseBitOr(ps *parser, noIn bool) (*Node, error) {
	l, err := parseBitXor(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("|") {
		ps.pop()
		r, err := parseBitXor(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KBinary, Op: "|", L: l, R: r}
	}
	return l, nil
}

func parseBitXor(ps *parser, noIn bool) (*Node, error) {
	l, err := parseBitAnd(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("^") {
		ps.pop()
		r, err := parseBitAnd(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KBinary, Op: "^", L: l, R: r}
	}
	return l, nil
}

func parseBitAnd(ps *parser, noIn bool) (*Node, error) {
	l, err := parseEquality(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("&") {
		ps.pop()
		r, err := parseEquality(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KBinary, Op: "&", L: l, R: r}
	}
	return l, nil
}

func parseEquality(ps *parser, noIn bool) (*Node, error) {
	l, err := parseRelational(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		switch t.Str {
		case "==", "!=", "===", "!==":
			ps.pop()
			r, err := parseRelational(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseRelational(ps *parser, noIn bool) (*Node, error) {
	l, err := parseShift(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind == tPunct {
			switch t.Str {
			case "<", ">", "<=", ">=":
				ps.pop()
				r, err := parseShift(ps, noIn)
				if err != nil {
					return nil, err
				}
				l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
				continue
			}
		} else if t.Kind == tIdent {
			if t.Str == "instanceof" {
				ps.pop()
				r, err := parseShift(ps, noIn)
				if err != nil {
					return nil, err
				}
				l = &Node{Kind: KBinary, Op: "instanceof", L: l, R: r}
				continue
			}
			if t.Str == "in" && !noIn {
				ps.pop()
				r, err := parseShift(ps, noIn)
				if err != nil {
					return nil, err
				}
				l = &Node{Kind: KBinary, Op: "in", L: l, R: r}
				continue
			}
		}
		break
	}
	return l, nil
}

func parseShift(ps *parser, noIn bool) (*Node, error) {
	l, err := parseAdditive(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		switch t.Str {
		case "<<", ">>", ">>>":
			ps.pop()
			r, err := parseAdditive(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseAdditive(ps *parser, noIn bool) (*Node, error) {
	l, err := parseMultiplicative(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		if t.Str == "+" || t.Str == "-" {
			ps.pop()
			r, err := parseMultiplicative(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseMultiplicative(ps *parser, noIn bool) (*Node, error) {
	l, err := parseExponent(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		if t.Str == "*" || t.Str == "/" || t.Str == "%" {
			ps.pop()
			r, err := parseExponent(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseExponent(ps *parser, noIn bool) (*Node, error) {
	l, err := parseUnary(ps, noIn)
	if err != nil {
		return nil, err
	}
	if ps.isPunct("**") {
		ps.pop()
		r, err := parseExponent(ps, noIn)
		if err != nil {
			return nil, err
		}
		return &Node{Kind: KBinary, Op: "**", L: l, R: r}, nil
	}
	return l, nil
}

func parseUnary(ps *parser, noIn bool) (*Node, error) {
	t := ps.peek()
	if t.Kind == tPunct {
		switch t.Str {
		case "+", "-", "~", "!":
			ps.pop()
			a, err := parseUnary(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KUnary, Op: t.Str, L: a, Line: t.Line, Col: t.Col}, nil
		}
	} else if t.Kind == tIdent {
		switch t.Str {
		case "typeof", "void", "delete":
			ps.pop()
			a, err := parseUnary(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KUnary, Op: t.Str, L: a, Line: t.Line, Col: t.Col}, nil
		case "await":
			ps.pop()
			a, err := parseUnary(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KUnary, Op: "await", L: a}, nil
		}
	}
	return parsePostfix(ps, noIn)
}

func parsePostfix(ps *parser, noIn bool) (*Node, error) {
	e, err := parseCallChain(ps, noIn)
	if err != nil {
		return nil, err
	}
	t := ps.peek()
	if t.Kind == tPunct && (t.Str == "++" || t.Str == "--") && !t.NL {
		ps.pop()
		return &Node{Kind: KUpdate, Op: t.Str, L: e, Prefix: false, Line: t.Line, Col: t.Col}, nil
	}
	return e, nil
}

func parseCallChain(ps *parser, noIn bool) (*Node, error) {
	var e *Node
	t := ps.peek()
	if t.Kind == tIdent && t.Str == "new" {
		ps.pop()
		callee, err := parseCallChain(ps, noIn)
		if err != nil {
			return nil, err
		}
		args := []*Node{}
		if ps.isPunct("(") {
			ps.pop()
			var err error
			args, err = parseArgs(ps)
			if err != nil {
				return nil, err
			}
		}
		e = &Node{Kind: KNew, L: callee, List: args, Line: t.Line, Col: t.Col}
	} else {
		var err error
		e, err = parsePrimary(ps, noIn)
		if err != nil {
			return nil, err
		}
	}
	for {
		t := ps.peek()
		if t.Kind == tPunct && t.Str == "." {
			ps.pop()
			k := ps.pop()
			if k.Kind != tIdent {
				ps.unexpected()
			}
			e = &Node{Kind: KMember, L: e, Str: k.Str, Line: k.Line, Col: k.Col}
			continue
		}
		if t.Kind == tPunct && (t.Str == "?." ) {
			ps.pop()
			if ps.isPunct("(") {
				ps.pop()
				args, err := parseArgs(ps)
				if err != nil {
					return nil, err
				}
				e = &Node{Kind: KCall, L: e, List: args, Opt: true, Line: t.Line, Col: t.Col}
				continue
			}
			if ps.isPunct("[") {
				ps.pop()
				k, err := parseExpression(ps, true)
				if err != nil {
					return nil, err
				}
				ps.expectPunct("]")
				e = &Node{Kind: KMember, L: e, X: k, Compute: true, Opt: true, Line: t.Line, Col: t.Col}
				continue
			}
			k := ps.pop()
			if k.Kind != tIdent {
				ps.unexpected()
			}
			e = &Node{Kind: KMember, L: e, Str: k.Str, Opt: true, Line: k.Line, Col: k.Col}
			continue
		}
		if t.Kind == tPunct && t.Str == "[" {
			ps.pop()
			k, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct("]")
			e = &Node{Kind: KMember, L: e, X: k, Compute: true, Line: t.Line, Col: t.Col}
			continue
		}
		if t.Kind == tPunct && t.Str == "(" {
			ps.pop()
			args, err := parseArgs(ps)
			if err != nil {
				return nil, err
			}
			e = &Node{Kind: KCall, L: e, List: args, Line: t.Line, Col: t.Col}
			continue
		}
		if t.Kind == tRegex || t.Kind == tStr || t.Kind == tNum || t.Kind == tBig ||
			t.Kind == tIdent || t.Kind == tTpl || t.Kind == tTplHead {
			// tagged template or unexpected
			if t.Kind == tTplHead || t.Kind == tTplMid {
				// tagged template literal
				tpl, err := parseTemplateRest(ps, t, e)
				if err != nil {
					return nil, err
				}
				e = &Node{Kind: KCall, L: e, List: []*Node{tpl}}
				continue
			}
			if ps.canEndExprAfter(t) {
				break
			}
			ps.unexpected()
		}
		break
	}
	return e, nil
}

func (ps *parser) canEndExprAfter(t Tok) bool {
	// after an expression these tokens end it (statement end handled by caller)
	return false
}

func parseArgs(ps *parser) ([]*Node, error) {
	var out []*Node
	for !ps.isPunct(")") {
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			out = append(out, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
				continue
			}
			break
		}
		e, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		out = append(out, e)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct(")")
	return out, nil
}

func parsePrimary(ps *parser, noIn bool) (*Node, error) {
	t := ps.peek()
	switch t.Kind {
	case tNum:
		ps.pop()
		return &Node{Kind: KNum, Num: t.Num, Line: t.Line, Col: t.Col}, nil
	case tBig:
		ps.pop()
		return &Node{Kind: KBig, Big: t.Big, Line: t.Line, Col: t.Col}, nil
	case tStr:
		ps.pop()
		return &Node{Kind: KStr, Str: t.Str, Line: t.Line, Col: t.Col}, nil
	case tTpl:
		ps.pop()
		return &Node{Kind: KTpl, Str: t.Str, List: nil, Line: t.Line, Col: t.Col}, nil
	case tTplHead:
		return parseTemplateRest(ps, t, nil)
	case tRegex:
		ps.pop()
		return &Node{Kind: KRegex, Str: t.Str, Flags: t.Flags, Line: t.Line, Col: t.Col}, nil
	case tIdent:
		switch t.Str {
		case "let", "yield":
			if !keywords[t.Str] {
				break
			}
			// used as identifier in strict mode -> runtime syntax error
			ps.pop()
			ps.strict = append(ps.strict, t)
			return &Node{Kind: KIdent, Str: t.Str, Line: t.Line, Col: t.Col}, nil
		case "true":
			ps.pop()
			return &Node{Kind: KBool, Bool: true, Line: t.Line, Col: t.Col}, nil
		case "false":
			ps.pop()
			return &Node{Kind: KBool, Bool: false, Line: t.Line, Col: t.Col}, nil
		case "null":
			ps.pop()
			return &Node{Kind: KNull, Line: t.Line, Col: t.Col}, nil
		case "this":
			ps.pop()
			return &Node{Kind: KThis, Line: t.Line, Col: t.Col}, nil
		case "undefined":
			ps.pop()
			return &Node{Kind: KIdent, Str: "undefined", Line: t.Line, Col: t.Col}, nil
		case "function":
			fn, err := parseFunction(ps, false, false)
			if err != nil {
				return nil, err
			}
			return fn, nil
		case "class":
			c, err := parseClass(ps, false)
			if err != nil {
				return nil, err
			}
			return c, nil
		case "async":
			if ps.peekAhead(1).Kind == tIdent && ps.peekAhead(1).Str == "function" {
				ps.pop()
				fn, err := parseFunction(ps, false, false)
				if err != nil {
					return nil, err
				}
				fn.Async = true
				return fn, nil
			}
		}
		ps.pop()
		return &Node{Kind: KIdent, Str: t.Str, Line: t.Line, Col: t.Col}, nil
	case tPunct:
		switch t.Str {
		case "(":
			ps.pop()
			e, err := parseExpression(ps, noIn)
			if err != nil {
				return nil, err
			}
			ps.expectPunct(")")
			return e, nil
		case "[":
			return parseArrayLit(ps)
		case "{":
			return parseObjectLit(ps)
		}
	}
	ps.unexpected()
	return nil, nil
}

func (ps *parser) peekAhead(n int) Tok {
	save := ps.pi
	var t Tok
	for i := 0; i <= n; i++ {
		t = ps.pop()
	}
	ps.pi = save
	return t
}

func parseArrayLit(ps *parser) (*Node, error) {
	t := ps.pop() // [
	n := &Node{Kind: KArray, Line: t.Line, Col: t.Col}
	for !ps.isPunct("]") {
		if ps.isPunct(",") {
			ps.pop()
			n.List = append(n.List, nil)
			continue
		}
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			n.List = append(n.List, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
				continue
			}
			break
		}
		e, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		n.List = append(n.List, e)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("]")
	return n, nil
}

func parseObjectLit(ps *parser) (*Node, error) {
	t := ps.pop() // {
	n := &Node{Kind: KObject, Line: t.Line, Col: t.Col}
	for !ps.isPunct("}") {
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			n.List = append(n.List, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
				continue
			}
			break
		}
		prop, err := parseObjProp(ps)
		if err != nil {
			return nil, err
		}
		n.List = append(n.List, prop)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("}")
	return n, nil
}

func parseObjProp(ps *parser) (*Node, error) {
	var key *Node
	shorthand := false
	method := false
	t := ps.peek()
	if t.Kind == tIdent {
		ps.pop()
		key = &Node{Kind: KStr, Str: t.Str}
		shorthand = true
	} else if t.Kind == tStr {
		ps.pop()
		key = &Node{Kind: KStr, Str: t.Str}
	} else if t.Kind == tNum {
		ps.pop()
		key = &Node{Kind: KStr, Str: numKey(t.Num)}
	} else if t.Kind == tPunct && t.Str == "[" {
		ps.pop()
		e, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		ps.expectPunct("]")
		key = &Node{Kind: KCompute, X: e}
	} else if t.Kind == tPunct && (t.Str == "*" ) {
		// generator method
		ps.pop()
		m, err := parseObjProp(ps)
		if err != nil {
			return nil, err
		}
		m.Gen = true
		return m, nil
	} else {
		ps.unexpected()
	}
	// method shorthand?
	if (t.Kind == tIdent || t.Kind == tStr) && (ps.isPunct("(") || ps.isPunct("async") || ps.isPunct("*")) {
		method = true
	}
	var val *Node
	if method {
		fn, err := parseFunctionMethod(ps, key.Str)
		if err != nil {
			return nil, err
		}
		fn.Str = key.Str
		val = fn
	} else if ps.isPunct(":") {
		ps.pop()
		v, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		val = v
	} else {
		// shorthand or accessor
		if ps.isPunct("=") {
			ps.pop()
			d, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			val = &Node{Kind: KAssign, L: &Node{Kind: KIdent, Str: key.Str}, R: d}
		} else if key.Kind == KStr {
			val = &Node{Kind: KIdent, Str: key.Str}
		} else {
			val = key
		}
	}
	n := &Node{Kind: KObject, L: key, R: val, Method: method}
	return n, nil
}

func numKey(v float64) string {
	if v == float64(int64(v)) {
		return strconv.FormatInt(int64(v), 10)
	}
	return strconv.FormatFloat(v, 'g', -1, 64)
}

func parseFunctionMethod(ps *parser, name string) (*Node, error) {
	if ps.isIdent("async") {
		ps.pop()
	}
	if ps.isPunct("*") {
		ps.pop()
	}
	ps.expectPunct("(")
	params, err := parseParams(ps)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	body, err := parseBlock(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KFunc, Str: name, List: params, L: body}, nil
}

func parseClass(ps *parser, isDecl bool) (*Node, error) {
	ps.pop() // class
	name := ""
	if ps.peek().Kind == tIdent {
		name = ps.pop().Str
	} else if isDecl {
		ps.unexpected()
	}
	var super *Node
	if ps.isIdent("extends") {
		ps.pop()
		s, err := parseCallChain(ps, false)
		if err != nil {
			return nil, err
		}
		super = s
	}
	ps.expectPunct("{")
	n := &Node{Kind: KClass, Str: name, L: super}
	for !ps.isPunct("}") {
		t := ps.peek()
		static := false
		if t.Kind == tIdent && t.Str == "static" && ps.peekAhead(1).Kind == tIdent {
			ps.pop()
			static = true
			t = ps.peek()
		}
		if t.Kind == tIdent && t.Str == "constructor" {
			ps.pop()
			fn, err := parseFunctionMethod(ps, "constructor")
			if err != nil {
				return nil, err
			}
			n.Y = fn
		} else {
			k, err := parseObjProp(ps)
			if err != nil {
				return nil, err
			}
			k.Decl = static
			n.List = append(n.List, k)
		}
		if ps.isPunct(";") {
			ps.pop()
		}
	}
	ps.pop()
	return n, nil
}

// parseTemplateRest parses the rest of a template literal after a head chunk.
func parseTemplateRest(ps *parser, head Tok, tag *Node) (*Node, error) {
	n := &Node{Kind: KTpl, Str: head.Str, Tag: tag}
	var err error
	for {
		e, err2 := parseExpression(ps, true)
		if err2 != nil {
			return nil, err2
		}
		n.List = append(n.List, e)
		ps.expectPunct("}")
		var chunk Tok
		if ps.l.prev.Kind == tEOF {
			break
		}
		chunk = ps.l.nextTemplate()
		n.Strs = append(n.Strs, chunk.Str)
		if chunk.Kind == tTplTail {
			break
		}
		if chunk.Kind == tEOF {
			break
		}
	}
	return n, err
}

var _ = big.NewInt
EOF
echo ok

function.arguments:
{"command": "cd /workspace && cat > internal/engine/expr.go <<'EOF'
package engine

import (
	"math/big"
	"strconv"
)

type saveState struct {
	pi        int
	look      []Tok
	lpos      int
	lline     int
	lstart    int
	lprev     Tok
	lnline    bool
}

func (ps *parser) save() saveState {
	return saveState{pi: ps.pi, look: append([]Tok(nil), ps.look...), lpos: ps.l.pos,
		lline: ps.l.line, lstart: ps.l.lineStart, lprev: ps.l.prev, lnline: ps.l.nline}
}

func (ps *parser) restore(s saveState) {
	ps.pi = s.pi
	ps.look = s.look
	ps.l.pos = s.lpos
	ps.l.line = s.lline
	ps.l.lineStart = s.lstart
	ps.l.prev = s.lprev
	ps.l.nline = s.lnline
}

// parseExpression parses a sequence expression.
func parseExpression(ps *parser, noIn bool) (*Node, error) {
	e, err := parseAssign(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct(",") {
		ps.pop()
		r, err := parseAssign(ps, noIn)
		if err != nil {
			return nil, err
		}
		if e.Kind != KSeq {
			e = &Node{Kind: KSeq, List: []*Node{e}}
		}
		e.List = append(e.List, r)
	}
	return e, nil
}

func (ps *parser) tryArrow() (*Node, bool) {
	st := ps.save()
	var params []*Node
	async := false
	if ps.isIdent("async") {
		// async arrow only when not followed by a newline and next is not => etc
		save := ps.pi
		ps.pop()
		if ps.isPunct("(") || (ps.peek().Kind == tIdent && !keywords[ps.peek().Str]) {
			async = true
		} else {
			ps.pi = save
		}
	}
	ok := true
	if ps.isPunct("(") {
		ps.pop()
		var err error
		params, err = parseParams(ps)
		if err != nil {
			ok = false
		} else if !ps.isPunct(")") {
			ok = false
		} else {
			ps.pop()
		}
	} else if ps.peek().Kind == tIdent {
		t := ps.pop()
		params = []*Node{&Node{Kind: KIdent, Str: t.Str}}
	} else {
		ok = false
	}
	if ok {
		if ps.isPunct("=>") {
			ps.pop()
			body, err := parseArrowBody(ps)
			if err != nil {
				return nil, false
			}
			fn := &Node{Kind: KFunc, List: params, L: body, Async: async, Gen: false, Body: body}
			return fn, true
		}
	}
	ps.restore(st)
	return nil, false
}

func parseArrowBody(ps *parser) (*Node, error) {
	if ps.isPunct("{") {
		b, err := parseBlock(ps)
		if err != nil {
			return nil, err
		}
		return b, nil
	}
	e, err := parseAssign(ps, false)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KReturn, L: e}, nil
}

func parseAssign(ps *parser, noIn bool) (*Node, error) {
	if fn, ok := ps.tryArrow(); ok {
		return fn, nil
	}
	l, err := parseCond(ps, noIn)
	if err != nil {
		return nil, err
	}
	t := ps.peek()
	if t.Kind == tPunct {
		switch t.Str {
		case "=", "+=", "-=", "*=", "/=", "%=", "**=", "<<=", ">>=", ">>>=", "&=", "|=", "^=", "&&=", "||=", "??=":
			if !isValidAssignTarget(l) {
				panic(&SyntaxError{Msg: "Invalid left-hand side in assignment "})
			}
			ps.pop()
			r, err := parseAssign(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KAssign, Op: t.Str, L: l, R: r}, nil
		}
	}
	return l, nil
}

func isValidAssignTarget(n *Node) bool {
	switch n.Kind {
	case KIdent, KMember, KThis:
		return true
	case KArray, KObject:
		return true
	}
	return false
}

func parseCond(ps *parser, noIn bool) (*Node, error) {
	c, err := parseCoalesce(ps, noIn)
	if err != nil {
		return nil, err
	}
	if ps.isPunct("?") {
		ps.pop()
		t, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		ps.expectPunct(":")
		f, err := parseAssign(ps, noIn)
		if err != nil {
			return nil, err
		}
		return &Node{Kind: KCond, L: c, R: t, X: f}, nil
	}
	return c, nil
}

func parseCoalesce(ps *parser, noIn bool) (*Node, error) {
	l, err := parseOr(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("??") {
		ps.pop()
		r, err := parseOr(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KLogical, Op: "??", L: l, R: r}
	}
	return l, nil
}

func parseOr(ps *parser, noIn bool) (*Node, error) {
	l, err := parseAnd(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("||") {
		ps.pop()
		r, err := parseAnd(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KLogical, Op: "||", L: l, R: r}
	}
	return l, nil
}

func parseAnd(ps *parser, noIn bool) (*Node, error) {
	l, err := parseBitOr(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("&&") {
		ps.pop()
		r, err := parseBitOr(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KLogical, Op: "&&", L: l, R: r}
	}
	return l, nil
}

func parseBitOr(ps *parser, noIn bool) (*Node, error) {
	l, err := parseBitXor(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("|") {
		ps.pop()
		r, err := parseBitXor(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KBinary, Op: "|", L: l, R: r}
	}
	return l, nil
}

func parseBitXor(ps *parser, noIn bool) (*Node, error) {
	l, err := parseBitAnd(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("^") {
		ps.pop()
		r, err := parseBitAnd(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KBinary, Op: "^", L: l, R: r}
	}
	return l, nil
}

func parseBitAnd(ps *parser, noIn bool) (*Node, error) {
	l, err := parseEquality(ps, noIn)
	if err != nil {
		return nil, err
	}
	for ps.isPunct("&") {
		ps.pop()
		r, err := parseEquality(ps, noIn)
		if err != nil {
			return nil, err
		}
		l = &Node{Kind: KBinary, Op: "&", L: l, R: r}
	}
	return l, nil
}

func parseEquality(ps *parser, noIn bool) (*Node, error) {
	l, err := parseRelational(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		switch t.Str {
		case "==", "!=", "===", "!==":
			ps.pop()
			r, err := parseRelational(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseRelational(ps *parser, noIn bool) (*Node, error) {
	l, err := parseShift(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind == tPunct {
			switch t.Str {
			case "<", ">", "<=", ">=":
				ps.pop()
				r, err := parseShift(ps, noIn)
				if err != nil {
					return nil, err
				}
				l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
				continue
			}
		} else if t.Kind == tIdent {
			if t.Str == "instanceof" {
				ps.pop()
				r, err := parseShift(ps, noIn)
				if err != nil {
					return nil, err
				}
				l = &Node{Kind: KBinary, Op: "instanceof", L: l, R: r}
				continue
			}
			if t.Str == "in" && !noIn {
				ps.pop()
				r, err := parseShift(ps, noIn)
				if err != nil {
					return nil, err
				}
				l = &Node{Kind: KBinary, Op: "in", L: l, R: r}
				continue
			}
		}
		break
	}
	return l, nil
}

func parseShift(ps *parser, noIn bool) (*Node, error) {
	l, err := parseAdditive(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		switch t.Str {
		case "<<", ">>", ">>>":
			ps.pop()
			r, err := parseAdditive(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseAdditive(ps *parser, noIn bool) (*Node, error) {
	l, err := parseMultiplicative(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		if t.Str == "+" || t.Str == "-" {
			ps.pop()
			r, err := parseMultiplicative(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseMultiplicative(ps *parser, noIn bool) (*Node, error) {
	l, err := parseExponent(ps, noIn)
	if err != nil {
		return nil, err
	}
	for {
		t := ps.peek()
		if t.Kind != tPunct {
			break
		}
		if t.Str == "*" || t.Str == "/" || t.Str == "%" {
			ps.pop()
			r, err := parseExponent(ps, noIn)
			if err != nil {
				return nil, err
			}
			l = &Node{Kind: KBinary, Op: t.Str, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func parseExponent(ps *parser, noIn bool) (*Node, error) {
	l, err := parseUnary(ps, noIn)
	if err != nil {
		return nil, err
	}
	if ps.isPunct("**") {
		ps.pop()
		r, err := parseExponent(ps, noIn)
		if err != nil {
			return nil, err
		}
		return &Node{Kind: KBinary, Op: "**", L: l, R: r}, nil
	}
	return l, nil
}

func parseUnary(ps *parser, noIn bool) (*Node, error) {
	t := ps.peek()
	if t.Kind == tPunct {
		switch t.Str {
		case "+", "-", "~", "!":
			ps.pop()
			a, err := parseUnary(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KUnary, Op: t.Str, L: a, Line: t.Line, Col: t.Col}, nil
		}
	} else if t.Kind == tIdent {
		switch t.Str {
		case "typeof", "void", "delete":
			ps.pop()
			a, err := parseUnary(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KUnary, Op: t.Str, L: a, Line: t.Line, Col: t.Col}, nil
		case "await":
			ps.pop()
			a, err := parseUnary(ps, noIn)
			if err != nil {
				return nil, err
			}
			return &Node{Kind: KUnary, Op: "await", L: a}, nil
		}
	}
	return parsePostfix(ps, noIn)
}

func parsePostfix(ps *parser, noIn bool) (*Node, error) {
	e, err := parseCallChain(ps, noIn)
	if err != nil {
		return nil, err
	}
	t := ps.peek()
	if t.Kind == tPunct && (t.Str == "++" || t.Str == "--") && !t.NL {
		ps.pop()
		return &Node{Kind: KUpdate, Op: t.Str, L: e, Prefix: false, Line: t.Line, Col: t.Col}, nil
	}
	return e, nil
}

func parseCallChain(ps *parser, noIn bool) (*Node, error) {
	var e *Node
	t := ps.peek()
	if t.Kind == tIdent && t.Str == "new" {
		ps.pop()
		callee, err := parseCallChain(ps, noIn)
		if err != nil {
			return nil, err
		}
		args := []*Node{}
		if ps.isPunct("(") {
			ps.pop()
			var err error
			args, err = parseArgs(ps)
			if err != nil {
				return nil, err
			}
		}
		e = &Node{Kind: KNew, L: callee, List: args, Line: t.Line, Col: t.Col}
	} else {
		var err error
		e, err = parsePrimary(ps, noIn)
		if err != nil {
			return nil, err
		}
	}
	for {
		t := ps.peek()
		if t.Kind == tPunct && t.Str == "." {
			ps.pop()
			k := ps.pop()
			if k.Kind != tIdent {
				ps.unexpected()
			}
			e = &Node{Kind: KMember, L: e, Str: k.Str, Line: k.Line, Col: k.Col}
			continue
		}
		if t.Kind == tPunct && (t.Str == "?." ) {
			ps.pop()
			if ps.isPunct("(") {
				ps.pop()
				args, err := parseArgs(ps)
				if err != nil {
					return nil, err
				}
				e = &Node{Kind: KCall, L: e, List: args, Opt: true, Line: t.Line, Col: t.Col}
				continue
			}
			if ps.isPunct("[") {
				ps.pop()
				k, err := parseExpression(ps, true)
				if err != nil {
					return nil, err
				}
				ps.expectPunct("]")
				e = &Node{Kind: KMember, L: e, X: k, Compute: true, Opt: true, Line: t.Line, Col: t.Col}
				continue
			}
			k := ps.pop()
			if k.Kind != tIdent {
				ps.unexpected()
			}
			e = &Node{Kind: KMember, L: e, Str: k.Str, Opt: true, Line: k.Line, Col: k.Col}
			continue
		}
		if t.Kind == tPunct && t.Str == "[" {
			ps.pop()
			k, err := parseExpression(ps, true)
			if err != nil {
				return nil, err
			}
			ps.expectPunct("]")
			e = &Node{Kind: KMember, L: e, X: k, Compute: true, Line: t.Line, Col: t.Col}
			continue
		}
		if t.Kind == tPunct && t.Str == "(" {
			ps.pop()
			args, err := parseArgs(ps)
			if err != nil {
				return nil, err
			}
			e = &Node{Kind: KCall, L: e, List: args, Line: t.Line, Col: t.Col}
			continue
		}
		if t.Kind == tRegex || t.Kind == tStr || t.Kind == tNum || t.Kind == tBig ||
			t.Kind == tIdent || t.Kind == tTpl || t.Kind == tTplHead {
			// tagged template or unexpected
			if t.Kind == tTplHead || t.Kind == tTplMid {
				// tagged template literal
				tpl, err := parseTemplateRest(ps, t, e)
				if err != nil {
					return nil, err
				}
				e = &Node{Kind: KCall, L: e, List: []*Node{tpl}}
				continue
			}
			if ps.canEndExprAfter(t) {
				break
			}
			ps.unexpected()
		}
		break
	}
	return e, nil
}

func (ps *parser) canEndExprAfter(t Tok) bool {
	// after an expression these tokens end it (statement end handled by caller)
	return false
}

func parseArgs(ps *parser) ([]*Node, error) {
	var out []*Node
	for !ps.isPunct(")") {
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			out = append(out, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
				continue
			}
			break
		}
		e, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		out = append(out, e)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct(")")
	return out, nil
}

func parsePrimary(ps *parser, noIn bool) (*Node, error) {
	t := ps.peek()
	switch t.Kind {
	case tNum:
		ps.pop()
		return &Node{Kind: KNum, Num: t.Num, Line: t.Line, Col: t.Col}, nil
	case tBig:
		ps.pop()
		return &Node{Kind: KBig, Big: t.Big, Line: t.Line, Col: t.Col}, nil
	case tStr:
		ps.pop()
		return &Node{Kind: KStr, Str: t.Str, Line: t.Line, Col: t.Col}, nil
	case tTpl:
		ps.pop()
		return &Node{Kind: KTpl, Str: t.Str, List: nil, Line: t.Line, Col: t.Col}, nil
	case tTplHead:
		return parseTemplateRest(ps, t, nil)
	case tRegex:
		ps.pop()
		return &Node{Kind: KRegex, Str: t.Str, Flags: t.Flags, Line: t.Line, Col: t.Col}, nil
	case tIdent:
		switch t.Str {
		case "let", "yield":
			if !keywords[t.Str] {
				break
			}
			// used as identifier in strict mode -> runtime syntax error
			ps.pop()
			ps.strict = append(ps.strict, t)
			return &Node{Kind: KIdent, Str: t.Str, Line: t.Line, Col: t.Col}, nil
		case "true":
			ps.pop()
			return &Node{Kind: KBool, Bool: true, Line: t.Line, Col: t.Col}, nil
		case "false":
			ps.pop()
			return &Node{Kind: KBool, Bool: false, Line: t.Line, Col: t.Col}, nil
		case "null":
			ps.pop()
			return &Node{Kind: KNull, Line: t.Line, Col: t.Col}, nil
		case "this":
			ps.pop()
			return &Node{Kind: KThis, Line: t.Line, Col: t.Col}, nil
		case "undefined":
			ps.pop()
			return &Node{Kind: KIdent, Str: "undefined", Line: t.Line, Col: t.Col}, nil
		case "function":
			fn, err := parseFunction(ps, false, false)
			if err != nil {
				return nil, err
			}
			return fn, nil
		case "class":
			c, err := parseClass(ps, false)
			if err != nil {
				return nil, err
			}
			return c, nil
		case "async":
			if ps.peekAhead(1).Kind == tIdent && ps.peekAhead(1).Str == "function" {
				ps.pop()
				fn, err := parseFunction(ps, false, false)
				if err != nil {
					return nil, err
				}
				fn.Async = true
				return fn, nil
			}
		}
		ps.pop()
		return &Node{Kind: KIdent, Str: t.Str, Line: t.Line, Col: t.Col}, nil
	case tPunct:
		switch t.Str {
		case "(":
			ps.pop()
			e, err := parseExpression(ps, noIn)
			if err != nil {
				return nil, err
			}
			ps.expectPunct(")")
			return e, nil
		case "[":
			return parseArrayLit(ps)
		case "{":
			return parseObjectLit(ps)
		}
	}
	ps.unexpected()
	return nil, nil
}

func (ps *parser) peekAhead(n int) Tok {
	save := ps.pi
	var t Tok
	for i := 0; i <= n; i++ {
		t = ps.pop()
	}
	ps.pi = save
	return t
}

func parseArrayLit(ps *parser) (*Node, error) {
	t := ps.pop() // [
	n := &Node{Kind: KArray, Line: t.Line, Col: t.Col}
	for !ps.isPunct("]") {
		if ps.isPunct(",") {
			ps.pop()
			n.List = append(n.List, nil)
			continue
		}
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			n.List = append(n.List, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
				continue
			}
			break
		}
		e, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		n.List = append(n.List, e)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("]")
	return n, nil
}

func parseObjectLit(ps *parser) (*Node, error) {
	t := ps.pop() // {
	n := &Node{Kind: KObject, Line: t.Line, Col: t.Col}
	for !ps.isPunct("}") {
		if ps.isPunct("...") {
			ps.pop()
			e, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			n.List = append(n.List, &Node{Kind: KSpread, L: e})
			if ps.isPunct(",") {
				ps.pop()
				continue
			}
			break
		}
		prop, err := parseObjProp(ps)
		if err != nil {
			return nil, err
		}
		n.List = append(n.List, prop)
		if ps.isPunct(",") {
			ps.pop()
			continue
		}
		break
	}
	ps.expectPunct("}")
	return n, nil
}

func parseObjProp(ps *parser) (*Node, error) {
	var key *Node
	shorthand := false
	method := false
	t := ps.peek()
	if t.Kind == tIdent {
		ps.pop()
		key = &Node{Kind: KStr, Str: t.Str}
		shorthand = true
	} else if t.Kind == tStr {
		ps.pop()
		key = &Node{Kind: KStr, Str: t.Str}
	} else if t.Kind == tNum {
		ps.pop()
		key = &Node{Kind: KStr, Str: numKey(t.Num)}
	} else if t.Kind == tPunct && t.Str == "[" {
		ps.pop()
		e, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		ps.expectPunct("]")
		key = &Node{Kind: KCompute, X: e}
	} else if t.Kind == tPunct && (t.Str == "*" ) {
		// generator method
		ps.pop()
		m, err := parseObjProp(ps)
		if err != nil {
			return nil, err
		}
		m.Gen = true
		return m, nil
	} else {
		ps.unexpected()
	}
	// method shorthand?
	if (t.Kind == tIdent || t.Kind == tStr) && (ps.isPunct("(") || ps.isPunct("async") || ps.isPunct("*")) {
		method = true
	}
	var val *Node
	if method {
		fn, err := parseFunctionMethod(ps, key.Str)
		if err != nil {
			return nil, err
		}
		fn.Str = key.Str
		val = fn
	} else if ps.isPunct(":") {
		ps.pop()
		v, err := parseAssign(ps, false)
		if err != nil {
			return nil, err
		}
		val = v
	} else {
		// shorthand or accessor
		if ps.isPunct("=") {
			ps.pop()
			d, err := parseAssign(ps, false)
			if err != nil {
				return nil, err
			}
			val = &Node{Kind: KAssign, L: &Node{Kind: KIdent, Str: key.Str}, R: d}
		} else if key.Kind == KStr {
			val = &Node{Kind: KIdent, Str: key.Str}
		} else {
			val = key
		}
	}
	n := &Node{Kind: KObject, L: key, R: val, Method: method}
	return n, nil
}

func numKey(v float64) string {
	if v == float64(int64(v)) {
		return strconv.FormatInt(int64(v), 10)
	}
	return strconv.FormatFloat(v, 'g', -1, 64)
}

func parseFunctionMethod(ps *parser, name string) (*Node, error) {
	if ps.isIdent("async") {
		ps.pop()
	}
	if ps.isPunct("*") {
		ps.pop()
	}
	ps.expectPunct("(")
	params, err := parseParams(ps)
	if err != nil {
		return nil, err
	}
	ps.expectPunct(")")
	body, err := parseBlock(ps)
	if err != nil {
		return nil, err
	}
	return &Node{Kind: KFunc, Str: name, List: params, L: body}, nil
}

func parseClass(ps *parser, isDecl bool) (*Node, error) {
	ps.pop() // class
	name := ""
	if ps.peek().Kind == tIdent {
		name = ps.pop().Str
	} else if isDecl {
		ps.unexpected()
	}
	var super *Node
	if ps.isIdent("extends") {
		ps.pop()
		s, err := parseCallChain(ps, false)
		if err != nil {
			return nil, err
		}
		super = s
	}
	ps.expectPunct("{")
	n := &Node{Kind: KClass, Str: name, L: super}
	for !ps.isPunct("}") {
		t := ps.peek()
		static := false
		if t.Kind == tIdent && t.Str == "static" && ps.peekAhead(1).Kind == tIdent {
			ps.pop()
			static = true
			t = ps.peek()
		}
		if t.Kind == tIdent && t.Str == "constructor" {
			ps.pop()
			fn, err := parseFunctionMethod(ps, "constructor")
			if err != nil {
				return nil, err
			}
			n.Y = fn
		} else {
			k, err := parseObjProp(ps)
			if err != nil {
				return nil, err
			}
			k.Decl = static
			n.List = append(n.List, k)
		}
		if ps.isPunct(";") {
			ps.pop()
		}
	}
	ps.pop()
	return n, nil
}

// parseTemplateRest parses the rest of a template literal after a head chunk.
func parseTemplateRest(ps *parser, head Tok, tag *Node) (*Node, error) {
	n := &Node{Kind: KTpl, Str: head.Str, Tag: tag}
	var err error
	for {
		e, err2 := parseExpression(ps, true)
		if err2 != nil {
			return nil, err2
		}
		n.List = append(n.List, e)
		ps.expectPunct("}")
		var chunk Tok
		if ps.l.prev.Kind == tEOF {
			break
		}
		chunk = ps.l.nextTemplate()
		n.Strs = append(n.Strs, chunk.Str)
		if chunk.Kind == tTplTail {
			break
		}
		if chunk.Kind == tEOF {
			break
		}
	}
	return n, err
}

