{"command": "cd /workspace && cat > internal/engine/interp.go <<'EOF'
package engine

import (
	"math"
	"math/big"
	"sort"
	"strconv"
	"strings"
)

// Runtime holds the global state of the interpreter.
type Runtime struct {
	Global    *Scope
	Glob      *Obj
	Protos    map[string]*Obj
	Classes   map[string]*Func
	SkipSym   *Sym
	ObjProto  *Obj
	ArrProto  *Obj
	FuncProto *Obj
	StrProto  *Obj
	NumProto  *Obj
	BoolProto *Obj
	ErrProtos map[string]*Obj
	DateProto *Obj
	RegProto  *Obj
	MapProto  *Obj
	SetProto  *Obj
	PromProto *Obj
	ItrProto  *Obj
	Micro     []func()
	Errors    []*Throw
}

// Throw is a thrown JavaScript value.
type Throw struct {
	Val Value
}

func (t *Throw) Error() string { return ToString(rt0, t.Val) }

var rt0 *Runtime

// ReturnSig signals a return statement.
type ReturnSig struct{ Val Value }

// BreakSig signals a break statement.
type BreakSig struct{ Label string }

// ContinueSig signals a continue statement.
type ContinueSig struct{ Label string }

type YieldSig struct{ Val Value }

// Scope is a lexical scope.
type Scope struct {
	parent *Scope
	vars   map[string]*Var
	kind   string
}

type Var struct{ Val Value }

func newScope(parent *Scope) *Scope {
	return &Scope{parent: parent, vars: make(map[string]*Var)}
}

func (s *Scope) lookup(name string) *Var {
	for sc := s; sc != nil; sc = sc.parent {
		if v, ok := sc.vars[name]; ok {
			return v
		}
	}
	return nil
}

func (s *Scope) set(name string, v Value) {
	for sc := s; sc != nil; sc = sc.parent {
		if vr, ok := sc.vars[name]; ok {
			vr.Val = v
			return
		}
	}
	// implicit global
	if s.parent == nil {
		s.vars[name] = &Var{Val: v}
		return
	}
	s.declare(name, v)
}

func (s *Scope) declare(name string, v Value) {
	s.vars[name] = &Var{Val: v}
}

// New creates a runtime with the standard globals.
func New() *Runtime {
	rt := &Runtime{Protos: map[string]*Obj{}, ErrProtos: map[string]*Obj{}}
	rt0 = rt
	rt.Global = newScope(nil)
	rt.Glob = NewObj(nil)
	rt.Global.kind = "global"
	rt.SkipSym = &Sym{Desc: "skip"}
	rt.ObjProto = NewObj(nil)
	rt.ArrProto = NewObj(nil)
	rt.FuncProto = NewObj(nil)
	rt.StrProto = NewObj(nil)
	rt.NumProto = NewObj(nil)
	rt.BoolProto = NewObj(nil)
	rt.DateProto = NewObj(nil)
	rt.RegProto = NewObj(nil)
	rt.MapProto = NewObj(nil)
	rt.SetProto = NewObj(nil)
	rt.PromProto = NewObj(nil)
	rt.ItrProto = NewObj(nil)
	rt.ErrProtos["Error"] = NewObj(nil)
	rt.ErrProtos["EvalError"] = NewObj(nil)
	rt.ErrProtos["RangeError"] = NewObj(nil)
	rt.ErrProtos["ReferenceError"] = NewObj(nil)
	rt.ErrProtos["SyntaxError"] = NewObj(nil)
	rt.ErrProtos["TypeError"] = NewObj(nil)
	rt.ErrProtos["URIError"] = NewObj(nil)
	rt.ErrProtos["AggregateError"] = NewObj(nil)
	for _, n := range []string{"Error", "EvalError", "RangeError", "ReferenceError", "SyntaxError", "TypeError", "URIError", "AggregateError"} {
		rt.ErrProtos[n].proto = rt.ObjProto
	}
	rt.Classes = map[string]*Func{}
	rt.ArrProto.proto = rt.ObjProto
	rt.FuncProto.proto = rt.ObjProto
	rt.StrProto.proto = rt.ObjProto
	rt.NumProto.proto = rt.ObjProto
	rt.BoolProto.proto = rt.ObjProto
	rt.DateProto.proto = rt.ObjProto
	rt.RegProto.proto = rt.ObjProto
	rt.MapProto.proto = rt.ObjProto
	rt.SetProto.proto = rt.ObjProto
	rt.PromProto.proto = rt.ObjProto
	rt.ItrProto.proto = rt.ObjProto
	return rt
}

// ---------- conversions ----------

func isUndef(v Value) bool {
	_, ok := v.(Undef)
	return ok || v == nil
}

func isNullish(v Value) bool {
	if _, ok := v.(Undef); ok {
		return true
	}
	if _, ok := v.(Null); ok {
		return true
	}
	return v == nil
}

func isNull(v Value) bool {
	_, ok := v.(Null)
	return ok
}

func ToBool(v Value) bool {
	switch t := v.(type) {
	case nil:
		return false
	case Undef:
		return false
	case Null:
		return false
	case Bool:
		return bool(t)
	case Str:
		return len(string(t)) > 0
	case float64:
		return t != 0 && t == t
	case *big.Int:
		return t.Sign() != 0
	case *Sym:
		return true
	default:
		return true
	}
}

// ToNumber converts a value to a number following ToNumber.
func ToNumber(v Value) float64 {
	switch t := v.(type) {
	case nil, Undef:
		return math.NaN()
	case Null:
		return 0
	case Bool:
		if t {
			return 1
		}
		return 0
	case Str:
		return strToNumber(string(t))
	case float64:
		return t
	case *big.Int:
		f, _ := new(big.Float).SetInt(t).Float64()
		return f
	case *RawNum:
		return t.V
	}
	return toNumberObject(v)
}

func toNumberObject(v Value) float64 {
	if o, ok := v.(*Obj); ok {
		if pv, ok := o.Get("valueOf"); ok {
			if f, ok := pv.(*Func); ok {
				r := callValue(f, v, nil)
				if isPrimitive(r) {
					return ToNumber(r)
				}
			}
		}
	}
	return math.NaN()
}

func isPrimitive(v Value) bool {
	switch v.(type) {
	case nil, Undef, Null, Bool, Str, float64, *big.Int, *RawNum, *Sym:
		return true
	}
	return false
}

func strToNumber(s string) float64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	if strings.HasPrefix(t, "0x") || strings.HasPrefix(t, "0X") {
		if v, err := strconv.ParseUint(t[2:], 16, 64); err == nil {
			return float64(v)
		}
		return math.NaN()
	}
	if strings.HasPrefix(t, "0o") || strings.HasPrefix(t, "0O") {
		if v, err := strconv.ParseUint(t[2:], 8, 64); err == nil {
			return float64(v)
		}
		return math.NaN()
	}
	if strings.HasPrefix(t, "0b") || strings.HasPrefix(t, "0B") {
		if v, err := strconv.ParseUint(t[2:], 2, 64); err == nil {
			return float64(v)
		}
		return math.NaN()
	}
	if strings.HasSuffix(t, "n") {
		if v, ok := new(big.Int).SetString(t[:len(t)-1], 10); ok {
			f, _ := new(big.Float).SetInt(v).Float64()
			return f
		}
	}
	if t == "Infinity" || t == "+Infinity" {
		return math.Inf(1)
	}
	if t == "-Infinity" {
		return math.Inf(-1)
	}
	if t == "NaN" {
		return math.NaN()
	}
	v, err := strconv.ParseFloat(t, 64)
	if err != nil {
		return math.NaN()
	}
	return v
}

// ToString converts a value to a string.
func ToString(rt *Runtime, v Value) string {
	switch t := v.(type) {
	case nil, Undef:
		return "undefined"
	case Null:
		return "null"
	case Bool:
		if t {
			return "true"
		}
		return "false"
	case Str:
		return string(t)
	case float64:
		return NumToString(t)
	case *big.Int:
		return t.String()
	case *RawNum:
		return t.Raw
	case *Sym:
		return "Symbol(" + t.Desc + ")"
	case *Date:
		if !t.Valid {
			return "Invalid Date"
		}
		return t.T.Format("Mon Jan 02 2006 15:04:05 GMT-0700 (MST)")
	}
	if o, ok := v.(*Obj); ok {
		if f, ok := o.Get("toString"); ok {
			if fn, ok := f.(*Func); ok {
				r := callValue(fn, v, nil)
				if s, ok := r.(Str); ok {
					return string(s)
				}
			}
		}
		switch o.cls {
		case "Array":
			return arrayToString(rt, o)
		case "Function", "class":
			return functionToString(o)
		case "Object":
			return "[object Object]"
		}
		return "[object " + o.cls + "]"
	}
	if f, ok := v.(*Func); ok {
		if f.Native != nil {
			return "function " + f.Name + "() { [native code] }"
		}
		return "function " + f.Name + "() { ... }"
	}
	return ToString(rt, nil)
}

func arrayToString(rt *Runtime, o *Obj) string {
	// arrays are *Arr, this is for exotic arrays
	return ""
}

func functionToString(o *Obj) string { return "[object Object]" }

// ToStringValue is ToString for use inside the interpreter.
func (rt *Runtime) ToString(v Value) string { return ToString(rt, v) }

// ToObject wraps primitives in objects.
func (rt *Runtime) ToObject(v Value) *Obj {
	switch t := v.(type) {
	case *Obj:
		return t
	case *Arr:
		o := NewObj(rt.ObjProto)
		o.cls = "Object"
		return o
	case Str:
		o := NewObj(rt.StrProto)
		o.cls = "String"
		for i, c := range string(t) {
			o.Set(strconv.Itoa(i), Str(string(c)))
		}
		o.Set("length", float64(len([]rune(string(t)))))
		return o
	case float64:
		o := NewObj(rt.NumProto)
		o.cls = "Number"
		o.SetPrimitive(v)
		return o
	case Bool:
		o := NewObj(rt.BoolProto)
		o.cls = "Boolean"
		o.SetPrimitive(v)
		return o
	case *Sym:
		o := NewObj(nil)
		o.cls = "Symbol"
		o.SetPrimitive(v)
		return o
	case *big.Int:
		o := NewObj(nil)
		o.cls = "BigInt"
		o.SetPrimitive(v)
		return o
	case *Date:
		o := NewObj(rt.DateProto)
		o.cls = "Date"
		o.SetPrimitive(v)
		return o
	case *Err:
		o := NewObj(rt.ErrProtos[t.Name])
		o.cls = t.Name
		o.SetPrimitive(v)
		return o
	}
	return nil
}

// TypeError throws a TypeError.
func (rt *Runtime) TypeError(msg string) {
	panic(&Throw{Val: rt.NewError("TypeError", msg)})
}

// NewError creates a new error object.
func (rt *Runtime) NewError(name, msg string) *Err {
	e := &Err{Name: name, Message: msg}
	return e
}

// ThrowError throws an Error with the given name and message.
func (rt *Runtime) ThrowError(name, msg string) {
	panic(&Throw{Val: rt.NewError(name, msg)})
}

// RangeError throws a RangeError.
func (rt *Runtime) RangeError(msg string) { rt.ThrowError("RangeError", msg) }

// GetMember resolves obj[key] following the prototype chain.
func (rt *Runtime) GetMember(obj Value, key string) Value {
	switch t := obj.(type) {
	case nil, Undef:
		rt.TypeError("Cannot read property '" + key + "' of " + ToString(rt, obj))
	case Null:
		rt.TypeError("Cannot read property '" + key + "' of null")
	case *Arr:
		if key == "length" {
			return float64(len(t.Items))
		}
		if i, ok := arrayIndex(key); ok {
			if i < len(t.Items) {
				return t.Items[i]
			}
			return Undef{}
		}
		if v, ok := t.Items[0:0], false; ok {
			return v
		}
		return rt.protoMember(rt.ArrProto, key)
	case *Obj:
		if v, ok := t.Get(key); ok {
			return v
		}
		return rt.protoMember(t, key)
	case Str:
		return rt.stringMember(string(t), key)
	case float64:
		if key == "toFixed" {
			return rt.NumProtoGet("toFixed")
		}
		return rt.protoMember(rt.NumProto, key)
	case Bool:
		return rt.protoMember(rt.BoolProto, key)
	case *big.Int:
		return rt.protoMember(nil, key)
	case *Sym:
		if key == "description" {
			return Str(t.Desc)
		}
		return rt.protoMember(nil, key)
	case *Date:
		return rt.dateMember(t, key)
	case *MapT:
		return rt.mapMember(t, key)
	case *SetT:
		return rt.setMember(t, key)
	case *RegExp:
		return rt.regexpMember(t, key)
	case *Err:
		switch key {
		case "message":
			return Str(t.Message)
		case "name":
			return Str(t.Name)
		case "stack":
			return Str(t.Name + ": " + t.Message)
		}
		return rt.protoMember(rt.ErrProtos[t.Name], key)
	}
	if o, ok := obj.(*Obj); ok {
		if v, ok := o.Get(key); ok {
			return v
		}
		return rt.protoMember(o, key)
	}
	rt.TypeError("Cannot read property '" + key + "' of " + ToString(rt, obj))
	return nil
}

func (rt *Runtime) protoMember(o *Obj, key string) Value {
	for p := o; p != nil; p = p.proto {
		if v, ok := p.Get(key); ok {
			return v
		}
	}
	if o == rt.ObjProto || o == nil {
		return Undef{}
	}
	return rt.protoMember(rt.ObjProto, key)
}

func (rt *Runtime) NumProtoGet(k string) Value {
	if v, ok := rt.NumProto.Get(k); ok {
		return v
	}
	return Undef{}
}

func arrayIndex(s string) (int, bool) {
	if s == "" || len(s) > 10 {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	if len(s) > 1 && s[0] == '0' {
		return 0, false
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}

// SetMember assigns obj[key] = v.
func (rt *Runtime) SetMember(obj Value, key string, v Value) {
	switch t := obj.(type) {
	case *Arr:
		if key == "length" {
			n, _ := ToInt(v)
			t.Resize(n)
			return
		}
		if i, ok := arrayIndex(key); ok {
			t.Set(i, v)
			return
		}
		rt.TypeError("Cannot create property '" + key + "' on " + ToString(rt, obj))
	case *Obj:
		t.Set(key, v)
		return
	case *MapT, *SetT:
		return
	}
	rt.TypeError("Cannot set property '" + key + "' of " + ToString(rt, obj))
}

// Resize grows or shrinks the array.
func (a *Arr) Resize(n int) {
	if n < 0 {
		n = 0
	}
	if n < len(a.Items) {
		a.Items = a.Items[:n]
		return
	}
	for len(a.Items) < n {
		a.Items = append(a.Items, Undef{})
	}
}

// Set sets an array item, extending if needed.
func (a *Arr) Set(i int, v Value) {
	for len(a.Items) <= i {
		a.Items = append(a.Items, Undef{})
	}
	a.Items[i] = v
}

// GetIndex returns arr[key] for arbitrary keys.
func (rt *Runtime) GetIndex(obj Value, key Value) Value {
	switch t := key.(type) {
	case float64:
		if t == math.Trunc(t) && !math.IsInf(t, 0) {
			return rt.GetMember(obj, NumToString(t))
		}
		return rt.GetMember(obj, NumToString(t))
	case Str:
		return rt.GetMember(obj, string(t))
	case *RawNum:
		return rt.GetMember(obj, NumToString(t.V))
	}
	return rt.GetMember(obj, ToString(rt, key))
}

// SetIndex assigns obj[key] = v for arbitrary keys.
func (rt *Runtime) SetIndex(obj Value, key Value, v Value) {
	switch t := key.(type) {
	case float64:
		rt.SetMember(obj, NumToString(t), v)
		return
	case Str:
		rt.SetMember(obj, string(t), v)
		return
	}
	rt.SetMember(obj, ToString(rt, key), v)
}

// ToInt converts to an integer number.
func ToInt(v Value) (int, bool) {
	f := ToNumber(v)
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return 0, false
	}
	return int(math.Trunc(f)), true
}

// ToIndex converts to an array index or throws RangeError.
