		return "null"
	case Bool:
		if t {
			return "true"
		}
		return "false"
	case Str:
		return string(t)
	case float64:
		return NumToString(t)
	case *big.Int:
		return t.String()
	case *RawNum:
		return t.Raw
	case *Sym:
		return "Symbol(" + t.Desc + ")"
