func (rt *Runtime) ToObject(v Value) *Obj {
	switch t := v.(type) {
	case *Obj:
		return t
	case *Arr:
		o := NewObj(rt.ObjProto)
		o.cls = "Object"
		return o
	case Str:
		o := NewObj(rt.StrProto)
		o.cls = "String"
