		}
		o.Set("length", float64(len([]rune(string(t)))))
		return o
	case float64:
		o := NewObj(rt.NumProto)
		o.cls = "Number"
		o.SetPrimitive(v)
		return o
	case Bool:
		o := NewObj(rt.BoolProto)
		o.cls = "Boolean"
		o.SetPrimitive(v)
		return o
	case *Sym:
		o := NewObj(nil)
		o.cls = "Symbol"
		o.SetPrimitive(v)
		return o
	case *big.Int:
		o := NewObj(nil)
		o.cls = "BigInt"
		o.SetPrimitive(v)
		return o
	case *Date:
		o := NewObj(rt.DateProto)
		o.cls = "Date"
		o.SetPrimitive(v)
		return o
	case *Err:
		o := NewObj(rt.ErrProtos[t.Name])
		o.cls = t.Name
