// Eval evaluates an expression node.
func (rt *Runtime) Eval(n *Node, sc *Scope, this Value) Value {
	switch n.Kind {
	case KNum:
		return n.Num
	case KBig:
		return n.Big
	case KStr:
		return Str(n.Str)
	case KBool:
		return Bool(n.Bool)
	case KNull:
		return Null{}
	case KThis:
		return this
	case KIdent:
		if v := sc.lookup(n.Str); v != nil {
			return v.Val
		}
		if g := rt.Glob; g != nil {
			if v, ok := g.Get(n.Str); ok {
				return v
			}
		}
		panic(&Throw{Val: rt.NewError("ReferenceError", n.Str + " is not defined")})
	case KRegex:
		return rt.NewRegExp(n.Str, n.Flags)
	case KTpl:
		return rt.tplValue(n, sc, this)
	case KArray:
		return rt.arrayLit(n, sc, this)
	case KObject:
		return rt.objectLit(n, sc, this)
	case KFunc:
		return rt.makeFunc(n, sc, this)
	case KClass:
		return rt.makeClass(n, sc, this)
	case KNew:
		return rt.evalNew(n, sc, this)
	case KCall:
		return rt.evalCall(n, sc, this)
	case KMember:
		obj := rt.Eval(n.L, sc, this)
		if short, ok := obj.(*Short); ok {
			return short
		}
		var key Value
		if n.Compute {
			key = rt.Eval(n.X, sc, this)
		} else {
			key = Str(n.Str)
		}
		if n.Opt && isNullish(obj) {
			return &Short{}
		}
		return rt.GetIndex(obj, key)
	case KUnary:
		return rt.evalUnary(n, sc, this)
	case KUpdate:
		return rt.evalUpdate(n, sc, this)
	case KBinary:
		return rt.evalBinary(n, sc, this)
	case KLogical:
		return rt.evalLogical(n, sc, this)
	case KCond:
		if ToBool(rt.Eval(n.L, sc, this)) {
			return rt.Eval(n.R, sc, this)
		}
		return rt.Eval(n.X, sc, this)
	case KAssign:
		return rt.evalAssign(n, sc, this)
	case KSeq:
		var v Value = Undef{}
		for _, e := range n.List {
			v = rt.Eval(e, sc, this)
		}
		return v
	case KSpread:
		return rt.Eval(n.L, sc, this)
	}
	rt.ThrowError("Error", "not implemented: "+strconv.Itoa(n.Kind))
	return nil
}

// Short is a sentinel used by optional chains.
type Short struct{}

func (rt *Runtime) tplValue(n *Node, sc *Scope, this Value) Value {
	if len(n.List) == 0 {
		return Str(n.Str)
	}
	var b strings.Builder
	b.WriteString(n.Str)
	for i, e := range n.List {
		v := rt.Eval(e, sc, this)
		b.WriteString(ToString(rt, v))
		if i < len(n.Strs) {
			b.WriteString(n.Strs[i])
		}
	}
	return Str(b.String())
}

func (rt *Runtime) arrayLit(n *Node, sc *Scope, this Value) Value {
	arr := &Arr{}
	for _, e := range n.List {
		if e == nil {
			arr.Items = append(arr.Items, Undef{})
			continue
		}
		if e.Kind == KSpread {
			v := rt.Eval(e.L, sc, this)
			rt.appendSpread(arr, v)
			continue
		}
		arr.Items = append(arr.Items, rt.Eval(e, sc, this))
	}
	return arr
}

func (rt *Runtime) appendSpread(arr *Arr, v Value) {
	switch t := v.(type) {
	case *Arr:
		arr.Items = append(arr.Items, t.Items...)
	case *Obj:
		if t.cls == "String" {
			if s, ok := t.prim.(Str); ok {
				for _, c := range string(s) {
					arr.Items = append(arr.Items, Str(string(c)))
				}
			}
			return
		}
		rt.TypeError(ToString(rt, v) + " is not iterable")
	case Str:
		for _, c := range string(t) {
			arr.Items = append(arr.Items, Str(string(c)))
		}
	case *SetT:
		arr.Items = append(arr.Items, t.Items...)
	case *MapT:
		for i := range t.Keys {
			pair := &Arr{Items: []Value{t.Keys[i], t.Vals[i]}}
			arr.Items = append(arr.Items, pair)
		}
	default:
		if isUndef(v) || isNull(v) {
			rt.TypeError(ToString(rt, v) + " is not iterable")
		}
		rt.TypeError(ToString(rt, v) + " is not iterable")
	}
}

func (rt *Runtime) objectLit(n *Node, sc *Scope, this Value) Value {
	o := NewObj(rt.ObjProto)
	for _, p := range n.List {
		if p.Kind == KSpread {
			v := rt.Eval(p.L, sc, this)
			rt.assignSpreadObj(o, v)
			continue
		}
		var key string
		if p.L.Kind == KCompute {
			key = ToString(rt, rt.Eval(p.L.X, sc, this))
		} else {
			key = p.L.Str
		}
		if p.Method {
			o.Set(key, rt.Eval(p.R, sc, this))
			continue
		}
		o.Set(key, rt.Eval(p.R, sc, this))
	}
	return o
}

func (rt *Runtime) assignSpreadObj(o *Obj, v Value) {
	switch t := v.(type) {
	case *Obj:
		for _, p := range t.props {
			o.Set(p.Key, p.Val)
		}
	case *Arr:
		for i, it := range t.Items {
			o.Set(strconv.Itoa(i), it)
		}
	case Str:
		for i, c := range string(t) {
			o.Set(strconv.Itoa(i), Str(string(c)))
		}
	}
}

func (rt *Runtime) makeFunc(n *Node, sc *Scope, this Value) Value {
	f := &Func{Name: n.Str, Closure: &Closure{Node: n, Scope: sc, Name: n.Str, This: this}}
	return f
}

func (rt *Runtime) makeClass(n *Node, sc *Scope, this Value) Value {
	proto := NewObj(rt.ObjProto)
	ctor := &Func{Name: n.Str, Closure: &Closure{Node: n.Y, Scope: sc, Name: n.Str, This: this}}
	ctor.ClassProto = proto
	ctor.IsClass = true
	ctor.Super = n.L
	if n.Y == nil {
		ctor.Closure = nil
	}
	for _, m := range n.List {
		key := m.L.Str
		fn := rt.Eval(m.R, sc, this).(*Func)
		if m.Decl {
			ctor.Set(key, fn)
			continue
		}
		proto.Set(key, fn)
	}
	proto.Set("constructor", ctor)
	return ctor
}

func (rt *Runtime) evalNew(n *Node, sc *Scope, this Value) Value {
	f := rt.Eval(n.L, sc, this)
	var args []Value
	for _, a := range n.List {
		if a.Kind == KSpread {
			v := rt.Eval(a.L, sc, this)
			if arr, ok := v.(*Arr); ok {
				args = append(args, arr.Items...)
				continue
			}
			rt.TypeError("Spread syntax requires iterable")
		}
		args = append(args, rt.Eval(a, sc, this))
	}
	return rt.construct(f, args)
}

func (rt *Runtime) construct(f Value, args []Value) Value {
	fn, ok := f.(*Func)
	if !ok {
		rt.TypeError("Value is not a constructor: " + ToString(rt, f))
	}
	var proto *Obj
	if fn.ClassProto != nil {
		proto = fn.ClassProto
	} else if pv, ok := fn.Get("prototype"); ok {
		if p, ok := pv.(*Obj); ok {
			proto = p
		}
	}
	if proto == nil {
		proto = rt.ObjProto
	}
	obj := NewObj(proto)
	obj.cls = "Object"
	if fn.Native != nil {
		if fn.NativeConstructor != nil {
			return fn.NativeConstructor(rt, obj, args)
		}
		return fn.Native(rt, obj, args)
	}
	rt.callFunc(fn, obj, args)
	return obj
}

func (rt *Runtime) evalCall(n *Node, sc *Scope, this Value) Value {
	callee := rt.Eval(n.L, sc, this)
	if short, ok := callee.(*Short); ok {
		return short
	}
	var args []Value
	for _, a := range n.List {
		if a.Kind == KSpread {
			v := rt.Eval(a.L, sc, this)
			if arr, ok := v.(*Arr); ok {
				args = append(args, arr.Items...)
				continue
			}
			rt.appendSpreadArgs(&args, v)
			continue
		}
		args = append(args, rt.Eval(a, sc, this))
	}
	return rt.Call(callee, this, args)
}

func (rt *Runtime) appendSpreadArgs(args *[]Value, v Value) {
	if arr, ok := v.(*Arr); ok {
		*args = append(*args, arr.Items...)
		return
	}
	if s, ok := v.(Str); ok {
		for _, c := range string(s) {
			*args = append(*args, Str(string(c)))
		}
		return
	}
	if st, ok := v.(*SetT); ok {
		*args = append(*args, st.Items...)
		return
	}
	rt.TypeError(ToString(rt, v) + " is not iterable")
}

// Call invokes a value.
func (rt *Runtime) Call(f Value, this Value, args []Value) Value {
	return rt.callValue(f, this, args)
}

func (rt *Runtime) callValue(f Value, this Value, args []Value) Value {
	switch t := f.(type) {
	case *Func:
		return rt.callFunc(t, this, args)
	case *Obj:
		if t.cls == "Function" || t.cls == "class" {
			if pv, ok := t.Get("[[Call]]"); ok {
				if fn, ok := pv.(*Func); ok {
					return rt.callFunc(fn, this, args)
				}
			}
		}
		rt.TypeError("Not a function: " + ToString(rt, f))
	case *Short:
		return t
	case *Proxy:
		return rt.proxyCall(t, this, args)
	}
	if isNullish(f) {
		rt.TypeError("Value is not an object: " + ToString(rt, f))
	}
	rt.TypeError("Not a function: " + ToString(rt, f))
	return nil
}

func (rt *Runtime) callFunc(f *Func, this Value, args []Value) Value {
	if f.Native != nil {
		return f.Native(rt, this, args)
	}
	c := f.Closure
	sc := newScope(c.Scope)
	if c.Node == nil {
		// default class constructor
		return Undef{}
	}
	params := c.Node.List
	for i, p := range params {
		if p == nil {
			continue
		}
		if p.Kind == KSpread {
			if v, ok := sc.lookup(p.Str); v != nil || ok {
			}
			rest := &Arr{Items: []Value{}}
			if i < len(args) {
				rest.Items = append(rest.Items, args[i:]...)
			}
			sc.declare(p.Str, rest)
			break
		}
		if p.Kind == KIdent {
			if i < len(args) {
				sc.declare(p.Str, args[i])
			} else {
				sc.declare(p.Str, Undef{})
			}
			continue
		}
		if p.Kind == KAssign {
			if i < len(args) {
				rt.bindPattern(p.L, args[i], sc)
			} else {
				d := rt.Eval(p.R, sc, this)
				rt.bindPattern(p.L, d, sc)
			}
			continue
		}
		if p.Kind == KArray || p.Kind == KObject {
			if i < len(args) {
				rt.bindPattern(p, args[i], sc)
			} else {
				rt.bindPattern(p, Undef{}, sc)
			}
			continue
		}
	}
	// this binding for non-arrow functions
	fnThis := this
	if c.Node.Async || c.Node.Gen {
		// keep as-is
	}
	if f.Name != "" {
		if _, ok := sc.vars[f.Name]; !ok {
			sc.declare(f.Name, f)
		}
	}
	rt.execBlock(c.Node.L, sc, fnThis)
	return Undef{}
}

func (rt *Runtime) proxyCall(p *Proxy, this Value, args []Value) Value {
	rt.TypeError("Not a function: " + ToString(rt, p))
	return nil
}

// Exec executes a statement.
func (rt *Runtime) exec(n *Node, sc *Scope, this Value) {
	switch n.Kind {
	case KEmpty, KDebugger:
		return
	case KExprStmt:
		rt.Eval(n.L, sc, this)
		return
	case KBlock:
		rt.execBlock(n, sc, this)
		return
	case KReturn:
		panic(ReturnSig{Val: rt.evalMaybeUndefined(n.L, sc, this)})
	case KIf:
		if ToBool(rt.Eval(n.L, sc, this)) {
			rt.exec(n.R, sc, this)
		} else if n.X != nil {
			rt.exec(n.X, sc, this)
		}
		return
	case KFor:
		rt.execFor(n, sc, this)
		return
	case KForIn:
		rt.execForIn(n, sc, this)
		return
	case KWhile:
		rt.execWhile(n, sc, this)
		return
	case KTry:
		rt.execTry(n, sc, this)
		return
	case KThrow:
		v := rt.Eval(n.L, sc, this)
		panic(&Throw{Val: v})
	case KVar:
		for _, d := range n.List {
			if d.R == nil {
				rt.bindPattern(d.L, Undef{}, sc)
				continue
			}
			rt.bindPattern(d.L, rt.Eval(d.R, sc, this), sc)
		}
		return
	case KBreak:
		panic(BreakSig{})
	case KContinue:
		panic(ContinueSig{})
	case KSwitch:
		rt.execSwitch(n, sc, this)
		return
	case KLabel:
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch s := r.(type) {
					case BreakSig:
						if s.Label == n.Str {
							return
						}
					case ContinueSig:
						if s.Label == n.Str {
							return
						}
					}
					panic(r)
				}
			}()
			rt.exec(n.L, sc, this)
		}()
		return
	}
	rt.ThrowError("Error", "unknown statement")
}

func (rt *Runtime) evalMaybeUndefined(n *Node, sc *Scope, this Value) Value {
	if n == nil {
		return Undef{}
	}
	return rt.Eval(n, sc, this)
}

func (rt *Runtime) execBlock(n *Node, sc *Scope, this Value) {
	if n == nil {
		return
	}
	for _, st := range n.List {
		rt.exec(st, sc, this)
	}
}

func (rt *Runtime) execFor(n *Node, sc *Scope, this Value) {
	body := sc
	if n.L != nil {
		rt.exec(n.L, body, this)
	}
	for {
		if n.R != nil && !ToBool(rt.Eval(n.R, body, this)) {
			break
		}
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch r.(type) {
					case BreakSig:
						panic(r)
					case ContinueSig:
						return
					}
					panic(r)
				}
			}()
			rt.exec(n.Y, body, this)
		}()
		if n.X != nil {
			rt.exec(n.X, body, this)
		}
	}
}

func (rt *Runtime) execWhile(n *Node, sc *Scope, this Value) {
	isDo := n.Op == "do"
	for {
		if !isDo && !ToBool(rt.Eval(n.L, sc, this)) {
			break
		}
		broke := false
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch r.(type) {
					case BreakSig:
						broke = true
					case ContinueSig:
						broke = false
					default:
						panic(r)
					}
				}
			}()
			rt.exec(n.R, sc, this)
		}()
		if broke {
			break
		}
		if isDo && !ToBool(rt.Eval(n.L, sc, this)) {
			break
		}
	}
}

func (rt *Runtime) execForIn(n *Node, sc *Scope, this Value) {
	obj := rt.Eval(n.R, sc, this)
	var keys []string
	switch t := obj.(type) {
	case *Obj:
		if t.cls == "Array" || t.cls == "String" {
			// arrays are *Arr
		}
		for _, p := range t.props {
			keys = append(keys, p.Key)
		}
	case *Arr:
		for i := range t.Items {
			keys = append(keys, strconv.Itoa(i))
		}
	case Str:
		for i := range []rune(string(t)) {
			keys = append(keys, strconv.Itoa(i))
		}
	case *MapT:
		for i := range t.Keys {
			keys = append(keys, ToString(rt, t.Keys[i]))
		}
	case *SetT:
		for i := range t.Items {
			keys = append(keys, strconv.Itoa(i))
		}
	case Undef, Null:
		// no iteration
	default:
		rt.TypeError("object is not iterable")
	}
	for _, k := range keys {
		v := Value(Str(k))
		if n.Op == "of" {
			switch t := obj.(type) {
			case *Arr:
				i, _ := strconv.Atoi(k)
				v = t.Items[i]
			case Str:
				i, _ := strconv.Atoi(k)
				v = Str(string([]rune(string(t))[i]))
			case *SetT:
				i, _ := strconv.Atoi(k)
				v = t.Items[i]
			case *MapT:
				i, _ := strconv.Atoi(k)
				v = t.Vals[i]
			}
		}
		if n.Decl && n.L != nil {
			rt.declarePattern(n.L, v, sc)
		} else {
			rt.bindPattern(n.L, v, sc)
		}
		broke := false
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch r.(type) {
					case BreakSig:
						broke = true
					case ContinueSig:
					default:
						panic(r)
					}
				}
			}()
			rt.exec(n.X, sc, this)
		}()
		if broke {
			break
		}
	}
}

func (rt *Runtime) execSwitch(n *Node, sc *Scope, this Value) {
	disc := rt.Eval(n.L, sc, this)
	idx := -1
	for i, c := range n.List {
		if c.Kind == KNull {
			idx = i
			continue
		}
		if looseEqual(rt.Eval(c.L, sc, this), disc) {
			idx = i
			break
		}
	}
	if idx < 0 {
		for i, c := range n.List {
			if c.Kind == KNull {
				idx = i
				break
			}
		}
	}
	if idx < 0 {
		return
	}
	for i := idx; i < len(n.List); i++ {
		c := n.List[i]
		broke := false
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch r.(type) {
					case BreakSig:
						broke = true
					case ContinueSig:
					default:
						panic(r)
					}
				}
			}()
			for _, st := range c.List {
				rt.exec(st, sc, this)
			}
		}()
		if broke {
			break
		}
	}
}

func (rt *Runtime) execTry(n *Node, sc *Scope, this Value) {
	func() {
		defer func() {
			r := recover()
			if r != nil {
				th, ok := r.(*Throw)
				if ok && n.R != nil {
					cs := newScope(sc)
					if n.Str != "" {
						cs.declare(n.Str, th.Val)
					}
					rt.exec(n.R, cs, this)
					r = nil
				} else if !ok {
					panic(r)
				} else {
					panic(r)
				}
			}
			if r != nil {
				panic(r)
			}
			if n.X != nil {
				rt.exec(n.X, newScope(sc), this)
			}
		}()
		rt.exec(n.L, newScope(sc), this)
		if n.X != nil {
			rt.exec(n.X, newScope(sc), this)
		}
	}()
}

func (rt *Runtime) evalUnary(n *Node, sc *Scope, this Value) Value {
	switch n.Op {
	case "!":
		return Bool(!ToBool(rt.Eval(n.L, sc, this)))
	case "-":
		return rt.Negate(rt.Eval(n.L, sc, this))
	case "+":
		return ToNumber(rt.Eval(n.L, sc, this))
	case "~":
		f := ToNumber(rt.Eval(n.L, sc, this))
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return float64(-1)
		}
		i := int64(math.Trunc(f))
		return float64(^i)
	case "typeof":
		v, target := rt.evalRef(n.L, sc, this)
		if target != nil && !target.found {
			return Str("undefined")
		}
		if short, ok := v.(*Short); ok {
			return Str(ToString(rt, short))
		}
		return Str(rt.TypeOf(v))
	case "void":
		rt.Eval(n.L, sc, this)
		return Undef{}
	case "delete":
		return rt.evalDelete(n.L, sc, this)
	case "await":
		return rt.Eval(n.L, sc, this)
	}
	rt.ThrowError("Error", "unknown unary op "+n.Op)
	return nil
}

func (rt *Runtime) Negate(v Value) Value {
	if b, ok := v.(*big.Int); ok {
		return new(big.Int).Neg(b)
	}
	return -ToNumber(v)
}

// TypeOf implements the typeof operator.
func (rt *Runtime) TypeOf(v Value) string {
	switch t := v.(type) {
	case nil, Undef:
		return "undefined"
	case Null:
		return "object"
	case Bool:
		return "boolean"
	case Str:
		return "string"
	case float64, *RawNum:
		return "number"
	case *big.Int:
		return "bigint"
	case *Sym:
		return "symbol"
	case *Func:
		return "function"
	case *Obj:
		return "object"
	}
	return "object"
}

type refInfo struct {
	found bool
}

func (rt *Runtime) evalRef(n *Node, sc *Scope, this Value) (Value, *refInfo) {
	if n.Kind == KIdent {
		if v := sc.lookup(n.Str); v != nil {
			return v.Val, &refInfo{found: true}
		}
		if g := rt.Glob; g != nil {
			if v, ok := g.Get(n.Str); ok {
				return v, &refInfo{found: true}
			}
		}
		return nil, &refInfo{}
	}
	return rt.Eval(n, sc, this), &refInfo{found: true}
}

func (rt *Runtime) evalDelete(n *Node, sc *Scope, this Value) Value {
	if n.Kind == KMember {
		obj := rt.Eval(n.L, sc, this)
		if o, ok := obj.(*Obj); ok {
			if n.Compute {
				k := rt.Eval(n.X, sc, this)
				o.Del(ToString(rt, k))
			} else {
				o.Del(n.Str)
			}
			return Bool(true)
		}
		if a, ok := obj.(*Arr); ok {
			var k string
			if n.Compute {
				k = ToString(rt, rt.Eval(n.X, sc, this))
			} else {
				k = n.Str
			}
			if i, ok := arrayIndex(k); ok {
				if i < len(a.Items) {
					a.Items[i] = nil
				}
			}
			return Bool(true)
		}
		return Bool(true)
	}
	if n.Kind == KIdent {
		sc.set(n.Str, Undef{})
		return Bool(true)
	}
	return Bool(true)
}

func (rt *Runtime) evalUpdate(n *Node, sc *Scope, this Value) Value {
	old := rt.Eval(n.L, sc, this)
	var oldNum Value
	switch t := old.(type) {
	case *big.Int:
		if n.Op == "++" {
			oldNum = new(big.Int).Add(t, big.NewInt(1))
		} else {
			oldNum = new(big.Int).Sub(t, big.NewInt(1))
		}
	default:
		f := ToNumber(old)
		if n.Op == "++" {
			oldNum = f + 1
		} else {
			oldNum = f - 1
		}
	}
	rt.assignTo(n.L, oldNum, sc, this)
	if n.Prefix {
		return oldNum
	}
	switch t := old.(type) {
	case *big.Int:
		return t
	}
	return ToNumber(old)
}

func (rt *Runtime) evalBinary(n *Node, sc *Scope, this Value) Value {
	l := rt.Eval(n.L, sc, this)
	r := rt.Eval(n.R, sc, this)
	return rt.BinOp(n.Op, l, r)
}

func (rt *Runtime) evalLogical(n *Node, sc *Scope, this Value) Value {
	switch n.Op {
	case "&&":
		l := rt.Eval(n.L, sc, this)
		if !ToBool(l) {
			return l
		}
		return rt.Eval(n.R, sc, this)
	case "||":
		l := rt.Eval(n.L, sc, this)
		if ToBool(l) {
			return l
		}
		return rt.Eval(n.R, sc, this)
	case "??":
		l := rt.Eval(n.L, sc, this)
		if !isNullish(l) {
			return l
		}
		return rt.Eval(n.R, sc, this)
	}
	rt.ThrowError("Error", "unknown logical op")
	return nil
}

func (rt *Runtime) evalAssign(n *Node, sc *Scope, this Value) Value {
	if n.R == nil {
		rt.bindPattern(n.L, Undef{}, sc)
		return Undef{}
	}
	v := rt.Eval(n.R, sc, this)
	if n.Op == "=" {
		rt.assignTo(n.L, v, sc, this)
		return v
	}
	// compound assignment
	var cur Value
	switch n.L.Kind {
	case KIdent:
		if vr := sc.lookup(n.L.Str); vr != nil {
			cur = vr.Val
		} else if g, ok := rt.Glob.Get(n.L.Str); ok {
			cur = g
		} else {
			panic(&Throw{Val: rt.NewError("ReferenceError", n.L.Str + " is not defined")})
		}
	case KMember:
		obj := rt.Eval(n.L.L, sc, this)
		if n.L.Compute {
			cur = rt.GetIndex(obj, rt.Eval(n.L.X, sc, this))
		} else {
			cur = rt.GetIndex(obj, Str(n.L.Str))
		}
	default:
		cur = rt.Eval(n.L, sc, this)
	}
	res := rt.BinOp(strings.TrimSuffix(n.Op, "="), cur, v)
	rt.assignTo(n.L, res, sc, this)
	return res
}

// BinOp implements binary operators.
func (rt *Runtime) BinOp(op string, l, r Value) Value {
	switch op {
	case "+":
		if isStr(l) || isStr(r) {
			return Str(ToString(rt, l) + ToString(rt, r))
		}
		if lb, ok := l.(*big.Int); ok {
			if rb, ok := r.(*big.Int); ok {
				return new(big.Int).Add(lb, rb)
			}
			rt.TypeError("Cannot mix BigInt and other types, use explicit conversions")
		}
		if _, ok := r.(*big.Int); ok {
			rt.TypeError("Cannot mix BigInt and other types, use explicit conversions")
		}
		return ToNumber(l) + ToNumber(r)
	case "-", "*", "/", "%":
		if lb, ok := l.(*big.Int); ok {
			if rb, ok := r.(*big.Int); ok {
				if op == "/" && rb.Sign() == 0 {
					rt.RangeError("Division by zero")
				}
				if op == "%" && rb.Sign() == 0 {
					rt.RangeError("Division by zero")
				}
				return bigBinOp(op, lb, rb)
			}
			rt.TypeError("Cannot mix BigInt and other types, use explicit conversions")
		}
		if _, ok := r.(*big.Int); ok {
			rt.TypeError("Cannot mix BigInt and other types, use explicit conversions")
		}
		a, b := ToNumber(l), ToNumber(r)
		switch op {
		case "-":
			return a - b
		case "*":
			return a * b
		case "/":
			return a / b
		case "%":
			return math.Mod(a, b)
		}
	case "**":
		if lb, ok := l.(*big.Int); ok {
			if rb, ok := r.(*big.Int); ok {
				if rb.Sign() < 0 {
					rt.RangeError("Exponent must be non-negative")
				}
				return new(big.Int).Exp(lb, rb, nil)
			}
			rt.TypeError("Cannot mix BigInt and other types, use explicit conversions")
		}
		return math.Pow(ToNumber(l), ToNumber(r))
	case "==":
		return Bool(looseEqual(l, r))
	case "!=":
		return Bool(!looseEqual(l, r))
	case "===":
		return Bool(strictEqual(l, r))
	case "!==":
		return Bool(!strictEqual(l, r))
	case "<", ">", "<=", ">=":
		cmp, ok := rt.compare(l, r)
		if !ok {
			return Bool(false)
		}
		switch op {
		case "<":
			return Bool(cmp < 0)
		case ">":
			return Bool(cmp > 0)
		case "<=":
			return Bool(cmp <= 0)
		case ">=":
			return Bool(cmp >= 0)
		}
	case "&", "|", "^", "<<", ">>", ">>>":
		return rt.bitOp(op, l, r)
	case "in":
		return Bool(rt.hasProperty(r, l))
	case "instanceof":
		return Bool(rt.instanceOf(l, r))
	}
	rt.ThrowError("Error", "unknown operator "+op)
	return nil
}

func bigBinOp(op string, a, b *big.Int) *big.Int {
	switch op {
	case "-":
		return new(big.Int).Sub(a, b)
	case "*":
		return new(big.Int).Mul(a, b)
	case "/":
		return new(big.Int).Quo(a, b)
	case "%":
		return new(big.Int).Rem(a, b)
	}
	return nil
}

func isStr(v Value) bool {
	_, ok := v.(Str)
	return ok
}

func strictEqual(a, b Value) bool {
	if isNullish(a) && isNullish(b) {
		return true
	}
	if isNullish(a) || isNullish(b) {
		return false
	}
	switch x := a.(type) {
	case Str:
		y, ok := b.(Str)
		return ok && x == y
	case float64:
		y, ok := b.(float64)
		return ok && x == y
	case *RawNum:
		y, ok := b.(*RawNum)
		return ok && x.V == y.V
	case *big.Int:
		y, ok := b.(*big.Int)
		return ok && x.Cmp(y) == 0
	case Bool:
		y, ok := b.(Bool)
		return ok && x == y
	case *Sym:
		return a == b
	}
	return a == b
}

func looseEqual(a, b Value) bool {
	if a == nil || b == nil {
		return isNullish(a) && isNullish(b)
	}
	switch x := a.(type) {
	case Undef:
		_, ok := b.(Undef)
		return ok
	case Null:
		_, ok := b.(Null)
		return ok
	case Bool:
		return looseEqual(ToNumber(a), b)
	case float64, *RawNum:
		switch y := b.(type) {
		case Str:
			return ToNumber(a) == strToNumber(string(y))
		case Bool:
			return ToNumber(a) == ToNumber(b)
		case float64, *RawNum:
			return ToNumber(a) == ToNumber(b)
		case *big.Int:
			bi, _ := new(big.Float).SetInt(y).Float64()
			return ToNumber(a) == bi
		default:
			return false
		}
	case Str:
		switch y := b.(type) {
		case Str:
			return x == y
		case float64, *RawNum, Bool:
			return strToNumber(string(x)) == ToNumber(b)
		case *big.Int:
			bi, _ := new(big.Float).SetInt(y).Float64()
			return strToNumber(string(x)) == bi
		default:
			return false
		}
	case *big.Int:
		switch y := b.(type) {
		case *big.Int:
			return x.Cmp(y) == 0
		case float64, *RawNum, Bool, Str:
			bi := new(big.Float).SetInt(x)
			bf, _ := bi.Float64()
			return bf == ToNumber(b)
		}
		return false
	case *Sym:
		y, ok := b.(*Sym)
		return ok && x == y
	}
	switch y := b.(type) {
	case float64, *RawNum, Str, Bool, *big.Int:
		return looseEqual(b, a)
	case Undef, Null:
		return false
	}
	return a == b
}

// compare returns -1, 0, 1 for <, ==, >.
func (rt *Runtime) compare(l, r Value) (int, bool) {
	if isStr(l) && isStr(r) {
		a, b := string(l.(Str)), string(r.(Str))
		if a < b {
			return -1, true
		}
		if a > b {
			return 1, true
		}
		return 0, true
	}
	if lb, ok := l.(*big.Int); ok {
		if rb, ok := r.(*big.Int); ok {
			return lb.Cmp(rb), true
		}
	}
	a, b := ToNumber(l), ToNumber(r)
	if math.IsNaN(a) || math.IsNaN(b) {
		return 0, false
	}
	switch {
	case a < b:
		return -1, true
	case a > b:
		return 1, true
	}
	return 0, true
}

func (rt *Runtime) bitOp(op string, l, r Value) Value {
	if lb, ok := l.(*big.Int); ok {
		if rb, ok := r.(*big.Int); ok {
			switch op {
			case "&":
				return new(big.Int).And(lb, rb)
			case "|":
				return new(big.Int).Or(lb, rb)
			case "^":
				return new(big.Int).Xor(lb, rb)
			case "<<":
				return new(big.Int).Lsh(lb, uint(rt.ToIndex(r)))
			case ">>":
				return new(big.Int).Rsh(lb, uint(rt.ToIndex(r)))
			}
		}
		rt.TypeError("Cannot mix BigInt and other types, use explicit conversions")
	}
	a := toInt32(l)
	b := toInt32(r)
	switch op {
	case "&":
		return float64(a & b)
	case "|":
		return float64(a | b)
	case "^":
		return float64(a ^ b)
	case "<<":
		return float64(int32(a << (uint(b) & 31)))
	case ">>":
		return float64(a >> (uint(b) & 31))
	case ">>>":
		return float64(uint32(a) >> (uint(b) & 31))
	}
	return nil
}

func toInt32(v Value) int32 {
	f := ToNumber(v)
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return 0
	}
	i := int64(math.Trunc(f))
	return int32(uint32(i))
}

// hasProperty implements the `in` operator.
func (rt *Runtime) hasProperty(obj Value, key Value) Value {
	switch t := obj.(type) {
	case *Arr:
		if s := ToString(rt, key); s == "length" {
			return Bool(true)
		} else if i, ok := arrayIndex(s); ok {
			return Bool(i >= 0 && i < len(t.Items))
		}
	case *Obj:
		if _, ok := t.Get(ToString(rt, key)); ok {
			return Bool(true)
		}
		for p := t.proto; p != nil; p = p.proto {
			if _, ok := p.Get(ToString(rt, key)); ok {
				return Bool(true)
			}
		}
		return Bool(false)
	case Str:
		s := ToString(rt, key)
		if s == "length" {
			return Bool(true)
		}
		if i, ok := arrayIndex(s); ok {
			return Bool(i >= 0 && i < len([]rune(string(t))))
		}
		return Bool(rt.protoMember(rt.StrProto, s) != Undef{})
	}
	return Bool(false)
}

func (rt *Runtime) instanceOf(l, r Value) bool {
	fn, ok := r.(*Func)
	if !ok {
		rt.TypeError("Right-hand side of 'instanceof' is not an object")
	}
	proto := Value(nil)
	if fn.ClassProto != nil {
		proto = fn.ClassProto
	} else if pv, ok := fn.Get("prototype"); ok {
		proto = pv
	}
	if proto == nil {
		return false
	}
	// special cases for built-in classes
	switch x := l.(type) {
	case *Arr:
		return fn.Name == "Array"
	case *Date:
		return fn.Name == "Date"
	case *Err:
		return fn.Name == "Error" || fn.Name == x.Name
	case *MapT:
		return fn.Name == "Map"
	case *SetT:
		return fn.Name == "Set"
	case *RegExp:
		return fn.Name == "RegExp"
	case *Promise:
		return fn.Name == "Promise"
	case *Proxy:
		return fn.Name == "Proxy"
	case *TypedArray:
		return fn.Name == x.Kind
	case *ArrayBuffer:
		return fn.Name == "ArrayBuffer"
	case Str:
		if x2, ok := l.(Str); ok {
			_ = x2
		}
	}
	// walk the prototype chain
	cur := rt.protoOf(l)
	for cur != nil {
		if cur == proto {
			return true
		}
		cur = cur.proto
	}
	return false
}

func (rt *Runtime) protoOf(v Value) *Obj {
	switch t := v.(type) {
	case *Obj:
		return t.proto
	case *Arr:
		return rt.ArrProto
	case Str:
		return rt.StrProto
	case float64:
		return rt.NumProto
	case Bool:
		return rt.BoolProto
	case *Date:
		return rt.DateProto
	case *Err:
		return rt.ErrProtos[t.Name]
	}
	return nil
}

// assignTo assigns a value to an lvalue (identifier, member or pattern).
func (rt *Runtime) assignTo(target *Node, v Value, sc *Scope, this Value) {
	switch target.Kind {
	case KIdent:
		sc.set(target.Str, v)
		return
	case KMember:
		obj := rt.Eval(target.L, sc, this)
		if target.Compute {
			rt.SetIndex(obj, rt.Eval(target.X, sc, this), v)
		} else {
			rt.SetIndex(obj, Str(target.Str), v)
		}
		return
	case KArray:
		rt.bindPattern(target, v, sc)
		return
	case KObject:
		rt.bindPattern(target, v, sc)
		return
	}
	rt.TypeError("Invalid left-hand side in assignment ")
}

// bindPattern binds a destructuring pattern.
func (rt *Runtime) bindPattern(pat *Node, v Value, sc *Scope) {
	switch pat.Kind {
	case KIdent:
		sc.set(pat.Str, v)
	case KArray:
		items := rt.iterableItems(v)
		idx := 0
		for _, e := range pat.List {
			if e == nil {
				idx++
				continue
			}
			if e.Kind == KSpread {
				rest := &Arr{Items: []Value{}}
				if idx < len(items) {
					rest.Items = append(rest.Items, items[idx:]...)
				}
				rt.bindPattern(e.L, rest, sc)
				return
			}
			var item Value = Undef{}
			if idx < len(items) {
				item = items[idx]
			}
			if e.Kind == KAssign {
				if idx >= len(items) || isNullish(items[idx]) {
					rt.bindPattern(e.L, rt.Eval(e.R, sc, nil), sc)
				} else {
					rt.bindPattern(e.L, item, sc)
				}
			} else {
				rt.bindPattern(e, item, sc)
			}
			idx++
		}
	case KObject:
		for _, p := range pat.List {
			if p.Kind == KSpread {
				rest := NewObj(rt.ObjProto)
				used := map[string]bool{}
				for _, q := range pat.List {
					if q.Kind == KSpread {
						continue
					}
					if q.L.Kind == KCompute {
						used[ToString(rt, rt.Eval(q.L.X, sc, nil))] = true
					} else {
						used[q.L.Str] = true
					}
				}
				if o, ok := v.(*Obj); ok {
					for _, pr := range o.props {
						if !used[pr.Key] {
							rest.Set(pr.Key, pr.Val)
						}
					}
				}
				rt.bindPattern(p.L, rest, sc)
				continue
			}
			var key string
			if p.L.Kind == KCompute {
				key = ToString(rt, rt.Eval(p.L.X, sc, nil))
			} else {
				key = p.L.Str
			}
			val := rt.GetIndex(v, Str(key))
			if p.R.Kind == KAssign {
				if isNullish(val) {
					rt.bindPattern(p.R.L, rt.Eval(p.R.R, sc, nil), sc)
				} else {
					rt.bindPattern(p.R.L, val, sc)
				}
			} else {
				rt.bindPattern(p.R, val, sc)
			}
		}
	case KAssign:
		rt.bindPattern(pat.L, v, sc)
	}
}

// declarePattern declares a binding in the current scope (for let/const/var).
func (rt *Runtime) declarePattern(pat *Node, v Value, sc *Scope) {
	switch pat.Kind {
	case KIdent:
		sc.declare(pat.Str, v)
	case KArray, KObject, KAssign:
		rt.bindPattern(pat, v, sc)
	}
}

func (rt *Runtime) iterableItems(v Value) []Value {
	switch t := v.(type) {
	case *Arr:
		return t.Items
	case Str:
		var out []Value
		for _, c := range string(t) {
			out = append(out, Str(string(c)))
		}
		return out
	case *SetT:
		return t.Items
	case *Obj:
		if t.cls == "String" {
			if s, ok := t.prim.(Str); ok {
				var out []Value
				for _, c := range string(s) {
					out = append(out, Str(string(c)))
				}
				return out
			}
		}
	}
	rt.TypeError(ToString(rt, v) + " is not iterable")
	return nil
}

