	objFn := &Func{Name: "Object", Native: func(rt *Runtime, this Value, args []Value) Value {
		if len(args) == 0 || isNullish(args[0]) {
			return NewObj(rt.ObjProto)
		}
		return rt.ToObject(args[0])
