	}))
	objFn.Set("assign", native("assign", func(rt *Runtime, this Value, args []Value) Value {
		t := rt.ToObject(rt.arg(args, 0))
		for _, a := range args[1:] {
			src := rt.ToObject(a)
			if src == nil {
				continue
			}
			for _, p := range src.props {
				t.Set(p.Key, p.Val)
			}
		}
		return t
	}))
	objFn.Set("freeze", native("freeze", func(rt *Runtime, this Value, args []Value) Value {
		return rt.arg(args, 0)
	}))
	objFn.Set("isFrozen", native("isFrozen", func(rt *Runtime, this Value, args []Value) Value {
		return Bool(false)
	}))
	objFn.Set("seal", native("seal", func(rt *Runtime, this Value, args []Value) Value {
		return rt.arg(args, 0)
	}))
	objFn.Set("preventExtensions", native("preventExtensions", func(rt *Runtime, this Value, args []Value) Value {
