func (rt *Runtime) ownEnumerableKeys(v Value) []string {
	switch t := v.(type) {
	case *Arr:
		out := []string{}
		for i := range t.Items {
			out = append(out, strconv.Itoa(i))
		}
		return out
	case *Obj:
		if t.cls == "String" {
			if s, ok := t.prim.(Str); ok {
				var out []string
				for i := range []rune(string(s)) {
					out = append(out, strconv.Itoa(i))
				}
				return out
			}
		}
		var out []string
		for _, p := range t.props {
			out = append(out, p.Key)
		}
		return out
	case Str:
		var out []string
		for i := range []rune(string(t)) {
			out = append(out, strconv.Itoa(i))
		}
		return out
	case *MapT:
		var out []string
		for i := range t.Keys {
			out = append(out, strconv.Itoa(i))
		}
		return out
	case *SetT:
		var out []string
		for i := range t.Items {
			out = append(out, strconv.Itoa(i))
		}
		return out
	}
	return nil
}

func (rt *Runtime) ownEnumerable(v Value) []Value {
	switch t := v.(type) {
	case *Arr:
		return t.Items
	case *Obj:
		if t.cls == "String" {
			if s, ok := t.prim.(Str); ok {
				var out []Value
				for _, c := range []rune(string(s)) {
					out = append(out, Str(string(c)))
				}
				return out
			}
		}
		return t.Values()
	case Str:
		var out []Value
		for _, c := range []rune(string(t)) {
			out = append(out, Str(string(c)))
		}
		return out
	case *MapT:
		return t.Vals
	case *SetT:
		return t.Items
	}
	return nil
}

func (rt *Runtime) classOf(v Value) string {
	switch t := v.(type) {
	case *Arr:
		return "Array"
	case *Obj:
		return t.cls
	case Str:
		return "String"
	case float64:
		return "Number"
	case Bool:
		return "Boolean"
	case *big.Int:
		return "BigInt"
	case *Sym:
		return "Symbol"
	case *Date:
		return "Date"
	case *Err:
		return "Error"
	case *MapT:
		return "Map"
	case *SetT:
		return "Set"
	case *RegExp:
		return "RegExp"
	case *Promise:
		return "Promise"
	case *Func:
		return "Function"
	}
	return "Object"
}

