type breakLoop struct{}

func (rt *Runtime) forEachIdx(a *Arr, fn func(v Value, i int)) {
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(breakLoop); ok {
				return
			}
			panic(r)
		}
	}()
	for i, v := range a.Items {
		fn(v, i)
	}
}

func (rt *Runtime) joinStrings(a *Arr) string {
	parts := make([]string, len(a.Items))
	for i, v := range a.Items {
		if isNullish(v) {
			continue
		}
		parts[i] = ToString(rt, v)
	}
	return strings.Join(parts, ",")
}

func (rt *Runtime) clampIndex(f float64, length int, fromEnd bool) int {
	if math.IsNaN(f) {
		f = 0
	}
	i := int(math.Trunc(f))
	if i < 0 {
		i += length
		if i < 0 {
			i = 0
		}
	}
	if i > length {
		i = length
	}
	return i
}

func (rt *Runtime) toArray(this Value) *Arr {
	switch t := this.(type) {
	case *Arr:
		return t
	case *Obj:
		if t.cls == "Array" {
			if a, ok := t.prim.(*Arr); ok {
				return a
			}
		}
	}
	rt.TypeError("Value is not an object: " + ToString(rt, this))
	return nil
}

func (rt *Runtime) callWith(fn Value, this Value, v Value, i int, arr Value) Value {
	return rt.callValue(fn, this, []Value{v, float64(i), arr})
}

// SymIterFn returns the iterator function for arrays.
func (rt *Runtime) SymIterFn() *Func {
	return native("[Symbol.iterator]", func(rt *Runtime, this Value, args []Value) Value {
		var items []Value
		switch t := this.(type) {
		case *Arr:
			items = t.Items
		case Str:
			for _, c := range string(t) {
				items = append(items, Str(string(c)))
			}
		case *SetT:
			items = t.Items
		case *MapT:
			for i := range t.Keys {
				items = append(items, &Arr{Items: []Value{t.Keys[i], t.Vals[i]}})
			}
		}
		idx := 0
		return &Obj{
			idx:   map[string]int{},
			proto: rt.ItrProto,
			cls:   "Array Iterator",
			props: []Prop{{Key: "[[items]]", Val: &Arr{Items: items}}, {Key: "[[idx]]", Val: float64(0)}},
		}
	})
}
