		_, ok := rt.arg(args, 0).(*Arr)
		return Bool(ok)
	}))
	arrFn.Set("of", native("of", func(rt *Runtime, this Value, args []Value) Value {
		return &Arr{Items: append([]Value{}, args...)}
	}))
	arrFn.Set("from", native("from", func(rt *Runtime, this Value, args []Value) Value {
