func (rt *Runtime) setupJSON() {
	j := NewObj(nil)
	j.cls = "JSON"
	j.Set("parse", native("parse", func(rt *Runtime, this Value, args []Value) Value {
		s := rt.strArg(args, 0, "undefined")
		v, err := ParseJSONValue(s)
		if err != nil {
			rt.SyntaxError(err.Error())
		}
		return v
	}))
	j.Set("stringify", native("stringify", func(rt *Runtime, this Value, args []Value) Value {
		v := rt.arg(args, 0)
		indent := ""
		if len(args) > 2 {
			if f, ok := args[2].(float64); ok {
				n := int(f)
				if n > 10 {
					n = 10
				}
				if n < 0 {
					n = 0
				}
				indent = strings.Repeat(" ", n)
			} else {
				s := ToString(rt, args[2])
				if len(s) > 10 {
					s = s[:10]
				}
				indent = s
			}
		}
		var b strings.Builder
		if !jsonStringify(rt, &b, v, "", indent) {
			return Undef{}
		}
		return Str(b.String())
	}))
	rt.def("JSON", j, false)
}

// ParseJSONValue parses a single JSON document.
func ParseJSONValue(s string) (Value, error) {
	vals, err := Parse(strings.NewReader(s), true)
	if err != nil {
		return nil, err
	}
	if len(vals) == 0 {
		return nil, errSyntax("Unexpected end of JSON input")
	}
	return vals[0], nil
}

type jsonError struct{ msg string }

func (e *jsonError) Error() string { return e.msg }

func errSyntax(msg string) error { return &jsonError{msg: msg} }

// jsonStringify implements JSON.stringify. Returns false for undefined.
func jsonStringify(rt *Runtime, b *strings.Builder, v Value, indent string, pad string) bool {
	switch t := v.(type) {
	case Undef, nil:
		if _, ok := v.(Undef); ok {
			return false
		}
		b.WriteString("null")
		return true
	case Null:
		b.WriteString("null")
		return true
	case Bool:
		if t {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
		return true
	case float64:
		if math.IsNaN(t) || math.IsInf(t, 0) {
			b.WriteString("null")
			return true
		}
		b.WriteString(NumToString(t))
		return true
	case *RawNum:
		if math.IsNaN(t.V) || math.IsInf(t.V, 0) {
			b.WriteString("null")
			return true
		}
		b.WriteString(NumToString(t.V))
		return true
	case *big.Int:
		rt.TypeError("Do not know how to serialize a BigInt")
		return true
	case Str:
		b.WriteString(jsonQuote(string(t)))
		return true
	case *Arr:
		if len(t.Items) == 0 {
			b.WriteString("[]")
			return true
		}
		b.WriteString("[")
		for i, it := range t.Items {
			if i > 0 {
				b.WriteString(",")
			}
			if pad != "" {
				b.WriteString("\n" + indent + pad)
			}
			if !jsonStringify(rt, b, it, indent+pad, pad) {
				b.WriteString("null")
			}
		}
		if pad != "" {
			b.WriteString("\n" + indent)
		}
		b.WriteString("]")
		return true
	case *Obj:
		if f, ok := t.Get("toJSON"); ok {
			r := rt.callValue(f, v, nil)
			return jsonStringify(rt, b, r, indent, pad)
		}
		switch t.cls {
		case "Date":
			d, ok := t.prim.(*Date)
			if !ok || !d.Valid {
				return false
			}
			b.WriteString(jsonQuote(d.T.UTC().Format("2006-01-02T15:04:05.000Z07:00")))
			return true
		}
		if len(t.props) == 0 {
			b.WriteString("{}")
			return true
		}
		b.WriteString("{")
		first := true
		for _, p := range t.props {
			var sb strings.Builder
			if !jsonStringify(rt, &sb, p.Val, indent+pad, pad) {
				continue
			}
			if !first {
				b.WriteString(",")
			}
			first = false
			if pad != "" {
				b.WriteString("\n" + indent + pad)
			}
			b.WriteString(jsonQuote(p.Key) + ":")
			b.WriteString(sb.String())
		}
		if !first && pad != "" {
			b.WriteString("\n" + indent)
		}
		b.WriteString("}")
		return true
	case *Sym:
		return false
	case *MapT, *SetT, *Func, *Promise:
		rt.TypeError("Converting circular structure to JSON")
		return false
	}
	rt.TypeError("Converting circular structure to JSON")
	return false
}

func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		case '\b':
			b.WriteString("\\b")
		case '\f':
			b.WriteString("\\f")
		default:
			if c < 0x20 {
				b.WriteString("\\u" + hex4(uint(c)))
				continue
			}
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func hex4(n uint) string {
	alpha := "0123456789abcdef"
	out := ""
	for i := 0; i < 4; i++ {
		out = string(alpha[n&0xF]) + out
		n >>= 4
	}
	return out
}

