		if start > end {
			start = end
		}
		return Str(string(r[start:end]))
	})
	strFn("substring", func(s string, args []Value) Value {
		r := []rune(s)
		start := rt.clampIndex(rt.numArg(args, 0, 0), len(r), false)
		end := rt.clampIndex(rt.numArg(args, 1, float64(len(r))), len(r), false)
		if start > end {
			start, end = end, start
		}
		return Str(string(r[start:end]))
	})
	strFn("substr", func(s string, args []Value) Value {
		r := []rune(s)
		start := rt.clampIndex(rt.numArg(args, 0, 0), len(r), false)
		length := int(rt.numArg(args, 1, float64(len(r))))
		if length < 0 {
			length = 0
		}
		if start+length > len(r) {
			length = len(r) - start
		}
		if length < 0 {
			length = 0
		}
		return Str(string(r[start : start+length]))
	})
	strFn("split", func(s string, args []Value) Value {
		sep := rt.arg(args, 0)
		limit := 0
		if len(args) > 1 && !isUndef(args[1]) {
			limit = rt.ToIndex(args[1])
		}
		out := &Arr{}
		if isUndef(sep) {
			out.Items = []Value{Str(s)}
			return out
		}
		if re, ok := sep.(*RegExp); ok {
			parts := reSplit(string(s), re, limit)
			for _, p := range parts {
				out.Items = append(out.Items, Str(p))
			}
			return out
		}
		delim := ToString(rt, sep)
		if delim == "" {
			for _, c := range s {
				out.Items = append(out.Items, Str(string(c)))
			}
			return out
		}
		parts := strings.Split(s, delim)
		for _, p := range parts {
			out.Items = append(out.Items, Str(p))
		}
		return out
	})
	strFn("replace", func(s string, args []Value) Value {
		return rt.strReplace(s, args, false)
	})
	strFn("replaceAll", func(s string, args []Value) Value {
		return rt.strReplace(s, args, true)
	})
	strFn("search", func(s string, args []Value) Value {
		if re, ok := rt.arg(args, 0).(*RegExp); ok {
			m := reFind(string(s), re)
			if len(m) == 0 {
				return float64(-1)
			}
			return float64(strings.Index(string(s), m[0]))
		}
		sub := ToString(rt, rt.arg(args, 0))
		return float64(strings.Index(s, sub))
	})
	strFn("match", func(s string, args []Value) Value {
		if re, ok := rt.arg(args, 0).(*RegExp); ok {
			return reMatch(string(s), re)
		}
		if _, ok := rt.arg(args, 0).(Undef); ok {
			return Null{}
		}
		r, ok := rt.arg(args, 0).(*regexp.Regexp)
		_ = r
		_ = ok
		sub := ToString(rt, rt.arg(args, 0))
		if strings.Contains(s, sub) {
			return &Arr{Items: []Value{Str(sub)}}
		}
		return Null{}
	})
	strFn("matchAll", func(s string, args []Value) Value {
		o := NewObj(rt.ObjProto)
		o.cls = "RegExp String Iterator"
		return o
	})
	strFn("localeCompare", func(s string, args []Value) Value {
		o := rt.strArg(args, 0, "")
		if s < o {
			return float64(-1)
		}
		if s > o {
			return float64(1)
		}
		return float64(0)
	})
	strFn("normalize", func(s string, args []Value) Value { return Str(s) })
	strFn("toString", func(s string, args []Value) Value { return Str(s) })
	strFn("valueOf", func(s string, args []Value) Value { return Str(s) })
	strFn("toLocaleString", func(s string, args []Value) Value { return Str(s) })

	strObj := NewObj(nil)
	strObj.cls = "String"
	sf := &Func{Name: "String", Native: func(rt *Runtime, this Value, args []Value) Value {
		if len(args) == 0 {
			return Str("")
		}
		return Str(ToString(rt, args[0]))
	}}
	sf.NativeConstructor = func(rt *Runtime, this *Obj, args []Value) Value {
		s := ""
		if len(args) > 0 {
			s = ToString(rt, args[0])
		}
		this.cls = "String"
		this.prim = Str(s)
		for i, c := range s {
			this.Set(strconv.Itoa(i), Str(string(c)))
		}
		this.Set("length", float64(len([]rune(s))))
		return this
	}
	sf.Set("fromCharCode", native("fromCharCode", func(rt *Runtime, this Value, args []Value) Value {
		var b strings.Builder
		for _, a := range args {
			f := ToNumber(a)
			if math.IsNaN(f) || math.IsInf(f, 0) {
				f = 0
			}
			b.WriteRune(rune(int(uint16(int64(math.Trunc(f))))))
		}
		return Str(b.String())
	}))
	sf.Set("fromCodePoint", native("fromCodePoint", func(rt *Runtime, this Value, args []Value) Value {
		var b strings.Builder
		for _, a := range args {
			f := ToNumber(a)
			if math.IsNaN(f) || f < 0 || f > 0x10FFFF || f != math.Trunc(f) {
				rt.RangeError("Invalid code point " + NumToString(f))
			}
			b.WriteRune(rune(int(f)))
		}
		return Str(b.String())
	}))
	sf.Set("raw", native("raw", func(rt *Runtime, this Value, args []Value) Value {
		o := rt.arg(args, 0)
		raw := rt.GetIndex(o, Str("raw"))
		arr, ok := raw.(*Arr)
		if !ok {
			rt.TypeError("Cannot convert undefined or null to object")
		}
		var b strings.Builder
		for i, v := range arr.Items {
			if i > 0 && float64(i) < ToNumber(rt.arg(args, 1, float64(len(arr.Items)))) {
				b.WriteString(ToString(rt, rt.arg(args, i+1)))
			}
			b.WriteString(ToString(rt, v))
		}
		return Str(b.String())
	}))
	rt.def("String", sf, false)
	_ = strObj
}

func (rt *Runtime) strReplace(s string, args []Value, all bool) Value {
	if re, ok := rt.arg(args, 0).(*RegExp); ok {
		return reReplace(string(s), re, rt.arg(args, 1), all)
	}
	sub := ToString(rt, rt.arg(args, 0))
	rep := rt.arg(args, 1)
	if strings.Contains(sub, "$") {
		sub = strings.ReplaceAll(sub, "$", "$$")
	}
	_ = rep
	return Str(strings.ReplaceAll(string(s), sub, rt.strArg(args, 1, "")))
}

// ---------- Number ----------

func (rt *Runtime) setupNumber() {
	p := rt.NumProto
	p.Set("toFixed", native("toFixed", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(this)
		d := int(rt.numArg(args, 0, 0))
		if d < 0 || d > 100 {
			rt.RangeError("toFixed() digits argument must be between 0 and 100")
		}
		return Str(strconv.FormatFloat(f, 'f', d, 64))
	}))
	p.Set("toPrecision", native("toPrecision", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(this)
		if len(args) == 0 || isUndef(args[0]) {
			return Str(NumToString(f))
		}
		d := int(rt.numArg(args, 0, 0))
		if d < 1 || d > 100 {
			rt.RangeError("toPrecision() argument must be between 1 and 100")
		}
		return Str(strconv.FormatFloat(f, 'g', d, 64))
	}))
	p.Set("toExponential", native("toExponential", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(this)
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return Str(NumToString(f))
		}
		if len(args) == 0 || isUndef(args[0]) {
			s := strconv.FormatFloat(f, 'e', -1, 64)
			return Str(expFormat(s))
		}
		d := int(rt.numArg(args, 0, 0))
		s := strconv.FormatFloat(f, 'e', d, 64)
		return Str(expFormat(s))
	}))
	p.Set("toString", native("toString", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(this)
		if len(args) > 0 {
			radix := int(rt.numArg(args, 0, 10))
			if radix < 2 || radix > 36 {
				rt.RangeError("toString() radix must be between 2 and 36")
			}
			if radix == 10 {
				return Str(NumToString(f))
			}
			return Str(intToRadix(f, radix))
		}
		return Str(NumToString(f))
	}))
	p.Set("toLocaleString", native("toLocaleString", func(rt *Runtime, this Value, args []Value) Value {
		return Str(NumToString(ToNumber(this)))
	}))
	p.Set("valueOf", native("valueOf", func(rt *Runtime, this Value, args []Value) Value {
		return ToNumber(this)
	}))

	nf := &Func{Name: "Number", Native: func(rt *Runtime, this Value, args []Value) Value {
		if len(args) == 0 {
			return float64(0)
		}
		return ToNumber(args[0])
	}}
	nf.NativeConstructor = func(rt *Runtime, this *Obj, args []Value) Value {
		v := float64(0)
		if len(args) > 0 {
			v = ToNumber(args[0])
		}
		this.cls = "Number"
		this.prim = v
		return this
	}
	nf.Set("parseInt", native("parseInt", func(rt *Runtime, this Value, args []Value) Value { return globalParseInt(rt, args) }))
	nf.Set("parseFloat", native("parseFloat", func(rt *Runtime, this Value, args []Value) Value { return globalParseFloat(rt, args) }))
	nf.Set("isNaN", native("isNaN", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(rt.arg(args, 0))
		return Bool(math.IsNaN(f))
	}))
	nf.Set("isFinite", native("isFinite", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(rt.arg(args, 0))
		return Bool(!math.IsNaN(f) && !math.IsInf(f, 0))
	}))
	nf.Set("isInteger", native("isInteger", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(rt.arg(args, 0))
		return Bool(!math.IsNaN(f) && !math.IsInf(f, 0) && f == math.Trunc(f))
	}))
	nf.Set("isSafeInteger", native("isSafeInteger", func(rt *Runtime, this Value, args []Value) Value {
		f := ToNumber(rt.arg(args, 0))
		return Bool(!math.IsNaN(f) && !math.IsInf(f, 0) && f == math.Trunc(f) && math.Abs(f) <= 9007199254740991)
	}))
	nf.Set("MAX_SAFE_INTEGER", 9007199254740991.0)
	nf.Set("MIN_SAFE_INTEGER", -9007199254740991.0)
	nf.Set("MAX_VALUE", math.MaxFloat64)
	nf.Set("MIN_VALUE", 5e-324)
	nf.Set("EPSILON", math.Nextafter(1, 2)-1)
	nf.Set("POSITIVE_INFINITY", math.Inf(1))
	nf.Set("NEGATIVE_INFINITY", math.Inf(-1))
	nf.Set("NaN", math.NaN())
	rt.def("Number", nf, false)

	bf := &Func{Name: "Boolean", Native: func(rt *Runtime, this Value, args []Value) Value {
		return Bool(ToBool(rt.arg(args, 0)))
	}}
	bf.NativeConstructor = func(rt *Runtime, this *Obj, args []Value) Value {
		this.cls = "Boolean"
		this.prim = Bool(ToBool(rt.arg(args, 0)))
		return this
	}
	bp := rt.BoolProto
	bp.Set("toString", native("toString", func(rt *Runtime, this Value, args []Value) Value {
		return Str(ToString(rt, ToBool(this)))
	}))
	bp.Set("valueOf", native("valueOf", func(rt *Runtime, this Value, args []Value) Value {
		return ToBool(this)
	}))
	rt.def("Boolean", bf, false)

	bigFn := &Func{Name: "BigInt", Native: func(rt *Runtime, this Value, args []Value) Value {
		return rt.toBigInt(rt.arg(args, 0))
	}}
	rt.def("BigInt", bigFn, false)
}

func expFormat(s string) string {
	// Go gives at least 2 exponent digits; JS gives as many as needed
	i := strings.IndexByte(s, 'e')
	if i < 0 {
		return s
	}
	mant, exp := s[:i], s[i+1:]
	sign := ""
	if exp[0] == '+' {
		exp = exp[1:]
	} else if exp[0] == '-' {
		sign = "-"
		exp = exp[1:]
	}
	for len(exp) > 1 && exp[0] == '0' {
		exp = exp[1:]
	}
	return mant + "e" + sign + exp
}

func intToRadix(f float64, radix int) string {
	neg := f < 0
	if neg {
		f = -f
	}
	n := int64(math.Trunc(f))
	if n == 0 {
		if neg {
			return "-0"
		}
		return "0"
	}
	alpha := "0123456789abcdefghijklmnopqrstuvwxyz"
	out := ""
	for n > 0 {
		out = string(alpha[n%int64(radix)]) + out
		n /= int64(radix)
	}
	if neg {
		out = "-" + out
	}
	return out
}

func (rt *Runtime) toBigInt(v Value) Value {
	switch t := v.(type) {
	case *big.Int:
		return t
	case float64:
		if math.IsNaN(t) || math.IsInf(t, 0) {
			rt.RangeError("Cannot convert " + NumToString(t) + " to a BigInt")
		}
		if t != math.Trunc(t) {
			rt.RangeError("The number " + NumToString(t) + " cannot be converted to a BigInt because it is not an integer")
		}
		return bigFromFloat(t)
	case Str:
		n, ok := new(big.Int).SetString(strings.TrimSpace(string(t)), 0)
		if !ok {
			rt.SyntaxError("Cannot convert " + string(t) + " to a BigInt")
		}
		return n
	case Bool:
		if t {
			return big.NewInt(1)
		}
		return big.NewInt(0)
	case Null:
		rt.TypeError("Cannot convert null to a BigInt")
	case Undef:
		rt.TypeError("Cannot convert undefined to a BigInt")
	}
	rt.TypeError("Cannot convert " + ToString(rt, v) + " to a BigInt")
	return nil
}

func bigFromFloat(f float64) *big.Int {
	bi, _ := new(big.Float).SetFloat64(f).Int(nil)
	return bi
}

