var dateLayouts = []string{
	"2006-01-02T15:04:05.000Z07:00",
	"2006-01-02T15:04:05Z07:00",
	"2006-01-02T15:04:05",
	"2006-01-02T15:04",
	"2006-01-02",
	"2006-01",
	"2006",
	time.RFC1123,
	time.RFC3339,
	"Mon Jan 02 2006 15:04:05 GMT-0700 (MST)",
	"Jan 2, 2006",
	"Jan 2 2006",
	"1/2/2006",
	"01/02/2006",
}

func parseDateValue(rt *Runtime, v Value) *Date {
	switch t := v.(type) {
	case *Date:
		return t
	case Str:
		s := strings.TrimSpace(string(t))
		for _, layout := range dateLayouts {
			if d, err := time.Parse(layout, s); err == nil {
				return &Date{T: d, Valid: true}
			}
		}
		return &Date{Valid: false}
	default:
		f := ToNumber(v)
		if math.IsNaN(f) {
			return &Date{Valid: false}
		}
		return &Date{T: time.UnixMilli(int64(f)), Valid: true}
	}
}

