		if arr, ok := rt.arg(args, 1).(*Arr); ok {
			callArgs = arr.Items
		} else if !isNullish(rt.arg(args, 1)) {
			callArgs = rt.iterableItems(rt.arg(args, 1))
		}
		return rt.callValue(fn, newThis, callArgs)
	}))
	p.Set("bind", native("bind", func(rt *Runtime, this Value, args []Value) Value {
		fn := this
		bound := append([]Value{}, args[1:]...)
		name := ""
		if f, ok := fn.(*Func); ok {
			name = f.Name
		}
		return &Func{Name: "bound " + name, Native: func(rt *Runtime, this Value, callArgs []Value) Value {
			return rt.callValue(fn, rt.arg(args, 0), append(append([]Value{}, bound...), callArgs...))
		}}
	}))
	p.Set("toString", native("toString", func(rt *Runtime, this Value, args []Value) Value {
		if f, ok := this.(*Func); ok {
			if f.Native != nil {
				return Str("function " + f.Name + "() { [native code] }")
			}
			return Str("function " + f.Name + "() { ... }")
		}
		return Str(ToString(rt, this))
	}))
	ff := &Func{Name: "Function", Native: func(rt *Runtime, this Value, args []Value) Value {
		var body string
		if len(args) > 0 {
			body = ToString(rt, args[len(args)-1])
		}
		return rt.compile(body)
	}}
	rt.def("Function", ff, false)
