		}
		s := &Sym{Desc: key}
		registry[key] = s
		return s
	}))
	sf.Set("keyFor", native("keyFor", func(rt *Runtime, this Value, args []Value) Value {
		if s, ok := rt.arg(args, 0).(*Sym); ok {
			for k, v := range registry {
				if v == s {
					return Str(k)
				}
			}
		} else {
			rt.TypeError(rt.strArg(args, 0, "undefined") + " is not a symbol")
		}
		return Undef{}
	}))
	wellKnown := []string{"iterator", "asyncIterator", "hasInstance", "isConcatSpreadable",
		"match", "matchAll", "replace", "search", "species", "split", "toPrimitive", "toStringTag", "unscopables"}
	for _, w := range wellKnown {
		sf.Set(w, &Sym{Desc: "Symbol." + w})
	}
	p := NewObj(nil)
	p.cls = "Symbol"
	p.Set("toString", native("toString", func(rt *Runtime, this Value, args []Value) Value {
		return Str(ToString(rt, this))
	}))
	p.Set("valueOf", native("valueOf", func(rt *Runtime, this Value, args []Value) Value {
		return this
