		fn := &Func{Name: name, Native: func(rt *Runtime, this Value, args []Value) Value {
			msg := ""
			if len(args) > 0 && !isUndef(args[0]) {
				msg = ToString(rt, args[0])
			}
			return &Err{Name: nameOf(this), Message: msg}
		}}
		nm := name
		fn.NativeConstructor = func(rt *Runtime, this *Obj, args []Value) Value {
			msg := ""
			if len(args) > 0 && !isUndef(args[0]) {
				msg = ToString(rt, args[0])
			}
			return &Err{Name: nm, Message: msg}
		}
		rt.def(name, fn, false)
	}
	for _, name := range []string{"Error", "EvalError", "RangeError", "ReferenceError", "SyntaxError", "TypeError", "URIError", "AggregateError"} {
		p := rt.ErrProtos[name]
		p.Set("name", Str(name))
		p.Set("toString", native("toString", func(rt *Runtime, this Value, args []Value) Value {
			e := rt.toErr(this)
			name := e.Name
			if e.Name == "" {
				name = "Error"
			}
			if e.Message == "" {
				return Str(name)
			}
			return Str(name + ": " + e.Message)
		}))
	}
}

func nameOf(this Value) string {
