func sameValueZero(a, b Value) bool {
	if strictEqual(a, b) {
		return true
	}
	x, ok1 := a.(float64)
	y, ok2 := b.(float64)
	return ok1 && ok2 && math.IsNaN(x) && math.IsNaN(y)
}

