}

func nameOf(this Value) string {
	if o, ok := this.(*Obj); ok {
		if v, ok := o.Get("name"); ok {
			return ToString(rt0, v)
		}
		return o.cls
	}
	return "Error"
}

func (rt *Runtime) toErr(this Value) *Err {
	switch t := this.(type) {
	case *Err:
		return t
	case *Obj:
		if t.cls == "Error" || t.cls == "TypeError" || t.cls == "RangeError" || t.cls == "SyntaxError" || t.cls == "ReferenceError" || t.cls == "EvalError" || t.cls == "URIError" {
			if d, ok := t.prim.(*Err); ok {
