	}), false)
	rt.def("encodeURIComponent", native("encodeURIComponent", func(rt *Runtime, this Value, args []Value) Value {
		return Str(encodeURI(rt.strArg(args, 0, ""), "!'()*-._~0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"))
	}), false)
	rt.def("decodeURIComponent", native("decodeURIComponent", func(rt *Runtime, this Value, args []Value) Value {
		s, err := decodeURI(rt.strArg(args, 0, ""))
		if err != nil {
			rt.ThrowError("URIError", "URI malformed")
		}
		return Str(s)
	}), false)
	rt.def("encodeURI", native("encodeURI", func(rt *Runtime, this Value, args []Value) Value {
		return Str(encodeURI(rt.strArg(args, 0, ""), "!#$&'()*+,/:;=?@-._~0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"))
	}), false)
	rt.def("decodeURI", native("decodeURI", func(rt *Runtime, this Value, args []Value) Value {
		s, err := decodeURI(rt.strArg(args, 0, ""))
		if err != nil {
			rt.ThrowError("URIError", "URI malformed")
		}
		return Str(s)
	}), false)
	rt.def("escape", native("escape", func(rt *Runtime, this Value, args []Value) Value {
		return Str(encodeURI(rt.strArg(args, 0, ""), "*@+_-.0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"))
	}), false)
	rt.def("unescape", native("unescape", func(rt *Runtime, this Value, args []Value) Value {
		s, err := decodeURI(rt.strArg(args, 0, ""))
		if err != nil {
			return Str(rt.strArg(args, 0, ""))
		}
		return Str(s)
	}), false)
	rt.def("eval", native("eval", func(rt *Runtime, this Value, args []Value) Value {
		if len(args) == 0 {
			return Undef{}
		}
		prog := parseString(ToString(rt, args[0]))
		sc := newScope(rt.Global)
		var res Value = Undef{}
		for _, st := range prog.Body {
			if st.Kind == KExprStmt {
				res = rt.Eval(st.L, sc, this)
				continue
			}
			rt.exec(st, sc, this)
		}
		return res
	}), false)
	// mark all standard globals as non enumerable
	for _, p := range rt.Glob.props {
		rt.nonEnum[p.Key] = true
	}
	// the global object should not be enumerable
	rt.Glob = NewObj(nil)
	rt.Glob.cls = "global"
	rt.Glob.proto = nil
	rt.Global.declare("globalThis", rt.Glob)
	for _, p := range rt.Glob.props {
		rt.nonEnum[p.Key] = true
	}
}

func encodeURI(s string, keep string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if strings.IndexByte(keep, c) >= 0 {
			b.WriteByte(c)
			continue
		}
		b.WriteString("%" + hex2(c))
	}
	return b.String()
}

func hex2(c byte) string {
	alpha := "0123456789ABCDEF"
	return string(alpha[c>>4&0xF]) + string(alpha[c&0xF])
}

func decodeURI(s string) (string, error) {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '%' {
			b.WriteByte(c)
			continue
		}
		if i+2 >= len(s) {
			return "", errSyntax("URI malformed")
		}
		hi, ok1 := hexVal(s[i+1])
		lo, ok2 := hexVal(s[i+2])
		if !ok1 || !ok2 {
			return "", errSyntax("URI malformed")
		}
		b.WriteByte(byte(hi<<4 | lo))
		i += 2
	}
	return b.String(), nil
}

func hexVal(c byte) (int, bool) {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0'), true
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10, true
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10, true
	}
	return 0, false
}

