	pf.Set("all", native("all", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		out := &Arr{}
		for _, it := range items {
			out.Items = append(out.Items, rt.awaitValue(it))
		}
		return rt.settledPromise(out, false)
	}))
	pf.Set("allSettled", native("allSettled", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		out := &Arr{}
		for _, it := range items {
			out.Items = append(out.Items, rt.awaitValue(it))
		}
		return rt.settledPromise(out, false)
	}))
	pf.Set("any", native("any", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		for _, it := range items {
			return rt.awaitValue(it)
		}
		return rt.settledPromise(&Arr{}, true)
	}))
	pf.Set("race", native("race", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		if len(items) == 0 {
			return rt.settledPromise(&Arr{}, true)
		}
		return rt.awaitValue(items[0])
	}))
	rt.def("Promise", pf, false)
}

func (rt *Runtime) toPromise(this Value) *Promise {
	if o, ok := this.(*Obj); ok && o.cls == "Promise" {
		if p, ok := o.prim.(*Promise); ok {
			return p
		}
	}
	rt.TypeError("Cannot read properties of undefined (reading 'then')")
	return nil
}

func (rt *Runtime) resolvePromise(pr *Promise, v Value) {
	if pr.State != 0 {
		return
	}
	if np, ok := rt.unwrapPromise(v); ok {
		for _, cb := range pr.CBs {
			np.CBs = append(np.CBs, cb)
		}
		*pr = *np
		return
	}
	pr.State = 1
	pr.Val = v
	rt.runMicro()
}

func (rt *Runtime) rejectPromise(pr *Promise, v Value) {
	if pr.State != 0 {
		return
	}
	pr.State = 2
	pr.Val = v
	rt.runMicro()
}

func (rt *Runtime) unwrapPromise(v Value) (*Promise, bool) {
	if o, ok := v.(*Obj); ok && o.cls == "Promise" {
		if p, ok := o.prim.(*Promise); ok {
			return p, true
		}
	}
	return nil, false
}

func (rt *Runtime) awaitValue(v Value) Value {
	if p, ok := rt.unwrapPromise(v); ok {
		if p.State == 1 {
			return p.Val
		}
		if p.State == 2 {
			panic(&Throw{Val: p.Val})
		}
		rt.TypeError("Promise is pending")
	}
	return v
}

func (rt *Runtime) settledPromise(v Value, rejected bool) Value {
	pr := &Promise{Val: v}
	if rejected {
		pr.State = 2
	} else {
		pr.State = 1
	}
	o := NewObj(rt.PromProto)
	o.cls = "Promise"
	o.prim = pr
	return o
}

func (rt *Runtime) thenPromise(pr *Promise, onFul, onRej Value) Value {
	npr := &Promise{}
	pr.CBs = append(pr.CBs, promiseCB{onFul: onFul, onRej: onRej, next: npr})
	o := NewObj(rt.PromProto)
	o.cls = "Promise"
	o.prim = npr
	if pr.State != 0 {
		rt.runMicro()
	}
	return o
}

type promiseCB struct {
	onFul Value
	onRej Value
	next  *Promise
}

func (rt *Runtime) runMicro() {
	for i := 0; i < len(rt.Micro); i++ {
		rt.Micro[i]()
	}
	rt.Micro = rt.Micro[:0]
}

// NewPromiseObject wraps a promise in an object.
func (rt *Runtime) NewPromiseObject(pr *Promise) Value {
	o := NewObj(rt.PromProto)
	o.cls = "Promise"
	o.prim = pr
	return o
}

