// reExec returns an array like the JS exec result.
func reExec(s string, re *RegExp) Value {
	m := reFind(s, re)
	if len(m) == 0 {
		return Null{}
	}
	out := &Arr{Items: []Value{}}
	for _, g := range m {
		if g == "" {
			out.Items = append(out.Items, Undef{})
		} else {
			out.Items = append(out.Items, Str(g))
		}
	}
	out.Items = append(out.Items, Str(s))
	out.Items = append(out.Items, float64(strings.Index(s, m[0])))
	return out
}

func reMatch(s string, re *RegExp) Value {
	m := reFind(s, re)
	if len(m) == 0 {
		return Null{}
	}
	if strings.Contains(re.Flags, "g") {
		out := &Arr{Items: []Value{}}
		idx := 0
		for {
			sub := reFind(s[idx:], re)
			if len(sub) == 0 {
				break
			}
			out.Items = append(out.Items, Str(sub[0]))
			idx += strings.Index(s[idx:], sub[0]) + len(sub[0])
			if len(sub[0]) == 0 {
				idx++
			}
			if idx > len(s) {
				break
			}
		}
		return out
	}
	out := &Arr{Items: []Value{}}
	for _, g := range m {
		if g == "" {
			out.Items = append(out.Items, Undef{})
		} else {
			out.Items = append(out.Items, Str(g))
		}
