}

func reReplace(s string, re *RegExp, rep Value, all bool) Value {
	if fn, ok := rep.(*Func); ok {
		count := 1
		if all || strings.Contains(re.Flags, "g") {
			count = -1
		}
		return Str(replaceFunc(string(s), re, func(match string, groups []string, idx int) string {
			args := []Value{}
			for _, g := range groups {
				if g == "" {
					args = append(args, Undef{})
				} else {
					args = append(args, Str(g))
				}
			}
			args = append(args, float64(idx), Str(s))
			return ToString(rt, rt.callValue(fn, Undef{}, args))
		}, count))
	}
	var count int
	if all || strings.Contains(re.Flags, "g") {
		count = -1
	} else {
		count = 1
	}
	return Str(replaceFunc(string(s), re, func(match string, groups []string, idx int) string {
		return expandReplacement(rt.strArg([]Value{rep}, 0, ""), groups, idx, s)
	}, count))
}

func expandReplacement(rep string, groups []string, idx int, input string) string {
	var b strings.Builder
	for i := 0; i < len(rep); i++ {
		c := rep[i]
		if c != '$' {
			b.WriteByte(c)
			continue
		}
		if i+1 < len(rep) {
			switch rep[i+1] {
			case '$':
				b.WriteByte('$')
				i++
				continue
			case '&':
				if len(groups) > 0 {
					b.WriteString(groups[0])
				}
				i++
				continue
			case '`':
				b.WriteString(input[:idx])
				i++
				continue
			case '\'':
				b.WriteString(input[idx+len(groups[0]):])
				i++
				continue
			default:
				if rep[i+1] >= '0' && rep[i+1] <= '9' {
					n := int(rep[i+1] - '0')
					if n < len(groups) {
						b.WriteString(groups[n])
					}
					i++
					continue
				}
			}
		}
		b.WriteByte(c)
	}
	return b.String()
}

// ---------- Promise ----------

func (rt *Runtime) setupPromise() {
	p := rt.PromProto
	p.Set("then", native("then", func(rt *Runtime, this Value, args []Value) Value {
		pr := rt.toPromise(this)
		if pr == nil {
			rt.TypeError("Cannot read properties of undefined (reading 'then')")
		}
		return rt.thenPromise(pr, rt.arg(args, 0), rt.arg(args, 1))
	}))
	p.Set("catch", native("catch", func(rt *Runtime, this Value, args []Value) Value {
		pr := rt.toPromise(this)
		return rt.thenPromise(pr, nil, rt.arg(args, 0))
	}))
	p.Set("finally", native("finally", func(rt *Runtime, this Value, args []Value) Value {
		pr := rt.toPromise(this)
		return rt.thenPromise(pr, rt.arg(args, 0), rt.arg(args, 0))
	}))
	pf := &Func{Name: "Promise", Native: func(rt *Runtime, this Value, args []Value) Value {
		rt.TypeError("Constructor Promise requires 'new'")
		return nil
	}}
	pf.NativeConstructor = func(rt *Runtime, this *Obj, args []Value) Value {
		pr := &Promise{}
		this.cls = "Promise"
		this.prim = pr
		exec := rt.arg(args, 0)
		if f, ok := exec.(*Func); ok {
			resolve := &Func{Name: "", Native: func(rt *Runtime, this Value, a []Value) Value {
				rt.resolvePromise(pr, rt.arg(a, 0))
				return Undef{}
			}}
			reject := &Func{Name: "", Native: func(rt *Runtime, this Value, a []Value) Value {
				rt.rejectPromise(pr, rt.arg(a, 0))
				return Undef{}
			}}
			rt.callValue(f, Undef{}, []Value{resolve, reject})
		}
		return this
	}
	pf.Set("resolve", native("resolve", func(rt *Runtime, this Value, args []Value) Value {
		pr := &Promise{}
		rt.resolvePromise(pr, rt.arg(args, 0))
		return pr
	}))
	pf.Set("reject", native("reject", func(rt *Runtime, this Value, args []Value) Value {
		pr := &Promise{}
		rt.rejectPromise(pr, rt.arg(args, 0))
		return pr
	}))
	pf.Set("all", native("all", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		out := &Arr{}
		for _, it := range items {
			out.Items = append(out.Items, rt.awaitValue(it))
		}
		return rt.settledPromise(out, false)
	}))
	pf.Set("allSettled", native("allSettled", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		out := &Arr{}
		for _, it := range items {
			out.Items = append(out.Items, rt.awaitValue(it))
		}
		return rt.settledPromise(out, false)
	}))
	pf.Set("any", native("any", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		for _, it := range items {
			return rt.awaitValue(it)
		}
		return rt.settledPromise(&Arr{}, true)
	}))
	pf.Set("race", native("race", func(rt *Runtime, this Value, args []Value) Value {
		items := rt.iterableItems(rt.arg(args, 0))
		if len(items) == 0 {
			return rt.settledPromise(&Arr{}, true)
		}
		return rt.awaitValue(items[0])
	}))
	rt.def("Promise", pf, false)
}

func (rt *Runtime) toPromise(this Value) *Promise {
	if o, ok := this.(*Obj); ok && o.cls == "Promise" {
		if p, ok := o.prim.(*Promise); ok {
			return p
		}
	}
	rt.TypeError("Cannot read properties of undefined (reading 'then')")
	return nil
}

func (rt *Runtime) resolvePromise(pr *Promise, v Value) {
	if pr.State != 0 {
		return
	}
	if np, ok := rt.unwrapPromise(v); ok {
		for _, cb := range pr.CBs {
			np.CBs = append(np.CBs, cb)
		}
		*pr = *np
		return
	}
	pr.State = 1
	pr.Val = v
	rt.runMicro()
}

func (rt *Runtime) rejectPromise(pr *Promise, v Value) {
	if pr.State != 0 {
		return
	}
	pr.State = 2
	pr.Val = v
	rt.runMicro()
}

func (rt *Runtime) unwrapPromise(v Value) (*Promise, bool) {
	if o, ok := v.(*Obj); ok && o.cls == "Promise" {
		if p, ok := o.prim.(*Promise); ok {
			return p, true
		}
	}
	return nil, false
}

func (rt *Runtime) awaitValue(v Value) Value {
	if p, ok := rt.unwrapPromise(v); ok {
		if p.State == 1 {
			return p.Val
		}
		if p.State == 2 {
			panic(&Throw{Val: p.Val})
		}
		rt.TypeError("Promise is pending")
	}
	return v
}

func (rt *Runtime) settledPromise(v Value, rejected bool) Value {
	pr := &Promise{Val: v}
	if rejected {
		pr.State = 2
	} else {
		pr.State = 1
	}
	o := NewObj(rt.PromProto)
	o.cls = "Promise"
	o.prim = pr
	return o
}

func (rt *Runtime) thenPromise(pr *Promise, onFul, onRej Value) Value {
	npr := &Promise{}
	pr.CBs = append(pr.CBs, promiseCB{onFul: onFul, onRej: onRej, next: npr})
	o := NewObj(rt.PromProto)
	o.cls = "Promise"
	o.prim = npr
	if pr.State != 0 {
		rt.runMicro()
	}
	return o
}

type promiseCB struct {
	onFul Value
	onRej Value
	next  *Promise
}

func (rt *Runtime) runMicro() {
	for i := 0; i < len(rt.Micro); i++ {
		rt.Micro[i]()
	}
	rt.Micro = rt.Micro[:0]
}

// NewPromiseObject wraps a promise in an object.
func (rt *Runtime) NewPromiseObject(pr *Promise) Value {
	o := NewObj(rt.PromProto)
	o.cls = "Promise"
	o.prim = pr
	return o
}

