// proxyGet handles property access through a proxy.
func (rt *Runtime) proxyGet(p *Proxy, key string) Value {
	if get, ok := p.Handler.Get("get"); ok {
		return rt.callValue(get, p.Handler, []Value{p.Target, Str(key), p.Handler})
	}
	return rt.GetIndex(p.Target, Str(key))
}

