	rt.def("ArrayBuffer", abf, false)

	kinds := []struct {
		name string
		size int
	}{
		{"Int8Array", 1}, {"Uint8Array", 1}, {"Uint8ClampedArray", 1},
		{"Int16Array", 2}, {"Uint16Array", 2}, {"Int32Array", 4}, {"Uint32Array", 4},
		{"Float32Array", 4}, {"Float64Array", 8},
	}
	for _, k := range kinds {
		kind := k.name
		fn := &Func{Name: kind, Native: func(rt *Runtime, this Value, args []Value) Value {
