func (rt *Runtime) newTypedArray(kind string, src Value) Value {
	ta := &TypedArray{Kind: kind}
	switch t := src.(type) {
	case float64:
		n := rt.ToIndex(t)
		ta.Buf = make([]byte, n)
	case *Arr:
		ta.Buf = make([]byte, len(t.Items))
		for i, v := range t.Items {
			ta.Buf[i] = byte(uint32(ToNumber(v)))
		}
	case *ArrayBuffer:
		ta.Buf = t.Buf
	case *TypedArray:
		ta.Buf = append([]byte(nil), t.Buf...)
	default:
		if !isNullish(src) {
			ta.Buf = []byte(rt.strArg([]Value{src}, 0, ""))
		}
	}
	return ta
}

