func globalParseInt(rt *Runtime, args []Value) Value {
	s := strings.TrimSpace(rt.strArg(args, 0, ""))
	radix := int(rt.numArg(args, 1, 0))
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	if (radix == 0 || radix == 16) && (strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X")) {
		radix = 16
		s = s[2:]
	}
	if radix == 0 {
		if strings.HasPrefix(s, "0") && len(s) > 1 {
			radix = 8
		} else {
			radix = 10
		}
	}
	if radix < 2 || radix > 36 {
		return float64(0)
	}
	end := 0
	for end < len(s) {
		c := s[end]
		v := digitVal(c)
		if v < 0 || v >= radix {
			break
		}
		end++
	}
	if end == 0 {
		return math.NaN()
	}
	n, _ := strconv.ParseInt(s[:end], radix, 64)
	if neg {
		n = -n
	}
	return float64(n)
}

func digitVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'z':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'Z':
		return int(c-'A') + 10
	}
	return -1
}

func globalParseFloat(rt *Runtime, args []Value) Value {
	s := strings.TrimSpace(rt.strArg(args, 0, ""))
	end := 0
	seenDigit := false
	seenDot := false
	for end < len(s) {
		c := s[end]
		if c >= '0' && c <= '9' {
			seenDigit = true
			end++
			continue
		}
		if (c == 'e' || c == 'E') && seenDigit {
			if end+1 < len(s) && (s[end+1] == '+' || s[end+1] == '-') {
				if end+2 < len(s) && s[end+2] >= '0' && s[end+2] <= '9' {
					end += 3
					continue
				}
			}
			break
		}
		if c == '.' && !seenDot {
			seenDot = true
			end++
			continue
		}
		if (c == '+' || c == '-') && end == 0 {
			end++
			continue
		}
		break
	}
	if !seenDigit {
		return math.NaN()
	}
	f, err := strconv.ParseFloat(s[:end], 64)
	if err != nil {
		return math.NaN()
	}
	return f
}

