package engine

import (
	"math"
	"math/big"
	"strconv"
)

// MaxSafeInteger is the largest integer exactly representable as a float64.
const MaxSafeInteger = 9007199254740991

// Convert converts a parsed document value into JavaScript values.
func Convert(v Value) Value {
	switch t := v.(type) {
	case *RawNum:
		return rawNumToJS(t)
	case *Obj:
		o := NewObj(nil)
		o.cls = t.cls
		o.prim = t.prim
		for _, p := range t.props {
			o.Set(p.Key, Convert(p.Val))
		}
		return o
	case *Arr:
		a := &Arr{}
		for _, it := range t.Items {
			a.Items = append(a.Items, Convert(it))
		}
		return a
	case Str:
		return Str(t)
	case Bool:
		return t
	case Null:
		return Null{}
	case Undef:
		return Undef{}
	}
	return v
}

func rawNumToJS(t *RawNum) Value {
	if isIntLiteral(t.Raw) {
		if n, ok := new(big.Int).SetString(t.Raw, 10); ok {
			if n.IsInt64() {
				abs := n.Abs(n)
				if abs.IsInt64() && abs.Int64() > MaxSafeInteger {
					return n
				}
			} else {
				return n
			}
		}
	}
	return t.V
}

func isIntLiteral(raw string) bool {
	if raw == "" {
		return false
	}
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if c == '.' || c == 'e' || c == 'E' {
			return false
		}
	}
	return true
}

// JSONToValue converts a parsed JSON document into plain JavaScript values
// (numbers always become float64, like JSON.parse).
func JSONToValue(v Value) Value {
	switch t := v.(type) {
	case *RawNum:
		return t.V
	case *Obj:
		o := NewObj(nil)
		o.cls = "Object"
		for _, p := range t.props {
			o.Set(p.Key, JSONToValue(p.Val))
		}
		return o
	case *Arr:
		a := &Arr{}
		for _, it := range t.Items {
			a.Items = append(a.Items, JSONToValue(it))
		}
		return a
	}
	return Convert(v)
}

func floatToInt64(f float64) int64 {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return 0
	}
	return int64(math.Trunc(f))
}

func formatIndex(i int) string { return strconv.Itoa(i) }
EOF
