// sortKeysValue recursively sorts the keys of an object.
func (rt *Runtime) sortKeysValue(v Value) Value {
	switch t := v.(type) {
	case *Obj:
		out := NewObj(nil)
		out.cls = t.cls
		out.prim = t.prim
		keys := make([]string, len(t.props))
		for i, p := range t.props {
			keys[i] = p.Key
		}
		sort.Strings(keys)
		for _, k := range keys {
			val, _ := t.Get(k)
			out.Set(k, rt.sortKeysValue(val))
		}
		return out
	case *Arr:
		out := &Arr{}
		for _, it := range t.Items {
			out.Items = append(out.Items, rt.sortKeysValue(it))
		}
		return out
	}
	return v
}

// walkValue applies fn bottom-up over a structure.
func (rt *Runtime) walkValue(v Value, fn Value, this Value) Value {
	switch t := v.(type) {
	case *Obj:
		out := NewObj(rt.ObjProto)
		out.cls = t.cls
		out.prim = t.prim
		for _, p := range t.props {
			out.Set(p.Key, rt.walkValue(p.Val, fn, this))
		}
		return rt.callValue(fn, this, []Value{out})
	case *Arr:
		out := &Arr{}
		for _, it := range t.Items {
			out.Items = append(out.Items, rt.walkValue(it, fn, this))
		}
		return rt.callValue(fn, this, []Value{out})
	}
	return rt.callValue(fn, this, []Value{v})
}
