	}
	return src, false
}

type pathSeg struct {
	name string
	idx  string
	isID bool
}

// parsePath parses `.a.b[0]` style paths. Returns the segments and how many
// bytes were consumed.
func parsePath(src string) ([]pathSeg, int, bool) {
	if !strings.HasPrefix(src, ".") {
		return nil, 0, false
	}
	i := 1
	var segs []pathSeg
	if i >= len(src) {
		return segs, i, true
	}
	c := src[i]
	if isIdentStartByte(c) {
		j := i
		for j < len(src) && isIdentPartByte(src[j]) {
			j++
		}
		segs = append(segs, pathSeg{name: src[i:j], isID: true})
		i = j
	} else if c == '[' {
		j, ok := matchBracket(src, i)
		if !ok {
			return nil, 0, false
		}
		segs = append(segs, pathSeg{idx: src[i+1 : j]})
		i = j + 1
	} else {
		return nil, 0, false
	}
	for i < len(src) {
		if src[i] == '.' {
			j := i + 1
			if j < len(src) && isIdentStartByte(src[j]) {
				k := j
				for k < len(src) && isIdentPartByte(src[k]) {
					k++
				}
				segs = append(segs, pathSeg{name: src[j:k], isID: true})
				i = k
				continue
			}
			return nil, 0, false
		}
		if src[i] == '[' {
			j, ok := matchBracket(src, i)
			if !ok {
				return nil, 0, false
			}
			segs = append(segs, pathSeg{idx: src[i+1 : j]})
			i = j + 1
			continue
		}
		break
	}
	return segs, i, true
}

func matchBracket(src string, i int) (int, bool) {
	depth := 0
	for j := i; j < len(src); j++ {
		switch src[j] {
		case '[':
			depth++
		case ']':
			depth--
			if depth == 0 {
				return j, true
			}
		}
	}
	return 0, false
}

func renderPath(segs []pathSeg) string {
	var b strings.Builder
	for _, s := range segs {
		if s.isID {
			b.WriteString("." + s.name)
			continue
		}
		b.WriteString("[" + s.idx + "]")
	}
	return b.String()
}

func isIdentStartByte(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func isIdentPartByte(c byte) bool {
	return isIdentStartByte(c) || (c >= '0' && c <= '9')
}

