			}
			return nil
		}
	}
	var sc *Scope
	for i := range comps {
		if i == 0 {
			sc = newScope(rt.Global)
		} else {
			sc = newScope(rt.Global)
		}
		_ = sc
	}
	var current Value
	for vi, v := range vals {
		current = v
		for i, c := range comps {
			sc := newScope(rt.Global)
			sc.declare("x", current)
			res := rt.runProgram(c.prog, sc, current)
			if fn, ok := res.(*Func); ok {
				res = rt.callValue(fn, current, []Value{current})
			}
			if sym, ok := res.(*Sym); ok && sym.Skip {
				if i == len(comps)-1 {
					current = res
					continue
				}
				current = res
				continue
			}
			if i == len(comps)-1 {
				rt.PrintValue(res)
			}
			current = res
		}
		_ = vi
	}
	return nil
}

// renderValue renders a document value using the raw number forms.
func renderValue(rt *Runtime, v Value) string {
	var sb strings.Builder
	rt.PrintValue(v)
	return sb.String()
