func parseProgramSafe(src string) (*Program, error) {
	defer func() {
		if r := recover(); r != nil {
			if se, ok := r.(*SyntaxError); ok {
				panic(&reducerParseError{se})
			}
			panic(r)
		}
	}()
	prog := Parse(src)
	return prog, nil
}

type reducerParseError struct{ se *SyntaxError }

func (e *reducerParseError) Error() string { return e.se.Msg }
