// ReducerError reports an error produced while evaluating a reducer.
type ReducerError struct {
	Src         string
	Off         int
	Len         int
	Msg         string
	Transformed string
}

func (e *ReducerError) Error() string {
	var b strings.Builder
	b.WriteString("\n  ")
	b.WriteString(e.Src)
	b.WriteString("\n  ")
	b.WriteString(strings.Repeat(" ", e.Off))
	b.WriteString(strings.Repeat("^", e.Len))
	b.WriteString("\n\n")
	if e.Transformed != "" {
