		b.WriteString("\n\n")
	}
	b.WriteString(e.Msg)
	return b.String()
}

// PlainError reports an error without a source frame.
type PlainError struct{ Msg string }

func (e *PlainError) Error() string { return e.Msg }

// transformSource rewrites a reducer argument into the source handed to the
// interpreter. Leading dot paths become member expressions on `x` and a leading
// question mark turns the expression into a filter.
func transformSource(src string) (string, bool) {
	if strings.HasPrefix(src, "?") {
		inner, _ := transformSource(src[1:])
		return "filter((x, i) => apply(" + inner + ", x, i))", true
	}
	if strings.HasPrefix(src, ".") {
		if segs, n, ok := parsePath(src); ok {
			return "x" + renderPath(segs) + src[n:], true
		}
		return "x" + src, true
	}
	return src, false
}

type pathSeg struct {
	name string
	idx  string
	isID bool
}

// parsePath parses `.a.b[0]` style paths. Returns the segments and how many
// bytes were consumed.
func parsePath(src string) ([]pathSeg, int, bool) {
	if !strings.HasPrefix(src, ".") {
		return nil, 0, false
	}
	i := 1
	var segs []pathSeg
	if i >= len(src) {
		return segs, i, true
	}
	c := src[i]
	if isIdentStartByte(c) {
		j := i
		for j < len(src) && isIdentPartByte(src[j]) {
			j++
		}
		segs = append(segs, pathSeg{name: src[i:j], isID: true})
		i = j
	} else if c == '[' {
		j, ok := matchBracket(src, i)
		if !ok {
			return nil, 0, false
		}
		segs = append(segs, pathSeg{idx: src[i+1 : j]})
		i = j + 1
	} else {
		return nil, 0, false
	}
	for i < len(src) {
		if src[i] == '.' {
			j := i + 1
			if j < len(src) && isIdentStartByte(src[j]) {
				k := j
				for k < len(src) && isIdentPartByte(src[k]) {
					k++
				}
				segs = append(segs, pathSeg{name: src[j:k], isID: true})
				i = k
				continue
			}
			return nil, 0, false
		}
		if src[i] == '[' {
			j, ok := matchBracket(src, i)
			if !ok {
