// strictError builds the error reported when a strict mode reserved word is
// used as an identifier.
func strictError(t Tok) *PlainError {
	line := 211 + t.Line - 1
	col := t.Col
	if t.Line == 1 {
		col = 13 + t.Col
	}
	return &PlainError{Msg: "SyntaxError: SyntaxError: Unexpected strict mode reserved word at " + itoa(line) + ":" + itoa(col)}
}

// compileReducer parses a reducer source.
func compileReducer(src string) (prog *Program, err error) {
	defer func() {
		if r := recover(); r != nil {
			if se, ok := r.(*SyntaxError); ok {
				err = &parseFail{se}
				return
			}
			panic(r)
		}
	}()
	prog = Parse(src)
	return prog, nil
}

