// PrintLine writes a raw line.
func (rt *Runtime) PrintLine(s string) {
	rt.Out.Write([]byte(s + "\n"))
}

// Flush flushes pending output.
func (rt *Runtime) Flush() {}

// PlainStringify renders a value without inlining, like JSON.stringify with a
// two space indent.
func (rt *Runtime) PlainStringify(v Value) string {
	var sb strings.Builder
	plainWrite(v, &sb, "")
	return sb.String()
}

func plainWrite(v Value, sb *strings.Builder, indent string) {
	switch t := v.(type) {
	case Undef:
		sb.WriteString("null")
	case nil:
		sb.WriteString("null")
	case Null:
		sb.WriteString("null")
	case Bool:
		if t {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
