cat > internal/yaml/yaml.go <<'EOF'
package yaml

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// Error is a YAML parsing error rendered with a source frame.
type Error struct {
	Line int
	Col  int
	Msg  string
	Src  []string
}

func (e *Error) Error() string {
	prefix := fmt.Sprintf("> %2d | ", e.Line)
	sp := strings.Repeat(" ", len(prefix))
	var b strings.Builder
	fmt.Fprintf(&b, "[%d:%d] %s\n", e.Line, e.Col, e.Msg)
	if e.Line-1 >= 0 && e.Line-1 < len(e.Src) {
		b.WriteString(prefix + e.Src[e.Line-1] + "\n")
		b.WriteString(sp + strings.Repeat(" ", e.Col-1) + "^\n")
	}
	return b.String()
}

type parser struct {
	lines []string
	i     int
}

// Parse parses a YAML document into a generic value (maps, arrays, scalars).
func Parse(src string) (interface{}, error) {
	p := &parser{lines: strings.Split(strings.ReplaceAll(src, "\r\n", "\n"), "\n")}
	return p.parseBlock(0)
}

func (p *parser) err(line, col int, msg string) error {
	return &Error{Line: line, Col: col, Msg: msg, Src: p.lines}
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func isBlank(s string) bool { return strings.TrimSpace(s) == "" }

// parseBlock parses a block node at the given indentation.
func (p *parser) parseBlock(minIndent int) (interface{}, error) {
	// find the first non blank, non comment line
	idx := -1
	ind := 0
	for i := 0; i < len(p.lines); i++ {
		if isBlank(p.lines[i]) {
			continue
		}
		t := strings.TrimSpace(p.lines[i])
		if strings.HasPrefix(t, "#") {
			continue
		}
		idx = i
		ind = indentOf(p.lines[i])
		break
	}
	if idx < 0 {
		return nil, nil
	}
	if ind < minIndent {
		return nil, nil
	}
	line := p.lines[idx]
	t := strings.TrimSpace(line)
	if strings.HasPrefix(t, "- ") || t == "-" {
		return p.parseSeq(idx, ind)
	}
	return p.parseMap(idx, ind)
}

func (p *parser) parseSeq(start, indent int) (interface{}, error) {
	out := []interface{}{}
	i := start
	for i < len(p.lines) {
		line := p.lines[i]
		if isBlank(line) {
			i++
			continue
		}
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") {
			i++
			continue
		}
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, p.err(i+1, ind+1, "unexpected indentation")
		}
		if !strings.HasPrefix(t, "-") {
			break
		}
		rest := strings.TrimSpace(strings.TrimPrefix(t, "-"))
		if rest == "" {
			i++
			v, err := p.parseBlock(indent + 1)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
			continue
		}
		if strings.Contains(rest, ":") && !strings.HasPrefix(rest, "[") && !strings.HasPrefix(rest, "{") &&
			!strings.HasPrefix(rest, "\"") && !strings.HasPrefix(rest, "'") {
			// inline mapping start
			p.i = i
			p.lines[i] = strings.Repeat(" ", indentOf(line)+2) + rest
			m, err := p.parseMap(i, indentOf(line)+2)
			if err != nil {
				return nil, err
			}
			out = append(out, m)
			i++
			continue
		}
		v, err := parseScalar(rest, i+1, p)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
		i++
	}
	return out, nil
}

func (p *parser) parseMap(start, indent int) (interface{}, error) {
	out := map[string]interface{}{}
	keys := []string{}
	i := start
	for i < len(p.lines) {
		line := p.lines[i]
		if isBlank(line) {
			i++
			continue
		}
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") {
			i++
			continue
		}
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, p.err(i+1, ind+1, "unexpected indentation")
		}
		ci := strings.Index(t, ":")
		if ci < 0 {
			return nil, p.err(i+1, ind+1, "could not find expected ':'")
		}
		key := strings.TrimSpace(t[:ci])
		key = unquote(key)
		rest := strings.TrimSpace(t[ci+1:])
		if rest == "" {
			// nested block
			j := i + 1
			nested := 0
			for j < len(p.lines) {
				if isBlank(p.lines[j]) {
					j++
					continue
				}
				tt := strings.TrimSpace(p.lines[j])
				if strings.HasPrefix(tt, "#") {
					j++
					continue
				}
				nested = indentOf(p.lines[j])
				break
			}
			if j >= len(p.lines) || nested <= indent {
				out[key] = nil
				keys = append(keys, key)
				i++
				continue
			}
			p.i = j
			v, err := p.parseBlock(nested)
			if err != nil {
				return nil, err
			}
			out[key] = v
			keys = append(keys, key)
			i = j
			continue
		}
		if rest == "|" || rest == ">" || rest == "|-" || rest == ">-" || rest == "|+" || rest == ">+" {
			var b strings.Builder
			j := i + 1
			for j < len(p.lines) {
				if isBlank(p.lines[j]) {
					j++
					continue
				}
				if indentOf(p.lines[j]) <= indent {
					break
				}
				b.WriteString(strings.TrimSpace(p.lines[j]) + "\n")
				j++
			}
			s := b.String()
			if strings.HasPrefix(rest, ">") {
				s = strings.Join(strings.Fields(strings.TrimSuffix(s, "\n")), " ") + "\n"
			}
			if strings.HasSuffix(rest, "-") {
				s = strings.TrimSuffix(s, "\n")
			}
			out[key] = s
			keys = append(keys, key)
			i = j
			continue
		}
		v, err := parseScalar(rest, i+1, p)
		if err != nil {
			return nil, err
		}
		out[key] = v
		keys = append(keys, key)
		i++
	}
	return out, nil
}

func unquote(s string) string {
	if len(s) >= 2 && (s[0] == '"' && s[len(s)-1] == '"' || s[0] == '\'' && s[len(s)-1] == '\'') {
		return s[1 : len(s)-1]
	}
	return s
}

func parseScalar(s string, line int, p *parser) (interface{}, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	if strings.HasPrefix(s, "#") {
		return nil, nil
	}
	switch s {
	case "null", "~", "Null", "NULL":
		return nil, nil
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON":
		return true, nil
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF":
		return false, nil
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return unquote(s), nil
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return unquote(s), nil
	}
	if strings.HasPrefix(s, "[") {
