		return s[1 : len(s)-1]
	}
	return s
}

func parseScalar(s string, line int, p *parser) (interface{}, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	if strings.HasPrefix(s, "#") {
		return nil, nil
	}
	switch s {
	case "null", "~", "Null", "NULL":
		return nil, nil
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON":
		return true, nil
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF":
		return false, nil
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return unquote(s), nil
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return unquote(s), nil
	}
	if strings.HasPrefix(s, "[") {
		return parseFlowSeq(s, line, p)
	}
	if strings.HasPrefix(s, "{") {
		return parseFlowMap(s, line, p)
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return float64(i), nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	return s, nil
}

func parseFlowSeq(s string, line int, p *parser) (interface{}, error) {
	if !strings.HasSuffix(s, "]") {
		return nil, p.err(line, strings.Index(s, "[")+2, "sequence end token ']' not found")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := []interface{}{}
	if inner == "" {
		return out, nil
	}
	for _, part := range splitFlow(inner) {
		v, err := parseScalar(strings.TrimSpace(part), line, p)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, nil
}

func parseFlowMap(s string, line int, p *parser) (interface{}, error) {
	if !strings.HasSuffix(s, "}") {
		return nil, p.err(line, strings.Index(s, "{")+2, "mapping end token '}' not found")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := map[string]interface{}{}
	if inner == "" {
		return out, nil
	}
	for _, part := range splitFlow(inner) {
		ci := strings.Index(part, ":")
		if ci < 0 {
			return nil, p.err(line, 1, "could not find expected ':'")
		}
		k := unquote(strings.TrimSpace(part[:ci]))
		v, err := parseScalar(strings.TrimSpace(part[ci+1:]), line, p)
		if err != nil {
			return nil, err
		}
		out[k] = v
	}
	return out, nil
}

func splitFlow(s string) []string {
	var parts []string
	depth := 0
	start := 0
	q := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				q = 0
			}
			continue
		}
		switch c {
		case '"', '\'':
			q = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, s[start:i])
				start = i + 1
			}
		}
	}
	parts = append(parts, s[start:])
	return parts
}

// Stringify renders a value as YAML.
func Stringify(v interface{}) string {
	var b strings.Builder
	writeYAML(&b, v, "", false)
	return strings.TrimSuffix(b.String(), "\n")
}

func writeYAML(b *strings.Builder, v interface{}, indent string, inSeq bool) {
	switch t := v.(type) {
	case nil:
		b.WriteString("null\n")
	case bool:
		if t {
			b.WriteString("true\n")
		} else {
			b.WriteString("false\n")
		}
	case int:
		b.WriteString(strconv.Itoa(t) + "\n")
	case float64:
		b.WriteString(formatNum(t) + "\n")
	case string:
		b.WriteString(t + "\n")
	case []interface{}:
		if len(t) == 0 {
			b.WriteString("[]\n")
			return
		}
		for _, it := range t {
			b.WriteString(indent + "- ")
			writeYAML(b, it, indent+"  ", true)
		}
	case map[string]interface{}:
		if len(t) == 0 {
			b.WriteString("{}\n")
			return
		}
		for _, k := range keysOf(t) {
			b.WriteString(indent + k + ": ")
			writeYAML(b, t[k], indent+"  ", false)
		}
	}
}

func formatNum(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 0) {
		return ".inf"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func keysOf(m map[string]interface{}) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

