// Error is a YAML parsing error rendered with a source frame.
type Error struct {
	Line int
	Col  int
	Msg  string
	Src  []string
}

func (e *Error) Error() string {
	prefix := fmt.Sprintf("> %2d | ", e.Line)
	sp := strings.Repeat(" ", len(prefix))
	var b strings.Builder
	fmt.Fprintf(&b, "[%d:%d] %s\n", e.Line, e.Col, e.Msg)
	if e.Line-1 >= 0 && e.Line-1 < len(e.Src) {
		b.WriteString(prefix + e.Src[e.Line-1] + "\n")
		b.WriteString(sp + strings.Repeat(" ", e.Col-1) + "^\n")
	}
	return b.String()
}

type parser struct {
	lines []string
}

// Parse parses a YAML document.
func Parse(src string) (engine.Value, error) {
	src = strings.ReplaceAll(src, "\r\n", "\n")
	p := &parser{lines: strings.Split(src, "\n")}
	return p.parseBlock(0)
}

func (p *parser) err(line, col int, msg string) error {
	return &Error{Line: line, Col: col, Msg: msg, Src: p.lines}
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func isBlank(s string) bool { return strings.TrimSpace(s) == "" }

func (p *parser) parseBlock(minIndent int) (engine.Value, error) {
	idx := -1
	ind := 0
	for i := 0; i < len(p.lines); i++ {
		if isBlank(p.lines[i]) {
			continue
		}
		t := strings.TrimSpace(p.lines[i])
		if strings.HasPrefix(t, "#") {
			continue
		}
		idx = i
		ind = indentOf(p.lines[i])
		break
	}
	if idx < 0 {
		return engine.Undef{}, nil
	}
	if ind < minIndent {
		return engine.Undef{}, nil
	}
	t := strings.TrimSpace(p.lines[idx])
	if strings.HasPrefix(t, "- ") || t == "-" {
		return p.parseSeq(idx, ind)
	}
	return p.parseMap(idx, ind)
}

func (p *parser) parseSeq(start, indent int) (engine.Value, error) {
	out := &engine.Arr{}
	i := start
	for i < len(p.lines) {
		line := p.lines[i]
		if isBlank(line) {
			i++
			continue
		}
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") {
			i++
			continue
		}
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, p.err(i+1, ind+1, "unexpected indentation")
		}
		if !strings.HasPrefix(t, "-") {
			break
		}
		rest := strings.TrimSpace(strings.TrimPrefix(t, "-"))
		if rest == "" {
			i++
			v, err := p.parseBlock(indent + 1)
			if err != nil {
				return nil, err
			}
			out.Items = append(out.Items, v)
			continue
		}
		if isMapStart(rest) {
			p.lines[i] = strings.Repeat(" ", indentOf(line)+2) + rest
			m, err := p.parseMap(i, indentOf(line)+2)
			if err != nil {
				return nil, err
			}
			out.Items = append(out.Items, m)
			i++
			continue
		}
		v, err := parseScalar(rest, i+1, p)
		if err != nil {
			return nil, err
		}
		out.Items = append(out.Items, v)
		i++
	}
	return out, nil
}

func isMapStart(s string) bool {
	if strings.HasPrefix(s, "[") || strings.HasPrefix(s, "{") ||
		strings.HasPrefix(s, "\"") || strings.HasPrefix(s, "'") {
		return false
	}
	ci := strings.Index(s, ":")
	if ci < 0 {
		return false
	}
	// a colon must be followed by a space or end
	return ci+1 >= len(s) || s[ci+1] == ' '
}

func (p *parser) parseMap(start, indent int) (engine.Value, error) {
	out := engine.NewObj(nil)
	i := start
	for i < len(p.lines) {
		line := p.lines[i]
		if isBlank(line) {
			i++
			continue
		}
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") {
			i++
			continue
		}
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, p.err(i+1, ind+1, "unexpected indentation")
		}
		ci := findColon(t)
		if ci < 0 {
			return nil, p.err(i+1, ind+1, "could not find expected ':'")
		}
		key := unquote(strings.TrimSpace(t[:ci]))
		rest := strings.TrimSpace(t[ci+1:])
		if rest == "" {
			j := i + 1
			nested := -1
			for j < len(p.lines) {
				if isBlank(p.lines[j]) {
					j++
					continue
				}
				tt := strings.TrimSpace(p.lines[j])
				if strings.HasPrefix(tt, "#") {
					j++
					continue
				}
				nested = indentOf(p.lines[j])
				break
			}
			if j >= len(p.lines) || nested <= indent {
				out.Set(key, engine.Undef{})
				i++
				continue
			}
			v, err := p.parseBlock(nested)
			if err != nil {
				return nil, err
			}
			out.Set(key, v)
			i = j
			continue
		}
		if rest == "|" || rest == ">" || rest == "|-" || rest == ">-" || rest == "|+" || rest == ">+" {
			var b strings.Builder
			j := i + 1
			for j < len(p.lines) {
				if isBlank(p.lines[j]) {
					j++
					continue
				}
				if indentOf(p.lines[j]) <= indent {
					break
				}
				b.WriteString(strings.TrimSpace(p.lines[j]) + "\n")
				j++
			}
			s := b.String()
			if strings.HasPrefix(rest, ">") {
				s = strings.Join(strings.Fields(strings.TrimSuffix(s, "\n")), " ") + "\n"
			}
			if strings.HasSuffix(rest, "-") {
				s = strings.TrimSuffix(s, "\n")
			}
			out.Set(key, engine.Str(s))
			i = j
			continue
		}
		v, err := parseScalar(rest, i+1, p)
		if err != nil {
			return nil, err
		}
		out.Set(key, v)
		i++
	}
	return out, nil
}

func findColon(s string) int {
	q := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				q = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			q = c
			continue
		}
		if c == ':' {
			return i
		}
	}
	return -1
}

func unquote(s string) string {
	if len(s) >= 2 && (s[0] == '"' && s[len(s)-1] == '"' || s[0] == '\'' && s[len(s)-1] == '\'') {
		return s[1 : len(s)-1]
	}
	return s
}

func parseScalar(s string, line int, p *parser) (engine.Value, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return engine.Undef{}, nil
	}
	if strings.HasPrefix(s, "#") {
		return engine.Undef{}, nil
	}
	switch s {
	case "null", "~", "Null", "NULL":
		return engine.Null{}, nil
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON":
		return engine.Bool(true), nil
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF":
		return engine.Bool(false), nil
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if v, err := engine.UnquoteJSON(s); err == nil {
			return engine.Str(v), nil
		}
		return engine.Str(s[1 : len(s)-1]), nil
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return engine.Str(strings.ReplaceAll(s[1:len(s)-1], "''", "'")), nil
	}
	if strings.HasPrefix(s, "[") {
		return parseFlowSeq(s, line, p)
	}
	if strings.HasPrefix(s, "{") {
		return parseFlowMap(s, line, p)
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return float64(i), nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	return engine.Str(s), nil
}

func parseFlowSeq(s string, line int, p *parser) (engine.Value, error) {
	if !strings.HasSuffix(s, "]") {
		return nil, p.err(line, strings.Index(s, "[")+2, "sequence end token ']' not found")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := &engine.Arr{}
	if inner == "" {
		return out, nil
	}
	for _, part := range splitFlow(inner) {
		v, err := parseScalar(strings.TrimSpace(part), line, p)
		if err != nil {
			return nil, err
		}
		out.Items = append(out.Items, v)
	}
	return out, nil
}

func parseFlowMap(s string, line int, p *parser) (engine.Value, error) {
	if !strings.HasSuffix(s, "}") {
		return nil, p.err(line, strings.Index(s, "{")+2, "mapping end token '}' not found")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := engine.NewObj(nil)
	if inner == "" {
		return out, nil
	}
	for _, part := range splitFlow(inner) {
		ci := findColon(part)
		if ci < 0 {
			return nil, p.err(line, 1, "could not find expected ':'")
		}
		k := unquote(strings.TrimSpace(part[:ci]))
		v, err := parseScalar(strings.TrimSpace(part[ci+1:]), line, p)
		if err != nil {
			return nil, err
		}
		out.Set(k, v)
	}
	return out, nil
}

func splitFlow(s string) []string {
	var parts []string
	depth := 0
	start := 0
	q := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				q = 0
			}
			continue
		}
		switch c {
		case '"', '\'':
			q = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, s[start:i])
				start = i + 1
			}
		}
	}
	parts = append(parts, s[start:])
	return parts
}

// Stringify renders a value as YAML.
func Stringify(v engine.Value) string {
	var b strings.Builder
	writeYAML(&b, v, "")
	return strings.TrimSuffix(b.String(), "\n")
}

func writeYAML(b *strings.Builder, v engine.Value, indent string) {
	switch t := v.(type) {
	case nil, engine.Undef:
		b.WriteString("null\n")
	case engine.Null:
		b.WriteString("null\n")
	case engine.Bool:
		if t {
			b.WriteString("true\n")
		} else {
			b.WriteString("false\n")
		}
	case engine.Str:
		b.WriteString(string(t) + "\n")
	case float64:
		b.WriteString(formatNum(t) + "\n")
	case *engine.RawNum:
		b.WriteString(formatNum(t.V) + "\n")
	case *engine.Arr:
		if len(t.Items) == 0 {
			b.WriteString("[]\n")
			return
		}
		for _, it := range t.Items {
			b.WriteString(indent + "- ")
			writeYAML(b, it, indent+"  ")
		}
	case *engine.Obj:
		if len(t.props) == 0 {
			b.WriteString("{}\n")
			return
		}
		for _, p := range t.props {
			b.WriteString(indent + p.Key + ": ")
			writeYAML(b, p.Val, indent+"  ")
		}
	default:
		b.WriteString(engine.ToString(nil, v) + "\n")
	}
}

func formatNum(f float64) string {
	if math.IsNaN(f) {
		return ".nan"
	}
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}
