package toml

import (
	"strconv"
	"strings"

	"github.com/antonmedv/fx/internal/engine"
)

// ToJSON converts a TOML document to a JSON value.
func ToJSON(src []byte) (engine.Value, error) {
	lines := strings.Split(strings.ReplaceAll(string(src), "\r\n", "\n"), "\n")
	root := engine.NewObj(nil)
	cur := root
	for _, line := range lines {
		t := strings.TrimSpace(line)
		if t == "" || strings.HasPrefix(t, "#") {
			continue
		}
		if strings.HasPrefix(t, "[") {
			if strings.HasPrefix(t, "[[") {
				name := strings.TrimSuffix(strings.TrimPrefix(t, "[["), "]]")
				arr := &engine.Arr{}
				parent, ok := cur.Get(name)
				if ok {
					if a, ok := parent.(*engine.Arr); ok {
						arr = a
					}
				}
				tbl := engine.NewObj(nil)
				arr.Items = append(arr.Items, tbl)
				cur.Set(name, arr)
				cur = tbl
				continue
			}
			name := strings.TrimSuffix(strings.TrimPrefix(t, "["), "]")
			tbl := engine.NewObj(nil)
			cur.Set(name, tbl)
			cur = tbl
			continue
		}
		eq := strings.Index(t, "=")
		if eq < 0 {
			continue
		}
		key := strings.TrimSpace(t[:eq])
		key = strings.Trim(key, "\"'")
		val := parseTOMLValue(strings.TrimSpace(t[eq+1:]))
		cur.Set(key, val)
	}
	return root, nil
}

func parseTOMLValue(s string) engine.Value {
	if s == "" {
		return engine.Undef{}
	}
	if strings.HasPrefix(s, "\"") {
		if v, err := engine.UnquoteJSON(s); err == nil {
			return engine.Str(v)
		}
		return engine.Str(strings.Trim(s, "\""))
	}
	if strings.HasPrefix(s, "'") {
		return engine.Str(strings.Trim(s, "'"))
	}
	if strings.HasPrefix(s, "[") {
		inner := strings.TrimSuffix(strings.TrimPrefix(s, "["), "]")
		arr := &engine.Arr{}
		for _, part := range strings.Split(inner, ",") {
			if strings.TrimSpace(part) == "" {
				continue
			}
			arr.Items = append(arr.Items, parseTOMLValue(strings.TrimSpace(part)))
		}
		return arr
	}
	switch s {
	case "true":
		return engine.Bool(true)
	case "false":
		return engine.Bool(false)
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return float64(i)
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}
	return engine.Str(s)
}
