			return nil, p.err(i+1, ind+1, "could not find expected ':'")
		}
		key := unquote(strings.TrimSpace(t[:ci]))
		rest := strings.TrimSpace(t[ci+1:])
		if rest == "" {
			j := i + 1
			nested := -1
			for j < len(p.lines) {
				if isBlank(p.lines[j]) {
					j++
					continue
				}
				tt := strings.TrimSpace(p.lines[j])
				if strings.HasPrefix(tt, "#") {
					j++
					continue
				}
				nested = indentOf(p.lines[j])
				break
			}
			if j >= len(p.lines) || nested <= indent {
				out.Set(key, engine.Undef{})
				i++
				continue
			}
			v, err := p.parseBlock(nested)
			if err != nil {
				return nil, err
			}
			out.Set(key, v)
			i = j
			continue
		}
		if rest == "|" || rest == ">" || rest == "|-" || rest == ">-" || rest == "|+" || rest == ">+" {
			var b strings.Builder
			j := i + 1
			for j < len(p.lines) {
				if isBlank(p.lines[j]) {
					j++
					continue
				}
				if indentOf(p.lines[j]) <= indent {
					break
				}
				b.WriteString(strings.TrimSpace(p.lines[j]) + "\n")
				j++
			}
			s := b.String()
			if strings.HasPrefix(rest, ">") {
				s = strings.Join(strings.Fields(strings.TrimSuffix(s, "\n")), " ") + "\n"
			}
			if strings.HasSuffix(rest, "-") {
				s = strings.TrimSuffix(s, "\n")
			}
			out.Set(key, engine.Str(s))
			i = j
			continue
		}
		v, err := parseScalar(rest, i+1, p)
		if err != nil {
			return nil, err
		}
		out.Set(key, v)
		i++
	}
	return out, nil
}

func findColon(s string) int {
	q := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				q = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			q = c
			continue
		}
		if c == ':' {
			return i
		}
	}
	return -1
}

func unquote(s string) string {
	if len(s) >= 2 && (s[0] == '"' && s[len(s)-1] == '"' || s[0] == '\'' && s[len(s)-1] == '\'') {
		return s[1 : len(s)-1]
	}
	return s
}

func parseScalar(s string, line int, p *parser) (engine.Value, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return engine.Undef{}, nil
	}
	if strings.HasPrefix(s, "#") {
		return engine.Undef{}, nil
	}
	switch s {
	case "null", "~", "Null", "NULL":
		return engine.Null{}, nil
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON":
		return engine.Bool(true), nil
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF":
		return engine.Bool(false), nil
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if v, err := engine.UnquoteJSON(s); err == nil {
			return engine.Str(v), nil
		}
		return engine.Str(s[1 : len(s)-1]), nil
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return engine.Str(strings.ReplaceAll(s[1:len(s)-1], "''", "'")), nil
	}
	if strings.HasPrefix(s, "[") {
		return parseFlowSeq(s, line, p)
	}
	if strings.HasPrefix(s, "{") {
		return parseFlowMap(s, line, p)
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return float64(i), nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	return engine.Str(s), nil
}

func parseFlowSeq(s string, line int, p *parser) (engine.Value, error) {
	if !strings.HasSuffix(s, "]") {
		return nil, p.err(line, strings.Index(s, "[")+2, "sequence end token ']' not found")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := &engine.Arr{}
	if inner == "" {
		return out, nil
	}
	for _, part := range splitFlow(inner) {
		v, err := parseScalar(strings.TrimSpace(part), line, p)
		if err != nil {
			return nil, err
		}
		out.Items = append(out.Items, v)
	}
	return out, nil
}

func parseFlowMap(s string, line int, p *parser) (engine.Value, error) {
	if !strings.HasSuffix(s, "}") {
		return nil, p.err(line, strings.Index(s, "{")+2, "mapping end token '}' not found")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := engine.NewObj(nil)
	if inner == "" {
		return out, nil
	}
	for _, part := range splitFlow(inner) {
		ci := findColon(part)
		if ci < 0 {
			return nil, p.err(line, 1, "could not find expected ':'")
		}
		k := unquote(strings.TrimSpace(part[:ci]))
		v, err := parseScalar(strings.TrimSpace(part[ci+1:]), line, p)
		if err != nil {
			return nil, err
		}
		out.Set(k, v)
	}
	return out, nil
}

func splitFlow(s string) []string {
	var parts []string
	depth := 0
	start := 0
	q := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				q = 0
			}
			continue
		}
		switch c {
		case '"', '\'':
			q = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, s[start:i])
				start = i + 1
			}
		}
	}
	parts = append(parts, s[start:])
	return parts
}

// Stringify renders a value as YAML.
func Stringify(v engine.Value) string {
	var b strings.Builder
	writeYAML(&b, v, "")
	return strings.TrimSuffix(b.String(), "\n")
}

func writeYAML(b *strings.Builder, v engine.Value, indent string) {
	switch t := v.(type) {
	case nil, engine.Undef:
		b.WriteString("null\n")
	case engine.Null:
		b.WriteString("null\n")
	case engine.Bool:
		if t {
			b.WriteString("true\n")
		} else {
			b.WriteString("false\n")
		}
	case engine.Str:
		b.WriteString(string(t) + "\n")
	case float64:
		b.WriteString(formatNum(t) + "\n")
	case *engine.RawNum:
		b.WriteString(formatNum(t.V) + "\n")
	case *engine.Arr:
		if len(t.Items) == 0 {
			b.WriteString("[]\n")
			return
		}
		for _, it := range t.Items {
			b.WriteString(indent + "- ")
			writeYAML(b, it, indent+"  ")
		}
	case *engine.Obj:
		if len(t.props) == 0 {
			b.WriteString("{}\n")
			return
		}
		for _, p := range t.props {
			b.WriteString(indent + p.Key + ": ")
			writeYAML(b, p.Val, indent+"  ")
		}
	default:
		b.WriteString(engine.ToString(nil, v) + "\n")
	}
}

func formatNum(f float64) string {
	if math.IsNaN(f) {
		return ".nan"
	}
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}
