// UnquoteJSON decodes a double quoted JSON string body.
func UnquoteJSON(s string) (string, error) {
	if len(s) < 2 || s[0] != '"' || s[len(s)-1] != '"' {
		return "", errSyntax2("invalid string")
	}
	return unquoteStr(s[1:len(s)-1], '"')
