func (e *errSyntax2) Error() string { return e.msg }

// YAMLParse parses a YAML document into JavaScript values.
func (rt *Runtime) YAMLParse(s string) (Value, error) {
	v, err := yaml.Parse(s)
	if err != nil {
		return nil, err
	}
	return convertYAML(v), nil
}

func convertYAML(v Value) Value {
	switch t := v.(type) {
	case *Obj:
		o := NewObj(nil)
		o.cls = "Object"
		for _, p := range t.props {
			o.Set(p.Key, convertYAML(p.Val))
		}
		return o
	case *Arr:
		a := &Arr{}
		for _, it := range t.Items {
			a.Items = append(a.Items, convertYAML(it))
		}
		return a
	}
	return v
}

// YAMLStringify renders a value as YAML.
func (rt *Runtime) YAMLStringify(v Value) string {
	return yaml.Stringify(v)
}
