			if len(reducers) == 0 {
				runInteractive(vals, o)
			}
			if len(vals) > 0 {
				start(os.Stdout, vals, reducers, o)
			}
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		if v == nil {
			break
		}
		vals = append(vals, v)
	}
	if len(reducers) == 0 {
		runInteractive(vals, o)
		return
	}
	if o.slurp {
		arr := make([]interface{}, 0, len(vals))
		for _, v := range vals {
			arr = append(arr, v)
		}
		vals = []interface{}{arr}
	}
	start(os.Stdout, vals, reducers, o)
}

func printThemes() {
	for _, t := range themeNames {
		fmt.Fprintln(os.Stderr, "")
