}

func knownTheme(name string) bool {
	for _, t := range themeNames {
		if t == name {
			return true
		}
	}
	return false
}

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

