package gol

import (
	"fmt"
	"io"
	"math/rand"
	"time"
)

// Run plays Conway's game of life, rendering two rows of cells per line using
// the half block characters.
func Run(w io.Writer) {
	const cols = 80
	const rows = 46
	grid := make([][]bool, rows)
	for y := range grid {
		grid[y] = make([]bool, cols)
		for x := range grid[y] {
			grid[y][x] = rand.Intn(2) == 1
		}
	}
	io.WriteString(w, "\x1b[2J\x1b[?25l\x1b[H")
	for {
		io.WriteString(w, "\x1b[H")
		for y := 0; y < rows; y += 2 {
			var b []byte
			for x := 0; x < cols; x++ {
				top := grid[y][x]
				bottom := false
				if y+1 < rows {
					bottom = grid[y+1][x]
				}
				switch {
				case top && bottom:
					b = append(b, []byte("█")...)
				case top:
					b = append(b, []byte("▀")...)
				case bottom:
					b = append(b, []byte("▄")...)
				default:
					b = append(b, ' ')
				}
			}
			fmt.Fprintln(w, string(b))
		}
		grid = step(grid)
		time.Sleep(33 * time.Millisecond)
	}
}

// step advances the simulation by one generation.
func step(g [][]bool) [][]bool {
	rows := len(g)
	cols := len(g[0])
	out := make([][]bool, rows)
	for y := range out {
		out[y] = make([]bool, cols)
		for x := range out[y] {
			n := 0
			for dy := -1; dy <= 1; dy++ {
				for dx := -1; dx <= 1; dx++ {
					if dy == 0 && dx == 0 {
						continue
					}
					yy, xx := y+dy, x+dx
					if yy < 0 || yy >= rows || xx < 0 || xx >= cols {
						continue
					}
					if g[yy][xx] {
						n++
					}
				}
			}
			if g[y][x] {
				out[y][x] = n == 2 || n == 3
			} else {
				out[y][x] = n == 3
			}
		}
	}
	return out
}
