}

func currentStyle() *style {
	s, ok := styles[os.Getenv("FX_THEME")]
	if !ok {
		return styles["0"]
	}
	return s
}

type node struct {
	key       string
	val       interface{}
	children  []*node
	collapsed bool
	isRoot    bool
}

// Run starts the interactive viewer on the given tty.
func Run(out io.Writer, vals []interface{}, noInline bool, name string) {
	st := currentStyle()
	root := &node{isRoot: true}
	if len(vals) == 1 {
		root.val = vals[0]
	} else if len(vals) > 1 {
		root.val = vals
	} else {
		root.val = nil
	}
	root.children = children(root.val)
	view := &viewer{st: st, name: name, root: root, w: out, cursor: 0, top: 0}
	view.loop()
}

type viewer struct {
	st      *style
	name    string
	root    *node
	w       io.Writer
	cursor  int
	top     int
	search  string
	rows    int
	cols    int
	force   bool
	match   []int
	matchIx int
}

func children(v interface{}) []*node {
	var out []*node
	switch t := v.(type) {
	case *engineObj:
		for _, p := range t.props {
			n := &node{key: p.Key, val: p.Val}
			n.children = children(p.Val)
			out = append(out, n)
		}
	case *engineArr:
		for i, it := range t.items {
			n := &node{key: strconv.Itoa(i), val: it}
			n.children = children(it)
			out = append(out, n)
		}
	}
	return out
}
