	name    string
	root    *node
	w       io.Writer
	cursor  int
	top     int
	rows    int
	cols    int
	search  string
	searchI string
	matches []int
	matchIx int
	lines   []string
	plain   []string
}

// Run starts the viewer.
func Run(out io.Writer, vals []engine.Value, name string) {
	st := currentStyle()
	root := &node{isRoot: true}
	root.val = nil
	if len(vals) == 1 {
		root.val = vals[0]
	} else if len(vals) > 1 {
		arr := &engine.Arr{}
		for _, v := range vals {
			arr.Items = append(arr.Items, v)
		}
		root.val = arr
	}
	root.children = []*node{}
	switch t := root.val.(type) {
	case *engine.Obj:
		for _, p := range t.props {
			root.children = append(root.children, newNode(p.Key, p.Val))
		}
	case *engine.Arr:
		for i, it := range t.Items {
			root.children = append(root.children, newNode(strconv.Itoa(i), it))
		}
