	v.rows, v.cols = termSize()
	v.loop()
}

func (v *viewer) loop() {
	v.render()
	buf := make([]byte, 256)
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	defer tty.Close()
	setRaw(0)
	defer setCooked(0)
	for {
		n, err := tty.Read(buf)
		if err != nil || n == 0 {
			return
		}
		if !v.handle(buf[:n]) {
			return
		}
		v.render()
	}
}

func (v *viewer) handle(b []byte) bool {
	s := string(b)
	switch s {
	case "q", "\x03", "\x1b":
		if s == "\x1b" {
			return true
		}
		return false
	case "j", "\x1b[B":
		v.cursor++
	case "k", "\x1b[A":
		v.cursor--
	case "\x1b[C", "l":
		v.expand()
	case "\x1b[D", "h":
		v.collapse()
	case "E":
		v.collapseAll()
	case "R", "e":
		v.expandAll()
	case " ":
		v.cursor += v.rows - 1
	case "b":
		v.cursor -= v.rows - 1
	case "G", "\x1b[6~":
		v.cursor = len(v.lines) - 1
	case "g", "\x1b[5~":
		v.cursor = 0
	case "/":
		v.startSearch()
		return true
	case "n":
		v.nextMatch(1)
	case "N":
		v.nextMatch(-1)
	}
	if v.cursor < 0 {
		v.cursor = 0
	}
	if v.cursor > len(v.lines)-1 {
		v.cursor = len(v.lines) - 1
	}
	if v.cursor < 0 {
		v.cursor = 0
	}
	return true
}

func (v *viewer) startSearch() {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	defer tty.Close()
	io.WriteString(v.w, "\r\x1b[30m\x1b[47m/"+v.search+"\x1b[0m\x1b[39m\x1b[49m")
	buf := make([]byte, 8)
	s := v.search
	for {
		n, err := tty.Read(buf)
		if err != nil || n == 0 {
			return
		}
		c := buf[0]
		if c == '\r' || c == '\n' || c == 27 {
			break
		}
		if c == 127 || c == 8 {
			if len(s) > 0 {
				s = s[:len(s)-1]
			}
		} else {
			s += string(buf[:n])
		}
		io.WriteString(v.w, "\r\x1b[30m\x1b[47m/"+s+"\x1b[0m\x1b[39m\x1b[49m")
	}
	v.search = s
	v.matches = nil
	if s != "" {
		for i, p := range v.plain {
			if strings.Contains(p, s) {
				v.matches = append(v.matches, i)
			}
		}
		v.matchIx = 0
		if len(v.matches) > 0 {
			v.cursor = v.matches[0]
		}
	}
}

func (v *viewer) nextMatch(d int) {
	if len(v.matches) == 0 {
		return
	}
	v.matchIx = (v.matchIx + d + len(v.matches)) % len(v.matches)
	v.cursor = v.matches[v.matchIx]
}

func (v *viewer) collapse() {
	if n := v.nodeAt(v.cursor); n != nil && len(n.children) > 0 {
		n.collapsed = true
	}
}

func (v *viewer) expand() {
	if n := v.nodeAt(v.cursor); n != nil {
		n.collapsed = false
	}
}

func (v *viewer) collapseAll() {
	var walk func(n *node)
	walk = func(n *node) {
		for _, c := range n.children {
			if len(c.children) > 1 {
				c.collapsed = true
			}
			walk(c)
		}
	}
	walk(v.root)
}

func (v *viewer) expandAll() {
	var walk func(n *node)
	walk = func(n *node) {
		n.collapsed = false
		for _, c := range n.children {
			walk(c)
		}
	}
	walk(v.root)
}

// lines builds the visible lines.
func (v *viewer) build() {
	v.lines = nil
	v.plain = nil
	var render func(n *node, depth int, last bool)
	render = func(n *node, depth int, last bool) {
		indent := strings.Repeat("  ", depth)
		if n.key != "" {
			if n.isRoot {
				return
			}
			// handled below
		}
	}
	// flatten
	var walk func(n *node, depth int)
	walk = func(n *node, depth int) {
		if n.isRoot {
			for _, c := range n.children {
				walk(c, depth)
			}
			if len(n.children) == 0 {
				v.push(n, depth, false)
			}
			return
		}
		v.push(n, depth, true)
		if n.collapsed {
			return
		}
		for _, c := range n.children {
			walk(c, depth+1)
		}
	}
	walk(v.root, 0)
}

func (v *viewer) push(n *node, depth int, withKey bool) {
	var b strings.Builder
	indent := strings.Repeat("  ", depth)
	b.WriteString(indent)
	var plain strings.Builder
	plain.WriteString(indent)
	if withKey && n.key != "" {
		if v.st.key != "" {
			b.WriteString(v.st.key + engine.QuoteKey(n.key) + v.st.reset)
		} else {
			b.WriteString(engine.QuoteKey(n.key))
		}
		plain.WriteString(engine.QuoteKey(n.key))
		b.WriteString(": ")
		plain.WriteString(": ")
	}
	v.writeNode(&b, &plain, n.val, depth+1)
	b.WriteString(",")
	plain.WriteString(",")
	v.lines = append(v.lines, b.String())
	v.plain = append(v.plain, plain.String())
}

func (v *viewer) writeNode(b, p *strings.Builder, val engine.Value, depth int) {
	st := v.st
	switch t := val.(type) {
	case engine.Str:
		if st.str != "" {
			b.WriteString(st.str + quote(string(t)) + "\x1b[39m")
		} else {
			b.WriteString(quote(string(t)))
		}
		p.WriteString(quote(string(t)))
	case float64:
		if st.num != "" {
			b.WriteString(st.num + engine.NumToString(t) + "\x1b[39m")
		} else {
			b.WriteString(engine.NumToString(t))
		}
		p.WriteString(engine.NumToString(t))
	case *big.Int:
		b.WriteString(t.String())
		p.WriteString(t.String())
	case *engine.RawNum:
		b.WriteString(t.Raw)
		p.WriteString(t.Raw)
	case engine.Bool:
		if st.bool != "" {
			b.WriteString(st.bool + strconv.FormatBool(bool(t)) + "\x1b[39m")
		} else {
			b.WriteString(strconv.FormatBool(bool(t)))
		}
		p.WriteString(strconv.FormatBool(bool(t)))
	case engine.Null:
		if st.null != "" {
			b.WriteString(st.null + "null\x1b[39m")
		} else {
			b.WriteString("null")
		}
		p.WriteString("null")
	case engine.Undef:
		b.WriteString("null")
		p.WriteString("null")
	case *engine.Arr:
		if len(t.Items) == 0 {
			b.WriteString(st.brace + "[]" + st.reset)
			p.WriteString("[]")
			return
		}
		if n := v.nodeOf(t); n != nil && n.collapsed {
			b.WriteString("[" + st.dim + "…\x1b[39m]")
			p.WriteString("[…]")
			return
		}
		b.WriteString(st.brace + "[" + st.reset)
		p.WriteString("[")
	case *engine.Obj:
		if t.Len() == 0 {
			b.WriteString(st.brace + "{}" + st.reset)
			p.WriteString("{}")
			return
		}
		if n := v.nodeOf(t); n != nil && n.collapsed {
			b.WriteString("{" + previewObject(t, st) + st.dim + "…\x1b[39m}")
			p.WriteString("{" + previewPlain(t) + "…}")
			return
		}
		b.WriteString(st.brace + "{" + st.reset)
		p.WriteString("{")
	default:
		b.WriteString(engine.ToString(nil, val))
		p.WriteString(engine.ToString(nil, val))
	}
}

func previewObject(o *engine.Obj, st *style) string {
	var b strings.Builder
	if st.key != "" {
		b.WriteString(st.key + engine.QuoteKey(o.Keys()[0]) + "\x1b[39m")
	} else {
		b.WriteString(engine.QuoteKey(o.Keys()[0]))
	}
	b.WriteString(":")
	first, _ := o.Get(o.Keys()[0])
	b.WriteString(engine.ToString(nil, first))
	b.WriteString(",")
	return b.String()
}

func previewPlain(o *engine.Obj) string {
	k := o.Keys()[0]
	first, _ := o.Get(k)
	return engine.QuoteKey(k) + ":" + engine.ToString(nil, first) + ","
}
EOF
echo ok

