package tui

import (
	"syscall"
	"unsafe"
)

const (
	ioctlGetTermios = 0x5401 // TCGETS
	ioctlSetTermios = 0x5402 // TCSETS
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   uint8
	Cc     [32]uint8
	Ispeed uint32
	Ospeed uint32
}

var saved termios

func ioctl(fd int, req uintptr, arg unsafe.Pointer) error {
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), req, uintptr(arg))
	if e != 0 {
		return e
	}
	return nil
}

func setRaw(fd int) {
	var t termios
	if ioctl(fd, ioctlGetTermios, unsafe.Pointer(&t)) != nil {
		return
	}
	saved = t
	t.Iflag &^= 0x1 | 0x2 | 0x8 | 0x10 | 0x20 | 0x40 | 0x400 | 0x800 | 0x1000
	t.Oflag &^= 0x1
	t.Lflag &^= 0x1 | 0x2 | 0x4 | 0x20 | 0x40 | 0x100 | 0x200 | 0x400 | 0x800 | 0x2000 | 0x8000 | 0x10000 | 0x20000 | 0x40000 | 0x80000
	t.Cflag &^= 0x100 | 0x8
	t.Cflag |= 0x4000
	t.Cc[6] = 1 // VMIN
	t.Cc[5] = 0 // VTIME
	ioctl(fd, ioctlSetTermios, unsafe.Pointer(&t))
}

func setCooked(fd int) {
	ioctl(fd, ioctlSetTermios, unsafe.Pointer(&saved))
}

type winsize struct {
	Row uint16
	Col uint16
	X   uint16
	Y   uint16
}

func termSize() (int, int) {
	var ws winsize
	if ioctl(1, 0x5413, unsafe.Pointer(&ws)) != nil {
		return 24, 80
	}
	if ws.Row == 0 || ws.Col == 0 {
		return 24, 80
	}
	return int(ws.Row), int(ws.Col)
}
