// Run starts the interactive viewer.
func Run(out io.Writer, vals []engine.Value, name string) {
	st := currentStyle()
	root := &node{isRoot: true}
	var val engine.Value
	switch len(vals) {
	case 0:
		val = nil
	case 1:
		val = vals[0]
