		v.render()
	}
	io.WriteString(out, "\x1b[?1049l\x1b[?25h\x1b[?1002l\x1b[?1006l\x1b[?2004l")
}

func (v *viewer) handle(b []byte) bool {
	s := string(b)
	if s == "\x1b" {
