}

func currentStyle() *style {
	s, ok := styles[os.Getenv("FX_THEME")]
	if !ok {
		return styles["0"]
	}
	return s
}

type node struct {
	key       string
	val       engine.Value
	children  []*node
	collapsed bool
	isRoot    bool
	isClose   bool
	parent    *node
}

func newNode(key string, v engine.Value, parent *node) *node {
	n := &node{key: key, val: v, parent: parent}
	switch t := v.(type) {
	case *engine.Obj:
		for _, p := range t.props {
			n.children = append(n.children, newNode(p.Key, p.Val, n))
		}
	case *engine.Arr:
		for i, it := range t.Items {
			n.children = append(n.children, newNode(strconv.Itoa(i), it, n))
		}
	}
	return n
}

type line struct {
	colored string
	plain   string
	node    *node
}

type viewer struct {
	st      *style
	name    string
	root    *node
	w       io.Writer
	tty     *os.File
	cursor  int
	top     int
	rows    int
	cols    int
	search  string
	matches []int
	matchIx int
	lines   []line
	ended   bool
}

// Run starts the interactive viewer.
func Run(out io.Writer, vals []engine.Value, name string) {
	st := currentStyle()
	root := &node{isRoot: true}
	var val engine.Value
	switch len(vals) {
	case 0:
		val = nil
	case 1:
		val = vals[0]
	default:
		arr := &engine.Arr{}
		arr.Items = append(arr.Items, vals...)
		val = arr
	}
	root.val = val
	switch t := val.(type) {
	case *engine.Obj:
		for _, p := range t.props {
			root.children = append(root.children, newNode(p.Key, p.Val, root))
		}
	case *engine.Arr:
		for i, it := range t.Items {
			root.children = append(root.children, newNode(strconv.Itoa(i), it, root))
		}
	}
	v := &viewer{st: st, name: name, root: root, w: out}
	v.rows, v.cols = termSize()
	io.WriteString(out, "\x1b[?25l\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l\x1b[?2004h\x1b[?1002h\x1b[?1006h\x1b[H")
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	v.tty = tty
	defer tty.Close()
	setRaw(int(tty.Fd()))
	defer setCooked(int(tty.Fd()))
	v.render()
	buf := make([]byte, 256)
	for !v.ended {
		n, err := tty.Read(buf)
		if err != nil || n == 0 {
			return
		}
		if !v.handle(buf[:n]) {
			v.ended = true
			break
		}
		if v.ended {
			break
		}
		v.render()
	}
	io.WriteString(out, "\x1b[?1049l\x1b[?25h\x1b[?1002l\x1b[?1006l\x1b[?2004l")
}

func (v *viewer) handle(b []byte) bool {
	s := string(b)
	if s == "\x1b" {
		return true
	}
	switch s {
	case "q", "\x03":
		return false
	case "j", "\x1b[B":
		v.cursor++
	case "k", "\x1b[A":
		v.cursor--
	case "\x1b[C", "l":
		v.expand()
	case "\x1b[D", "h":
		v.collapse()
	case "E":
		v.collapseAll()
	case "R", "e":
		v.expandAll()
	case " ":
		v.cursor += v.rows - 1
	case "b", "\x02":
		v.cursor -= v.rows - 1
	case "G", "\x1b[6~":
		v.cursor = len(v.lines) - 1
	case "g", "\x1b[5~", "\x1b[H":
		v.cursor = 0
	case "/":
		v.doSearch()
	case "n":
		v.nextMatch(1)
	case "N":
		v.nextMatch(-1)
	}
	if v.cursor < 0 {
		v.cursor = 0
	}
	if v.cursor > len(v.lines)-1 {
		v.cursor = len(v.lines) - 1
	}
	if v.cursor < 0 {
		v.cursor = 0
	}
	return true
}

func (v *viewer) collapse() {
	if n := v.lines[v.cursor].node; n != nil && len(n.children) > 0 {
		n.collapsed = true
	}
}

func (v *viewer) expand() {
	if n := v.lines[v.cursor].node; n != nil {
		n.collapsed = false
	}
}

func (v *viewer) collapseAll() {
	var walk func(n *node)
	walk = func(n *node) {
		if len(n.children) > 0 {
			n.collapsed = true
		}
		for _, c := range n.children {
			walk(c)
		}
	}
	for _, c := range v.root.children {
		if len(c.children) > 0 {
			c.collapsed = true
		}
		walk(c)
	}
}

func (v *viewer) expandAll() {
	var walk func(n *node)
	walk = func(n *node) {
		n.collapsed = false
		for _, c := range n.children {
			walk(c)
		}
	}
	walk(v.root)
}

func (v *viewer) doSearch() {
	io.WriteString(v.w, "\r\x1b[30m\x1b[47m/"+v.search+"\x1b[0m\x1b[39m\x1b[49m")
	buf := make([]byte, 8)
	s := v.search
	for {
		n, err := v.tty.Read(buf)
		if err != nil || n == 0 {
			return
		}
		c := buf[0]
		if c == '\r' || c == '\n' || c == 27 {
			break
		}
		if c == 127 || c == 8 {
			if len(s) > 0 {
				s = s[:len(s)-1]
			}
		} else {
			s += string(buf[:n])
		}
		io.WriteString(v.w, "\r\x1b[30m\x1b[47m/"+s+"\x1b[0m\x1b[39m\x1b[49m")
	}
	v.search = s
	v.matches = nil
	if s != "" {
		for i, l := range v.lines {
			if strings.Contains(l.plain, s) {
				v.matches = append(v.matches, i)
			}
		}
		v.matchIx = 0
		if len(v.matches) > 0 {
			v.cursor = v.matches[0]
		}
	}
}

func (v *viewer) nextMatch(d int) {
	if len(v.matches) == 0 {
		return
	}
	v.matchIx = (v.matchIx + d + len(v.matches)) % len(v.matches)
	v.cursor = v.matches[v.matchIx]
}

// buildLines flattens the tree into display lines.
func (v *viewer) buildLines() {
	v.lines = nil
	for _, c := range v.root.children {
		v.walk(c, 0, false)
	}
}

func (v *viewer) walk(n *node, depth int, last bool) {
	indent := strings.Repeat("  ", depth)
	var b strings.Builder
	var p strings.Builder
	b.WriteString(indent)
	p.WriteString(indent)
	if !n.isRoot && n.key != "" {
		if v.st.key != "" {
			b.WriteString(v.st.key + engine.QuoteKey(n.key) + v.st.reset)
		} else {
			b.WriteString(engine.QuoteKey(n.key))
		}
		p.WriteString(engine.QuoteKey(n.key))
		b.WriteString(": ")
		p.WriteString(": ")
	}
	switch t := n.val.(type) {
	case *engine.Obj:
		if t.Len() == 0 {
			b.WriteString(v.st.brace + "{}" + v.st.reset)
			p.WriteString("{}")
		} else if n.collapsed {
			b.WriteString(v.st.brace + "{" + v.st.reset + v.preview(t) + v.st.dim + "…\x1b[39m" + v.st.brace + "}" + v.st.reset)
			p.WriteString("{" + v.previewPlain(t) + "…}")
		} else {
			b.WriteString(v.st.brace + "{" + v.st.reset)
			p.WriteString("{")
		}
	case *engine.Arr:
		if len(t.Items) == 0 {
			b.WriteString(v.st.brace + "[]" + v.st.reset)
			p.WriteString("[]")
		} else if n.collapsed {
			b.WriteString(v.st.brace + "[" + v.st.reset + v.st.dim + "…\x1b[39m" + v.st.brace + "]" + v.st.reset)
			p.WriteString("[…]")
		} else {
			b.WriteString(v.st.brace + "[" + v.st.reset)
			p.WriteString("[")
		}
	default:
		v.scalar(&b, &p, n.val)
	}
	if !last {
		b.WriteString(",")
		p.WriteString(",")
	}
	v.lines = append(v.lines, line{colored: b.String(), plain: p.String(), node: n})
	if n.isRoot {
		return
	}
	if n.collapsed {
		return
	}
	if t, ok := n.val.(*engine.Obj); ok && t.Len() > 0 {
		for i, c := range n.children {
			v.walk(c, depth+1, i == len(n.children)-1)
		}
		v.closeLine(depth, "}", last)
		return
	}
	if t, ok := n.val.(*engine.Arr); ok && len(t.Items) > 0 {
		for i, c := range n.children {
			v.walk(c, depth+1, i == len(n.children)-1)
		}
		v.closeLine(depth, "]", last)
	}
}

func (v *viewer) closeLine(depth int, brace string, last bool) {
	indent := strings.Repeat("  ", depth)
	var b strings.Builder
	var p strings.Builder
	b.WriteString(indent)
	p.WriteString(indent)
	b.WriteString(v.st.brace + brace + v.st.reset)
	p.WriteString(brace)
	if !last {
		b.WriteString(",")
		p.WriteString(",")
	}
	v.lines = append(v.lines, line{colored: b.String(), plain: p.String()})
}

func (v *viewer) preview(o *engine.Obj) string {
	var b strings.Builder
	if len(o.props) == 0 {
		return ""
	}
	k := o.props[0].Key
	if v.st.key != "" {
		b.WriteString(v.st.key + engine.QuoteKey(k) + v.st.reset)
	} else {
		b.WriteString(engine.QuoteKey(k))
	}
	b.WriteString(":")
	first, _ := o.Get(k)
	b.WriteString(v.st.brace)
	var sb strings.Builder
	v.scalar(&b, &strings.Builder{}, first)
	b.WriteString(",")
	return b.String()
}

func (v *viewer) previewPlain(o *engine.Obj) string {
	if len(o.props) == 0 {
		return ""
	}
	k := o.props[0].Key
	first, _ := o.Get(k)
	var b strings.Builder
	v.scalar(&b, &strings.Builder{}, first)
	return engine.QuoteKey(k) + ":" + b.String() + ","
}

func (v *viewer) scalar(b *strings.Builder, p *strings.Builder, val engine.Value) {
	st := v.st
	switch t := val.(type) {
	case engine.Str:
		s := engine.QuoteStr(string(t))
		if st.str != "" {
			b.WriteString(st.str + s + "\x1b[39m")
		} else {
			b.WriteString(s)
		}
		p.WriteString(s)
	case float64:
		s := engine.NumToString(t)
		if st.num != "" {
			b.WriteString(st.num + s + "\x1b[39m")
		} else {
			b.WriteString(s)
		}
		p.WriteString(s)
	case *big.Int:
		b.WriteString(t.String())
		p.WriteString(t.String())
	case *engine.RawNum:
		b.WriteString(t.Raw)
		p.WriteString(t.Raw)
	case engine.Bool:
		s := strconv.FormatBool(bool(t))
		if st.bool != "" {
			b.WriteString(st.bool + s + "\x1b[39m")
		} else {
			b.WriteString(s)
		}
		p.WriteString(s)
	case engine.Null:
		if st.null != "" {
			b.WriteString(st.null + "null\x1b[39m")
		} else {
			b.WriteString("null")
		}
		p.WriteString("null")
	case engine.Undef:
		b.WriteString("null")
		p.WriteString("null")
	default:
		s := engine.ToString(nil, val)
		b.WriteString(s)
		p.WriteString(s)
	}
}

func (v *viewer) render() {
	v.buildLines()
	if v.top > v.cursor {
		v.top = v.cursor
	}
	if v.top > len(v.lines)-v.rows+1 {
		if len(v.lines) >= v.rows-1 {
			v.top = len(v.lines) - v.rows + 1
		} else {
			v.top = 0
		}
	}
	if v.top < 0 {
		v.top = 0
	}
	var b strings.Builder
	b.WriteString("\x1b[H")
	end := v.top + v.rows - 1
	if end > len(v.lines) {
		end = len(v.lines)
	}
	for i := v.top; i < end; i++ {
		if i == v.cursor {
			b.WriteString(v.highlight(v.lines[i].colored))
		} else {
			b.WriteString(v.lines[i].colored)
		}
		b.WriteString("\r\n")
	}
	empty := "\x1b[90m~\x1b[39m"
	for i := end; i < v.top+v.rows-1; i++ {
		b.WriteString(empty)
		b.WriteString("\r\n")
	}
	// status line
	pct := 0
	if len(v.lines) > v.rows {
		pct = v.top * 100 / (len(v.lines) - v.rows + 1)
	}
	status := "\x1b[30m\x1b[47m" + v.path() + "\x1b[0m\x1b[39m\x1b[49m"
	right := fmt.Sprintf("%d%% %s", pct, v.name)
	pad := v.cols - plainWidth(v.path()) - len(right)
	if pad < 0 {
		pad = 0
	}
	b.WriteString(status + strings.Repeat(" ", pad) + right)
	io.WriteString(v.w, b.String())
}

func (v *viewer) path() string {
	if v.cursor >= 0 && v.cursor < len(v.lines) {
		if n := v.lines[v.cursor].node; n != nil && n.key != "" {
			return "." + n.key
		}
	}
	return ""
}

func (v *viewer) highlight(s string) string {
	// highlight the key of the current line with reverse video
	i := strings.Index(s, "\x1b[")
	if i < 0 {
		return s
	}
	j := strings.Index(s[i:], "m")
	if j < 0 {
		return s
	}
	j += i + 1
	return s[:i] + "\x1b[7m" + s[j:]
}

func plainWidth(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		if s[i] == 0x1b {
			for i < len(s) && s[i] != 'm' {
				i++
			}
			continue
		}
		n++
	}
	return n
}
